                          Signaler un problème
                        </button>
                        <p className="text-center text-xs font-semibold text-[#7B8B7D]">
                          {getClaimWindowLabel(order)}
                        </p>
                      </div>
                    </article>
                  ))}
                </div>
              )}
            </section>
          )}

          {!showOrderHistory && isFetching && (
            <div className="space-y-12">
              {Array.from({ length: 2 }).map((_, sectionIndex) => (
                <div key={sectionIndex} className="space-y-6">
                  <div className="souki-skeleton h-6 w-40 rounded-xl" />
                  <div className="grid grid-cols-3 gap-2 md:flex md:gap-4 md:overflow-hidden">
                    {Array.from({ length: 6 }).map((__, index) => (
                      <div
                        key={index}
                        className="souki-skeleton h-[220px] w-full rounded-2xl md:h-[390px] md:w-[12rem] md:shrink-0 md:rounded-[28px]"
                      />
                    ))}
                  </div>
                  <div className="souki-skeleton h-24 rounded-[1.75rem]" />
                </div>
              ))}
            </div>
          )}

          {!showOrderHistory && !isFetching && error && (
            <div className="rounded-[28px] border border-red-200 bg-red-50 p-6 text-red-600">
              {error}
            </div>
          )}

          {!showOrderHistory && !isFetching && !error && (
            <>
              {productsByCategory ? (
                <div
                  ref={revealRef}
                  id="catalogue-products"
                  className="space-y-12 scroll-mt-28"
                >
                  {([
                    { key: "legumes" as const, label: "Légumes", subtitle: "Frais du marché de gros" },
                    { key: "fruits" as const, label: "Fruits", subtitle: "Sucrés et de saison" },
                    { key: "herbes" as const, label: "Herbes", subtitle: "Aromates et fraîcheur" },
                  ] as const).map((section, sectionIndex) => {
                    const items = productsByCategory[section.key]
                    if (items.length === 0) return null
                    return (
                      <section key={section.key} id={`catalogue-cat-${section.key}`} className="scroll-mt-28">
                        <div
                          data-reveal="up"
                          data-delay={String((sectionIndex % 4) + 1)}
                          className="mb-4 flex items-end justify-between"
                        >
                          <div className="flex items-center gap-3">
                            <span className="h-8 w-1.5 shrink-0 rounded-full bg-gradient-to-b from-[#5BD174] to-[#1E8A3C] md:hidden" />
                            <div>
                              <h3 className="text-lg font-bold text-[#264129]">{section.label}</h3>
                              <p className="text-sm text-[#6F8070]">{section.subtitle}</p>
                            </div>
                          </div>
                          <span className="rounded-full bg-[#F0FAF1] px-3 py-1 text-xs font-bold text-[#1E8A3C]">
                            {items.length} produit{items.length > 1 ? "s" : ""}
                          </span>
                        </div>
                        <div className="grid grid-cols-2 gap-3 md:-mx-1 md:flex md:snap-x md:snap-mandatory md:gap-4 md:overflow-x-auto md:px-1 md:pb-3 md:scrollbar-none">
                          {items.map((product, index) => (
                            <div
                              key={product.id}
                              data-reveal="scale"
                              data-delay={String(((sectionIndex * 3 + index) % 4) + 1)}
                              className="w-full md:w-[12rem] md:shrink-0 md:snap-start"
                            >
                              <ProductCard
                                id={product.id}
                                name={product.name}
                                image={product.image}
                                price={product.price}
                                prixKhddarEstime={product.prix_khddar_estime}
                                niveau={product.niveau}
                                unit={product.unit}
                                displayUnit={product.displayUnit}
                                quantityStep={product.quantityStep}
                                stock={product.stock}
                                onView={openProductDetail}
                                variant="minimal"
                                isFavorite={isFavorite(product.id)}
                                onToggleFavorite={() => toggleFavorite(product.id)}
                                onAddToCart={handleAddToCart}
                              />
                            </div>
                          ))}
                        </div>
                      </section>
                    )
                  })}

                  {filteredProducts.length === 0 && (
                    <div className="rounded-[28px] border border-[#E6EFE7] bg-white p-12 text-center">
                      <p className="text-[#6F8070]">Aucun produit disponible pour le moment.</p>
                    </div>
                  )}
                </div>
              ) : productsByLevel ? (
                <div
                  ref={revealRef}
                  id="catalogue-products"
                  className="space-y-12 scroll-mt-28"
                >
                  {([
                    { key: "level1" as const, label: "Essentiels", subtitle: "Les indispensables du quotidien" },
                    { key: "level2" as const, label: "Populaires", subtitle: "Les préférés de nos clients" },
                    { key: "level3" as const, label: "À découvrir", subtitle: "Des pépites à essayer" },
                  ] as const).map((section, sectionIndex) => {
                    const items = productsByLevel[section.key]
                    if (items.length === 0) return null
                    const interlude = sectionBreaks[sectionIndex]
                    return (
                      <Fragment key={section.key}>
                        <section>
                          <div
                            data-reveal="up"
                            data-delay={String((sectionIndex % 4) + 1)}
                            className="mb-4 flex items-end justify-between"
                          >
                            <div className="flex items-center gap-3">
                              <span className="h-8 w-1.5 shrink-0 rounded-full bg-gradient-to-b from-[#5BD174] to-[#1E8A3C] md:hidden" />
                              <div>
                                <h3 className="text-lg font-bold text-[#264129]">{section.label}</h3>
                                <p className="text-sm text-[#6F8070]">{section.subtitle}</p>
                              </div>
                            </div>
                            <span className="rounded-full bg-[#F0FAF1] px-3 py-1 text-xs font-bold text-[#1E8A3C]">
                              {items.length} produit{items.length > 1 ? "s" : ""}
                            </span>
                          </div>
                          <div className="grid grid-cols-2 gap-3 md:-mx-1 md:flex md:snap-x md:snap-mandatory md:gap-4 md:overflow-x-auto md:px-1 md:pb-3 md:scrollbar-none">
                            {items.map((product, index) => {
                              const delay = ((sectionIndex * 3 + index) % 4) + 1
                              return (
                                <div
                                  key={product.id}
                                  data-reveal="scale"
                                  data-delay={String(delay)}
                                  className="w-full md:w-[12rem] md:shrink-0 md:snap-start"
                                >
                                  <ProductCard
                                    id={product.id}
                                    name={product.name}
                                    image={product.image}
                                    price={product.price}
                                    prixKhddarEstime={product.prix_khddar_estime}
                                    niveau={product.niveau}
                                    unit={product.unit}
                                    displayUnit={product.displayUnit}
                                    quantityStep={product.quantityStep}
                                    stock={product.stock}
                                    onView={openProductDetail}
                                    variant="minimal"
                                    isFavorite={isFavorite(product.id)}
                                    onToggleFavorite={() => toggleFavorite(product.id)}
                                    onAddToCart={handleAddToCart}
                                  />
                                </div>
                              )
                            })}
                          </div>
                        </section>

                        {interlude && (
                          <div className="grid gap-3 sm:grid-cols-[minmax(0,1.4fr)_minmax(0,1fr)] sm:gap-4">
                            <CatalogueTrustInterlude
                              icon={interlude.trust.icon}
                              eyebrow={interlude.trust.eyebrow}
                              title={interlude.trust.title}
                              description={interlude.trust.description}
                              tone={interlude.trust.tone}
                              delay={String((sectionIndex % 3) + 1)}
                            />
                            <CatalogueStatInterlude
                              label={interlude.stat.label}
                              value={interlude.stat.value}
                              tone={interlude.stat.tone}
                              delay={String((sectionIndex % 3) + 2)}
                            />
                          </div>
                        )}
                      </Fragment>
                    )
                  })}

                  {filteredProducts.length === 0 && (
                    <div className="rounded-[28px] border border-[#E6EFE7] bg-white p-12 text-center">
                      <p className="text-[#6F8070]">Aucun produit disponible pour le moment.</p>
                    </div>
                  )}
                </div>
              ) : (
                <div
                  ref={revealRef}
                  id="catalogue-products"
                  className="scroll-mt-28"
                >
                  <div className="grid grid-cols-2 gap-3 md:-mx-1 md:flex md:snap-x md:snap-mandatory md:gap-4 md:overflow-x-auto md:px-1 md:pb-3 md:scrollbar-none">
                    {filteredProducts.map((product, index) => {
                      const delay = (index % 4) + 1
                      return (
                        <div
                          key={product.id}
                          data-reveal="scale"
                          data-delay={String(delay)}
                          className="w-full md:w-[12rem] md:shrink-0 md:snap-start"
                        >
                          <ProductCard
                            id={product.id}
                            name={product.name}
                            image={product.image}
                            price={product.price}
                            prixKhddarEstime={product.prix_khddar_estime}
                            niveau={product.niveau}
                            unit={product.unit}
                            displayUnit={product.displayUnit}
                            quantityStep={product.quantityStep}
                            stock={product.stock}
                            onView={openProductDetail}
                            variant="minimal"
                            isFavorite={isFavorite(product.id)}
                            onToggleFavorite={() => toggleFavorite(product.id)}
                            onAddToCart={handleAddToCart}
                          />
                        </div>
                      )
                    })}
                  </div>
                </div>
              )}

              {filteredProducts.length === 0 && !productsByLevel && (
                <div className="rounded-[28px] border border-[#E6EFE7] bg-white p-12 text-center">
                  <p className="text-[#6F8070]">Aucun produit ne correspond à votre recherche.</p>
                </div>
              )}
            </>
          )}
        </main>

        <aside
          className={cn(
            "fixed right-0 top-0 z-50 flex h-[100dvh] w-[min(100vw,22rem)] flex-col border-l border-[#E6F0E7] bg-white will-change-transform transition-transform duration-500 ease-[cubic-bezier(0.22,1,0.36,1)] xl:sticky xl:top-20 xl:h-[calc(100vh-80px)] xl:w-[20rem] xl:translate-x-0 2xl:w-[22rem]",
            showCart
              ? "translate-x-0 shadow-[0_24px_70px_-20px_rgba(18,32,24,0.4)] xl:shadow-none"
              : "translate-x-full xl:translate-x-0"
          )}
        >
          <button
            onClick={() => setShowCart(false)}
            className="absolute right-4 top-4 rounded-xl p-2 text-[#264129] xl:hidden"
          >
            <X className="h-5 w-5" />
          </button>

          <div className="border-b border-[#EEF2EE] p-4 xl:p-5">
            <div className="flex items-center gap-2 text-[#1E8A3C]">
              <ShoppingCart className="h-5 w-5" />
              <h2 className="text-xl font-black">Votre panier</h2>
            </div>
            <p className="mt-2 text-sm text-[#6F8070]">
              Ajustez vos quantités puis validez votre commande.
            </p>
          </div>

          <div className="flex-1 overflow-y-auto p-3 xl:p-4">
            {cart.length === 0 ? (
              <div className="py-10 text-center animate-fade-in-up">
                <img
                  src="/illustrations/empty-basket.webp"
                  alt=""
                  loading="lazy"
                  decoding="async"
                  width={144}
                  height={144}
                  aria-hidden="true"
                  className="mx-auto mb-3 h-36 w-36 object-contain animate-gentle-float"
                />
                <p className="text-[#6F8070]">Votre panier est vide.</p>
              </div>
            ) : (
              <div className="space-y-4 pb-4">
                <div className="rounded-xl border border-gray-200 bg-gray-50 px-4 py-3.5 shadow-sm">
                  {reste > 0 ? (
                    <div className="flex items-start justify-between gap-3">
                      <p className="text-sm font-bold leading-snug text-[#264129]">
                        Plus que {reste.toFixed(2)} DH pour la livraison gratuite 🎁
                      </p>
                      <span className="shrink-0 rounded-full bg-white px-2.5 py-1 text-xs font-bold text-[#9A5C11]">
                        Livraison {FRAIS.toFixed(0)} DH
                      </span>
                    </div>
                  ) : (
                    <div className="flex items-center justify-between gap-3">
                      <p className="text-sm font-bold text-[#1E8A3C]">Livraison offerte ✅</p>
                      <span className="shrink-0 rounded-full bg-[#F0FDF4] px-2.5 py-1 text-xs font-bold text-[#1E8A3C]">
                        Gratuite
                      </span>
                    </div>
                  )}

                  <div className="mt-3 w-full rounded-full bg-white h-2 ring-1 ring-gray-200">
                    <div
                      className="h-2 rounded-full bg-[#1E8A3C] transition-all duration-300"
                      style={{
                        width: `${progression}%`,
                      }}
                    />
                  </div>
                  <p className="mt-2 text-right text-[11px] font-semibold text-[#6F8070]">
                    {cartSubtotal.toFixed(2)} / {SEUIL.toFixed(0)} DH
                  </p>
                </div>

                {/* Produits deja selectionnes : toujours affiches en premier (haut du panier). */}
                {cart.map((item) => (
                  <div
                    key={item.id}
                    className="flex gap-3 rounded-2xl border border-[#E6F0E7] bg-[#F7FCF7] p-3"
                  >
                    <img
                      src={item.image}
                      alt={item.name}
                      onError={(event) => applyImageFallback(event, item.fallbackImage)}
                      className="h-14 w-14 shrink-0 rounded-xl object-cover 2xl:h-16 2xl:w-16 2xl:rounded-2xl"
                    />
                    <div className="min-w-0 flex-1">
                      <div className="flex items-start justify-between gap-2">
                        <div className="min-w-0">
                          <h3 className="truncate text-sm font-bold text-[#264129]">{item.name}</h3>
                          <p className="text-xs text-[#6F8070]">
                            {item.price.toFixed(2)} DH / {item.displayUnit}
                          </p>
                        </div>
                        <button
                          onClick={() => removeFromCart(item.id)}
                          className="rounded-full p-1 text-red-400 transition-colors hover:bg-red-50 hover:text-red-600"
                        >
                          <Trash2 className="h-4 w-4" />
                        </button>
                      </div>

                      <div className="mt-3 flex flex-wrap items-center gap-2">
                        <div className="flex shrink-0 items-center rounded-full border border-[#CDE8D0] bg-white">
                          <button
                            onClick={() => updateCartQuantity(item.id, -item.quantityStep)}
                            className="p-1.5 text-[#2E5A33] transition-colors hover:bg-[#E7F5E8] disabled:cursor-not-allowed disabled:opacity-40 2xl:p-2"
                          >
                            <Minus className="h-3 w-3" />
                          </button>
                          <span className="min-w-[72px] px-2 text-center text-xs font-semibold text-[#264129] 2xl:min-w-[90px] 2xl:px-3">
                            {formatQuantity(item.quantity, item.unit)}
                          </span>
                          <button
                            onClick={() => updateCartQuantity(item.id, item.quantityStep)}
                            className="p-1.5 text-[#2E5A33] transition-colors hover:bg-[#E7F5E8] disabled:cursor-not-allowed disabled:opacity-40 2xl:p-2"
                          >
                            <Plus className="h-3 w-3" />
                          </button>
                        </div>
                        <span className="ml-auto shrink-0 text-sm font-bold text-[#F07C00]">
                          {(item.price * item.quantity).toFixed(2)} DH
                        </span>
                      </div>
                    </div>
                  </div>
                ))}

                {/* Suggestions / upsell : section du bas, apres les produits choisis. */}
                {pricingSuggestions.length > 0 && (
                  <div className="rounded-xl border border-gray-200 bg-gray-50 px-4 py-3.5 shadow-sm">
                    <div className="mb-3 flex items-center gap-3">
                      <span className="h-px flex-1 bg-gray-200" />
                      <span className="text-[11px] font-bold uppercase tracking-wide text-gray-500">
                        À ne pas manquer
                      </span>
                      <span className="h-px flex-1 bg-gray-200" />
                    </div>
                    <div className="grid grid-cols-2 gap-2.5">
                      {pricingSuggestions.map((suggestion) => {
                        const niveau = suggestion.niveau || 2
                        const isInCart = cart.some((item) => item.id === suggestion.id)
                        const isFeaturedLevelTwo = niveau === 2 && suggestion.id === firstLevelTwoSuggestionId
                        const resteSuggestions = Math.max(0, SEUIL - cartSubtotal)
                        const suffitPourSeuil = resteSuggestions > 0 && suggestion.price >= resteSuggestions

                        return (
                        <div
                          key={suggestion.id}
                          className={cn(
                            "overflow-hidden rounded-xl border bg-white shadow-sm transition-shadow hover:shadow-md",
                            niveau === 3
                              ? "border-2 border-amber-400"
                              : isFeaturedLevelTwo
                                ? "border-2 border-[#1E8A3C]"
                                : "border-gray-200"
                          )}
                        >
                          <div className="relative flex aspect-square items-center justify-center bg-gray-50">
                            <img
                              src={suggestion.image}
                              alt={suggestion.name}
                              onError={(event) => applyImageFallback(event, suggestion.fallbackImage)}
                              className="h-full w-full object-cover"
                            />
                            <span className={cn(
                              "absolute left-2 top-2 rounded-full px-2 py-1 text-[10px] font-bold",
                              suffitPourSeuil
                                ? "bg-amber-100 text-amber-700"
                                : "hidden"
                            )}>
                              Suffit pour livraison gratuite
                            </span>
                            {suggestion.prix_khddar_estime && (
                              <span className="absolute bottom-2 right-2 rounded-full bg-white/90 px-2 py-0.5 text-[10px] text-gray-400 line-through">
                                {suggestion.prix_khddar_estime.toFixed(2)} DH
                              </span>
                            )}
                          </div>
                          <div className="p-3">
                            <p className="truncate text-[13px] font-medium text-[#264129]">
                              {suggestion.name}
                            </p>
                            <p className="mt-1 truncate text-[11px] text-gray-400">
                              Ajout malin pour compléter ton panier
                            </p>
                            <div className="mt-3 flex items-center justify-between gap-2">
                              <span className="text-[15px] font-medium text-[#1E8A3C]">
                                {suggestion.price.toFixed(2)} DH
                              </span>
                              <button
                                type="button"
                                onClick={() => handleAddSuggestionToCart(suggestion)}
                                className={cn(
                                  "flex h-8 w-8 items-center justify-center rounded-full border text-sm font-bold transition-colors",
                                  isInCart
                                    ? "border-[#1E8A3C] bg-[#1E8A3C] text-white"
                                    : "border-gray-300 bg-white text-[#264129] hover:border-[#1E8A3C] hover:text-[#1E8A3C]"
                                )}
                                aria-label={`Ajouter ${suggestion.name}`}
                              >
                                {isInCart ? "✓" : "+"}
                              </button>
                            </div>
                          </div>
                        </div>
                        )
                      })}
                    </div>

                    {cart.length > 0 && addedSuggestionItems.length > 0 && (
                      <div className="mt-4 flex items-center gap-3 rounded-xl border border-green-200 bg-[#F0FDF4] px-4 py-3">
                        <Leaf className="h-5 w-5 shrink-0 text-[#1E8A3C]" />
                        <p className="text-sm font-semibold text-[#264129]">
                          Tu économises {suggestionSavings.toFixed(2)} DH vs le khddar sur cette sélection 🌿
                        </p>
                      </div>
                    )}
                  </div>
                )}
              </div>
            )}
          </div>

          {cart.length > 0 && (
            <div className="border-t border-[#EEF2EE] p-4 xl:p-5">
              <div className="space-y-2 text-sm">
                <div className="flex items-center justify-between text-[#6F8070]">
                  <span>Sous-total</span>
                  <span className="font-semibold text-[#264129]">{cartSubtotal.toFixed(2)} DH</span>
                </div>
                <div className="flex items-center justify-between text-[#6F8070]">
                  <span>Livraison</span>
                  <span className="font-semibold text-[#264129]">
                    {cartDeliveryFee > 0 ? `${cartDeliveryFee.toFixed(2)} DH` : "Offerte ✅"}
                  </span>
                </div>
              </div>

              <div className="mt-4 flex items-center justify-between border-t border-[#EEF2EE] pt-4">
                <span className="text-lg font-black text-[#264129]">Total</span>
                <span className="text-xl font-black text-[#F07C00] 2xl:text-2xl">{cartTotal.toFixed(2)} DH</span>
              </div>

              <button
                onClick={handleCheckout}
                disabled={isSubmittingCart}
                className="mt-5 w-full rounded-2xl bg-[#F07C00] px-4 py-3 font-semibold text-white transition-colors hover:bg-[#D66B00] disabled:opacity-70 disabled:cursor-not-allowed"
              >
                {isSubmittingCart ? "Validation en cours..." : "Valider la commande"}
              </button>

              <p className="mt-3 text-center text-xs text-[#6F8070]">
                Livraison demain pour garantir la fraîcheur.
              </p>
            </div>
          )}
        </aside>
      </div>

      {(showSidebar || showCart) && (
        <div
          className="fixed inset-0 z-40 bg-black/40 backdrop-blur-[1px] animate-in fade-in duration-300 xl:hidden"
          onClick={() => {
            setShowSidebar(false)
            setShowCart(false)
          }}
        />
      )}

      {/* ===== BARRE PANIER STICKY (mobile) : acces checkout a portee de pouce =====
          Visible quand le panier contient des articles et que le tiroir panier est
          ferme. Remonte au-dessus de la barre de navigation. md:hidden via le
          primitif StickyBottomBar (desktop inchange). */}
      {cart.length > 0 && !showCart && (
        <StickyBottomBar aboveNav>
          <button
            type="button"
            onClick={() => {
              haptic("medium")
              setShowCart(true)
            }}
            className="flex w-full items-center justify-between gap-3 rounded-2xl bg-[#F07C00] px-4 py-3.5 text-white shadow-[0_12px_28px_-14px_rgba(240,124,0,0.8)] active:scale-[0.98]"
          >
            <span className="flex items-center gap-2">
              <span className="flex h-7 min-w-7 items-center justify-center rounded-full bg-white/20 px-1.5 text-[13px] font-black">
                {cart.length}
              </span>
              <span className="text-[15px] font-black">Voir le panier</span>
            </span>
            <span className="flex items-center gap-1.5 text-[15px] font-black souki-tabular-nums">
              {cartTotal.toFixed(2)} DH
              <ArrowRight className="h-4 w-4" />
            </span>
          </button>
        </StickyBottomBar>
      )}

      {/* Pas de onMenuClick ici : le bouton « Plus » ouvre le tiroir standard
          (Historique, Wallet, Profil…) au lieu de l'ancienne barre latérale
          gauche, redondante sur mobile (recherche + catégories déjà en tête). */}
      <MobileBottomNav
        cartCount={cart.length}
        onCartClick={() => setShowCart(true)}
      />

      <ProductDetailSheet
        product={detailProduct}
        open={detailProduct !== null}
        onClose={() => setDetailProduct(null)}
        onAddToCart={handleAddToCart}
        isFavorite={detailProduct ? isFavorite(detailProduct.id) : false}
        onToggleFavorite={() => detailProduct && toggleFavorite(detailProduct.id)}
      />

      <AIModals
        isOpen={activeModal !== null}
        onClose={() => setActiveModal(null)}
        mode={activeModal}
        products={products}
        onApplySelections={handleApplySelections}
      />

      {pendingDeleteOrderId !== null && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#122018]/55 px-4 py-6 backdrop-blur-sm">
          <div className="w-full max-w-md rounded-[28px] border border-[#F3D8B2] bg-white p-5 shadow-[0_30px_90px_rgba(18,32,24,0.25)]">
            <div className="flex items-start gap-3">
              <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-[#FFF7EE] text-[#F07C00]">
                <Trash2 className="h-5 w-5" />
              </span>
              <div className="min-w-0 flex-1">
                <h3 className="text-lg font-black text-[#264129]">Supprimer cette commande ?</h3>
                <p className="mt-1 text-sm font-semibold leading-6 text-[#6F8070]">
                  La commande N-{pendingDeleteOrderId} sera retiree de votre historique local. Vos donnees de paiement et de livraison ne changent pas.
                </p>
              </div>
            </div>

            <div className="mt-5 flex flex-col-reverse gap-3 sm:flex-row sm:justify-end">
              <button
                type="button"
                onClick={() => setPendingDeleteOrderId(null)}
                disabled={deletingOrderId === pendingDeleteOrderId}
                className="rounded-2xl border border-[#DDE7DE] px-5 py-3 text-sm font-bold text-[#607061] transition-colors hover:bg-[#F7FCF7] disabled:opacity-60"
              >
                Annuler
              </button>
              <button
                type="button"
                onClick={() => void confirmDeleteOrderHistory()}
                disabled={deletingOrderId === pendingDeleteOrderId}
                className="rounded-2xl bg-red-600 px-5 py-3 text-sm font-black text-white transition-colors hover:bg-red-700 disabled:cursor-not-allowed disabled:opacity-70"
              >
                {deletingOrderId === pendingDeleteOrderId ? "Suppression..." : "Supprimer"}
              </button>
            </div>
          </div>
        </div>
      )}

      {claimOrder && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#122018]/55 px-4 py-6 backdrop-blur-sm">
          <div className="w-full max-w-xl rounded-[28px] border border-[#DDEBDD] bg-white p-5 shadow-[0_30px_90px_rgba(18,32,24,0.25)]">
            <div className="flex items-start justify-between gap-4">
              <div>
                <p className="text-xs font-bold uppercase tracking-[0.2em] text-[#F07C00]">
                  SAV Wallet
                </p>
                <h3 className="mt-1 text-2xl font-black text-[#264129]">
                  Signaler un problème
                </h3>
                <p className="mt-1 text-sm text-[#6F8070]">
                  Commande N-{claimOrder.id} · remboursement crédité sur votre wallet SOUKI.
                </p>
              </div>
              <button
                onClick={closeClaimModal}
                disabled={isSubmittingClaim}
                className="rounded-2xl border border-[#E4ECE4] p-2 text-[#6F8070] transition-colors hover:bg-[#F7FCF7] disabled:opacity-60"
                aria-label="Fermer"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="mt-5 space-y-4">
              <label className="block">
                <span className="text-sm font-bold text-[#264129]">Produit concerné</span>
                <select
                  value={claimLineId ?? ""}
                  onChange={(event) => {
                    const nextLineId = Number(event.target.value)
                    const nextLine = claimableLines.find((line) => line.ligne_panier_id === nextLineId)
                    setClaimLineId(Number.isFinite(nextLineId) ? nextLineId : null)
                    setClaimQuantity(nextLine ? String(Math.min(1, nextLine.quantite_kg)) : "1")
                  }}
                  className="mt-2 w-full rounded-2xl border border-[#DDE7DE] bg-white px-4 py-3 text-sm font-semibold text-[#264129] outline-none focus:border-[#4CB84A]"
                >
                  {claimableLines.map((line) => (
                    <option key={line.ligne_panier_id} value={line.ligne_panier_id ?? ""}>
                      {line.nom_fr} · {formatQuantity(line.quantite_kg, "kg")}
                    </option>
                  ))}
                </select>
              </label>

              <div className="grid gap-4 sm:grid-cols-2">
                <label className="block">
                  <span className="text-sm font-bold text-[#264129]">Quantité à rembourser</span>
                  <input
                    type="number"
                    min="0.001"
                    max={selectedClaimLine?.quantite_kg ?? undefined}
                    step="0.001"
                    value={claimQuantity}
                    onChange={(event) => setClaimQuantity(event.target.value)}
                    className="mt-2 w-full rounded-2xl border border-[#DDE7DE] bg-white px-4 py-3 text-sm font-semibold text-[#264129] outline-none focus:border-[#4CB84A]"
                  />
                  {selectedClaimLine && (
                    <p className="mt-1 text-xs font-semibold text-[#7B8B7D]">
                      Maximum: {formatQuantity(selectedClaimLine.quantite_kg, "kg")}
                    </p>
                  )}
                </label>

                <label className="block">
                  <span className="text-sm font-bold text-[#264129]">Raison</span>
                  <select
                    value={claimReason}
                    onChange={(event) => setClaimReason(event.target.value as ClaimReason)}
                    className="mt-2 w-full rounded-2xl border border-[#DDE7DE] bg-white px-4 py-3 text-sm font-semibold text-[#264129] outline-none focus:border-[#4CB84A]"
                  >
                    {claimReasonOptions.map((reason) => (
                      <option key={reason.id} value={reason.id}>
                        {reason.label}
                      </option>
                    ))}
                  </select>
                </label>
              </div>

              <div className="rounded-2xl border border-[#F3D8B2] bg-[#FFF7EE] p-4 text-sm text-[#7A4C0E]">
                Le remboursement est automatiquement crédité sur votre wallet SOUKI. Aucun remboursement CB ou cash
                n'est propose pour ce parcours.
              </div>

              {claimError && (
                <div className="rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-semibold text-red-600">
                  {claimError}
                </div>
              )}

              <div className="flex flex-col-reverse gap-3 sm:flex-row sm:justify-end">
                <button
                  onClick={closeClaimModal}
                  disabled={isSubmittingClaim}
                  className="rounded-2xl border border-[#DDE7DE] px-5 py-3 text-sm font-bold text-[#607061] transition-colors hover:bg-[#F7FCF7] disabled:opacity-60"
                >
                  Annuler
                </button>
                <button
                  onClick={() => void handleSubmitClaim()}
                  disabled={isSubmittingClaim || !selectedClaimLine}
                  className="rounded-2xl bg-[#1E8A3C] px-5 py-3 text-sm font-black text-white transition-colors hover:bg-[#176B2E] disabled:cursor-not-allowed disabled:opacity-70"
                >
                  {isSubmittingClaim ? "Envoi en cours..." : "Crediter mon wallet"}
                </button>
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

export default function CataloguePage() {
  return (
    <Suspense
      fallback={
        <div className="min-h-screen bg-[#FBFDF9] flex items-center justify-center">
          <div className="h-10 w-10 animate-spin rounded-full border-4 border-[#1E8A3C] border-t-transparent" />
        </div>
      }
    >
      <CatalogueContent />
    </Suspense>
  )
}

"use client"

import { SoukiLogoLink } from "@/components/souki/souki-logo"
import { useState, useEffect, Suspense } from "react"
import Link from "next/link"
import Image from "next/image"
import { useSearchParams, useRouter } from "next/navigation"
import {
  ArrowLeft,
  Plus,
  Minus,
  Trash2,
  MapPin,
  Clock,
  Banknote,
  Wallet,
  CreditCard,
  Check,
  Lock,
  Shield,
  PartyPopper,
  MessageCircle,
  Navigation,
  AlertTriangle
} from "lucide-react"
import {
  API_BASE_URL,
  getBlacklistStatus,
  markBlacklistLiftNotificationSeen,
  requestBlacklistLift,
  type BlacklistStatusDTO,
} from "@/lib/api"
import { isValidMoroccanPhone, normalizeMoroccanPhone, PHONE_ERROR_MSG } from "@/lib/phoneValidator"
import { cn } from "@/lib/utils"
import {
  DELIVERY_FEE,
  FREE_DELIVERY_THRESHOLD,
  CatalogueProduct,
  fetchCatalogueProducts,
  getCataloguePresentation,
} from "@/lib/catalogue"
import { MapboxLocator } from "@/components/souki/mapbox-locator"
import { MobileBottomNav } from "@/components/souki/mobile-bottom-nav"
import { PolicyLink } from "@/components/souki/policy-link"
import { PwaHeader, StickyBottomBar } from "@/components/souki/pwa"
import { useAuth } from "@/hooks/useAuth"
import { useHaptic } from "@/hooks/useHaptic"
import { useOrderLock } from "@/hooks/useOrderLock"
import { toast } from "sonner"

const DEFAULT_IMAGE = "https://images.unsplash.com/photo-1540420773420-3366772f4999?w=400&h=300&fit=crop"
const SEUIL = FREE_DELIVERY_THRESHOLD
const FRAIS = DELIVERY_FEE

interface CartItem {
  id: string
  name: string
  price: number
  quantity: number
  unit: string
  image: string
}

interface UserProfile {
  prenom: string
  nom: string
  email: string
  telephone: string
  address: {
    adresse: string
    ville: string
    code_postal: string
  }
}

interface WalletState {
  has_wallet: boolean
  is_activated: boolean
  balance_centimes: number
}

// Updated time slots
// Livraison à l'heure exacte, contrainte entre 08h00 et 15h00.
const DELIVERY_MIN_TIME = "08:00"
const DELIVERY_MAX_TIME = "15:00"
const DELIVERY_TIME_PRESETS = ["08:00", "10:00", "12:00", "14:00"]
// Comparaison sûre car les chaînes "HH:MM" 24h zéro-paddées se trient lexicalement.
const isTimeInRange = (value: string) =>
  Boolean(value) && value >= DELIVERY_MIN_TIME && value <= DELIVERY_MAX_TIME
const formatDeliveryTime = (value: string) => (value ? value.replace(":", "h") : "—")

const paymentMethods = [
  { id: "cod", icon: Banknote, label: "Cash on Delivery", desc: "Payez à la porte, confirmation appel la veille" },
  { id: "wallet", icon: Wallet, label: "Wallet SOUKI", desc: "" },
  { id: "cmi", icon: CreditCard, label: "Carte Bancaire CMI", desc: "Visa / Mastercard marocain — Frais 2% inclus", disabled: true },
]

function CheckoutContent() {
  const searchParams = useSearchParams()
  const router = useRouter()
  const haptic = useHaptic()
  const commandeId = searchParams.get('commande_id')
  const panierId = searchParams.get('panier_id')
  const cartParam = searchParams.get('cart')
  const isSmartBasket = searchParams.get('source') === 'smart'
  const editCartHref = isSmartBasket
    ? "/catalogue?assistant=smart"
    : panierId
    ? `/catalogue?panier_id=${panierId}`
    : commandeId
      ? `/catalogue?commande_id=${commandeId}`
      : "/catalogue"

  // États
  const [voiceData, setVoiceData] = useState<any>(null)
  const [panierData, setPanierData] = useState<any>(null)
  const [isLoading, setIsLoading] = useState(!!commandeId || !!panierId)
  const [voiceError, setVoiceError] = useState(false)
  const [profileLoading, setProfileLoading] = useState(true)

  // On initialise le panier vide, on le remplira dynamiquement dans le useEffect
  const [cart, setCart] = useState<CartItem[]>([])

  // Profile data
  const [userProfile, setUserProfile] = useState<UserProfile | null>(null)
  const [walletBalance, setWalletBalance] = useState(0)
  const [phoneNumber, setPhoneNumber] = useState("")

  const [selectedTimeSlot, setSelectedTimeSlot] = useState(DELIVERY_MIN_TIME)
  const [timeError, setTimeError] = useState("")
  const [selectedPayment, setSelectedPayment] = useState("cod")
  const [acceptTerms, setAcceptTerms] = useState(false)
  const [address, setAddress] = useState("")
  const [city, setCity] = useState("")
  const [instructions, setInstructions] = useState("")
  const [isSubmitting, setIsSubmitting] = useState(false)
  // Commande validee par l'API : declenche l'overlay de celebration avant la redirection.
  const [confirmedOrderId, setConfirmedOrderId] = useState<number | null>(null)
  const [catalogueImages, setCatalogueImages] = useState<Record<number, string>>({})
  const [cataloguePrices, setCataloguePrices] = useState<Record<number, number>>({})
  const [catalogueProducts, setCatalogueProducts] = useState<CatalogueProduct[]>([])
  const [mapboxModalOpen, setMapboxModalOpen] = useState(false)
  const [blacklistStatus, setBlacklistStatus] = useState<BlacklistStatusDTO | null>(null)
  const [showLiftModal, setShowLiftModal] = useState(false)
  const [hideLiftNotification, setHideLiftNotification] = useState(false)
  const [liftMotif, setLiftMotif] = useState("")
  const [isSendingLiftRequest, setIsSendingLiftRequest] = useState(false)
  const [liftRequestMessage, setLiftRequestMessage] = useState("")
  // VULN-010 : plus aucun JWT dans le localStorage. `token` est un simple marqueur
  // de session non secret ; l'authentification reelle passe par le cookie httpOnly.
  const { token } = useAuth()
  // Verrou de commande restaure (BUG-004), aligne sur le cutoff backend.
  const { isLocked: isOrderCutoffActive, message: orderLockMessage } = useOrderLock()

  const isGenericImage = (imageUrl: string) =>
    imageUrl.includes("photo-1542838132-92c53300491e")

  const resolveCartItemImage = (
    rawImage: unknown,
    productId: number | null,
    productName: string
  ) => {
    // 1) Source la plus fiable: image catalogue par product_id
    if (productId !== null && catalogueImages[productId]) {
      return catalogueImages[productId]
    }
    // 2) Fallback métier: mapping catalogue par nom produit (avec alias)
    if (productName) {
      const mappedImage = getCataloguePresentation(productName).image
      if (!isGenericImage(mappedImage)) {
        return mappedImage
      }
    }
    // 3) Dernier recours: image backend seulement si non vide et non générique
    if (typeof rawImage === "string" && rawImage.trim().length > 0 && !isGenericImage(rawImage)) {
      return rawImage
    }
    return DEFAULT_IMAGE
  }

  const buildCartItems = (lines: any[]): CartItem[] => {
    return lines
      .map((line: any) => {
        const productId = Number(line.id ?? line.product_id)
        const productName = line.name || line.nom_produit || line.nom_fr || "Produit inconnu"
        const currentCataloguePrice = Number.isFinite(productId) ? cataloguePrices[productId] : undefined
        const price = Number(
          currentCataloguePrice ?? line.price ?? line.prix_unitaire ?? line.prix_kg ?? 0
        )
        const quantity = Number(
          line.quantity ?? line.quantite_effective ?? line.quantite_kg ?? 1
        )
        const unit = line.unit || line.unite || "kg"

        if (!Number.isFinite(productId) || !Number.isFinite(quantity) || quantity <= 0) {
          return null
        }

        return {
          id: String(productId),
          name: String(productName),
          price: Number.isFinite(price) ? price : 0,
          quantity,
          unit: String(unit),
          image: resolveCartItemImage(
            line.image,
            Number.isFinite(productId) ? productId : null,
            String(productName)
          ),
        }
      })
      .filter((item: CartItem | null): item is CartItem => item !== null)
  }

  const getCartOverrideFromUrl = (): CartItem[] | null => {
    if (!cartParam) {
      return null
    }

    try {
      const parsed = JSON.parse(cartParam)
      const items = Array.isArray(parsed) ? buildCartItems(parsed) : []
      return items.length > 0 ? items : null
    } catch {
      try {
        const parsed = JSON.parse(decodeURIComponent(cartParam))
        const items = Array.isArray(parsed) ? buildCartItems(parsed) : []
        return items.length > 0 ? items : null
      } catch {
        return null
      }
    }
  }

  // Helper function to extract city from address string
  const extractCityFromAddress = (fullAddress: string): string => {
    // Try to extract city from formatted address (usually the first meaningful word after street)
    // Format is typically: "Street Name, City" or similar
    const parts = fullAddress.split(",").map(p => p.trim())
    if (parts.length > 1) {
      return parts[parts.length - 1] // Return the last part (usually the city)
    }
    return ""
  }

  // Fetch user profile on mount
  useEffect(() => {
    const fetchProfile = async () => {
      if (!token) {
        setProfileLoading(false)
        return
      }

      try {
        const response = await fetch(`${API_BASE_URL}/api/user/bootstrap`, {
          headers: { Authorization: `Bearer ${token}` },
        })

        if (!response.ok) {
          throw new Error("Impossible de charger le profil")
        }

        const data = await response.json()

        // Set profile data
        setUserProfile(data.profile)

        // Pre-fill address and city
        if (data.profile.address?.adresse) {
          setAddress(data.profile.address.adresse)
          setCity(data.profile.address.ville || extractCityFromAddress(data.profile.address.adresse))
        }

        // Set phone number
        if (data.profile.telephone) {
          setPhoneNumber(data.profile.telephone)
        }

        // Set wallet balance (convert centimes to DH)
        if (data.wallet?.balance_centimes !== undefined) {
          setWalletBalance(data.wallet.balance_centimes / 100)
        } else if (data.wallet?.solde_centimes !== undefined) {
          setWalletBalance(data.wallet.solde_centimes / 100)
        }
      } catch (err) {
        console.error("Erreur lors du chargement du profil:", err)
      } finally {
        setProfileLoading(false)
      }
    }

    fetchProfile()
  }, [token])

  useEffect(() => {
    if (!token) {
      setBlacklistStatus(null)
      return
    }

    let isMounted = true
    getBlacklistStatus(token)
      .then((status) => {
        if (isMounted) {
          setBlacklistStatus(status)
        }
      })
      .catch(() => {
        if (isMounted) {
          setBlacklistStatus(null)
        }
      })

    return () => {
      isMounted = false
    }
  }, [token])

  useEffect(() => {
    let isMounted = true
    fetchCatalogueProducts()
      .then((products) => {
        if (!isMounted) {
          return
        }
        const imageMap = products.reduce<Record<number, string>>((acc, product) => {
          acc[product.id] = product.image
          return acc
        }, {})
        const priceMap = products.reduce<Record<number, number>>((acc, product) => {
          acc[product.id] = product.price
          return acc
        }, {})
        setCatalogueProducts(products)
        setCatalogueImages(imageMap)
        setCataloguePrices(priceMap)
      })
      .catch(() => {
        // Fallback already handled in resolveCartItemImage.
      })
    return () => {
      isMounted = false
    }
  }, [])

  // Récupération des données et INITIALISATION DU PANIER au bon moment
  useEffect(() => {
    const cartOverride = getCartOverrideFromUrl()

    if (commandeId) {
      // Flux voix: récupérer CommandeCheckoutDTO
      fetch(`${API_BASE_URL}/api/commandes/${commandeId}`, {
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
        .then(res => {
          if (!res.ok) throw new Error("Commande non trouvée")
          return res.json()
        })
        .then(data => {
          setVoiceData(data)

          if (cartOverride) {
            setCart(cartOverride)
          } else if (data.lignes && data.lignes.length > 0) {
            setCart(buildCartItems(data.lignes))
          }
          setIsLoading(false)
        })
        .catch(() => {
          setVoiceError(true)
          setIsLoading(false)
        })
    } else if (panierId) {
      // Flux manuel: récupérer PanierDetailsDTO
      fetch(`${API_BASE_URL}/api/paniers/${panierId}`, {
        headers: token ? { Authorization: `Bearer ${token}` } : {},
      })
        .then(res => {
          if (!res.ok) throw new Error("Panier non trouvé")
          return res.json()
        })
        .then(data => {
          setPanierData(data)

          if (data.lignes && data.lignes.length > 0) {
            setCart(buildCartItems(data.lignes))
          }
          setIsLoading(false)
        })
        .catch(() => {
          setVoiceError(true)
          setIsLoading(false)
        })
    } else if (cartParam) {
      // Si on vient de l'ancien système d'URL (sans voix)
      setCart(cartOverride ?? [])
    } else {
      // Faux panier par défaut si on accède à la page sans rien
      setCart([
        { id: "1", name: "Tomates Marocaines", price: 7, quantity: 5, unit: "kg", image: "https://images.unsplash.com/photo-1592924357228-91a4daadcfea" },
        { id: "3", name: "Oignons", price: 9, quantity: 3, unit: "kg", image: "https://images.unsplash.com/photo-1620574387735-3624d75b2dbc" },
        { id: "4", name: "Carottes", price: 8.5, quantity: 2, unit: "kg", image: "https://images.unsplash.com/photo-1598170845058-32b9d6a5da37?w=400&h=300&fit=crop" },
      ])
    }
  }, [commandeId, panierId, cartParam, catalogueImages, cataloguePrices, token])

  const merchantPrice = cart.reduce((sum, item) => sum + (item.price * 1.1) * item.quantity, 0)
  const subtotal = cart.reduce((sum, item) => sum + item.price * item.quantity, 0)
  const totalProduits = subtotal
  const progressionLivraison = Math.min(100, (totalProduits / SEUIL) * 100)
  const deliveryFee = totalProduits >= SEUIL ? 0 : FRAIS
  const walletDiscount = 0
  const total = subtotal + deliveryFee - walletDiscount
  const savings = merchantPrice - subtotal
  const isCodBlocked = Boolean(blacklistStatus?.is_blacklisted)
  const shouldShowLiftNotification = Boolean(
    blacklistStatus?.last_action === "LIFTED" &&
    !blacklistStatus.lift_notification_seen &&
    !hideLiftNotification
  )

  useEffect(() => {
    if (isCodBlocked && selectedPayment === "cod") {
      setSelectedPayment("wallet")
    }
  }, [isCodBlocked, selectedPayment])

  const cartProductIds = new Set(cart.map((item) => Number(item.id)))
  const suggestionsByLevel = [1, 2, 3].map((level) => ({
    level,
    items: catalogueProducts
      .filter((product) => product.niveau === level && !cartProductIds.has(product.id))
      .slice(0, 3),
  })).filter((group) => group.items.length > 0)

  const updateQuantity = (id: string, delta: number) => {
    haptic("light")
    setCart(prev => prev.map(item => {
      if (item.id === id) {
        const newQuantity = Math.max(0.5, item.quantity + delta)
        return { ...item, quantity: newQuantity }
      }
      return item
    }))
  }

  const removeItem = (id: string) => {
    haptic("light")
    setCart(prev => prev.filter(item => item.id !== id))
  }

  // Heure de livraison exacte : on borne à [08:00, 15:00]. Hors plage, on ramène
  // à la borne la plus proche et on affiche un message clair.
  const handleTimeChange = (value: string) => {
    if (!value) return
    haptic("light")
    if (!isTimeInRange(value)) {
      setSelectedTimeSlot(value < DELIVERY_MIN_TIME ? DELIVERY_MIN_TIME : DELIVERY_MAX_TIME)
      setTimeError("Livraison possible uniquement entre 08h00 et 15h00.")
      return
    }
    setTimeError("")
    setSelectedTimeSlot(value)
  }

  const addSuggestionToCart = (product: CatalogueProduct) => {
    setCart((prev) => {
      const existing = prev.find((item) => item.id === String(product.id))
      if (existing) {
        return prev.map((item) =>
          item.id === String(product.id)
            ? { ...item, quantity: Number((item.quantity + product.quantityStep).toFixed(2)) }
            : item
        )
      }
      return [
        ...prev,
        {
          id: String(product.id),
          name: product.name,
          price: product.price,
          quantity: product.quantityStep,
          unit: product.unit,
          image: product.image,
        },
      ]
    })
  }

  // Handle address detection from Mapbox
  const handleAddressDetected = (detectedAddress: string, detectedCity: string) => {
    setAddress(detectedAddress)
    setCity(detectedCity || extractCityFromAddress(detectedAddress))
  }

  const isWalletInsufficient = selectedPayment === "wallet" && walletBalance < total
  const isPhoneMissing = phoneNumber.trim().length === 0
  const isPhoneInvalid = phoneNumber.trim().length > 0 && !isValidMoroccanPhone(phoneNumber)
  const isAddressMissing = address.trim().length === 0
  const isCityMissing = city.trim().length === 0
  const canSubmitOrder =
    acceptTerms &&
    cart.length > 0 &&
    !isWalletInsufficient &&
    !isPhoneMissing &&
    !isPhoneInvalid &&
    !isAddressMissing &&
    !isCityMissing &&
    !(isCodBlocked && selectedPayment === "cod") &&
    !isOrderCutoffActive &&
    !isSubmitting

  const submitLiftRequest = async () => {
    if (!token) {
      setLiftRequestMessage("Connectez-vous pour envoyer la demande.")
      return
    }

    const motif = liftMotif.trim()
    if (!motif) {
      setLiftRequestMessage("Expliquez la situation avant l'envoi.")
      return
    }

    setIsSendingLiftRequest(true)
    setLiftRequestMessage("")
    try {
      await requestBlacklistLift(token, motif)
      const status = await getBlacklistStatus(token)
      setBlacklistStatus(status)
      setLiftMotif("")
      setShowLiftModal(false)
      setLiftRequestMessage("Demande envoyée.")
    } catch (error) {
      setLiftRequestMessage(error instanceof Error ? error.message : "Impossible d'envoyer la demande.")
    } finally {
      setIsSendingLiftRequest(false)
    }
  }

  const acknowledgeLiftNotification = async () => {
    if (!token) {
      setHideLiftNotification(true)
      return
    }

    try {
      await markBlacklistLiftNotificationSeen(token)
      setBlacklistStatus((current) => current ? { ...current, lift_notification_seen: true } : current)
    } catch {
      // Keep the alert visible if the backend cannot persist the read receipt.
      return
    }
    setHideLiftNotification(true)
  }

  const handleFinalSubmit = async () => {
    if (!canSubmitOrder) return

    setIsSubmitting(true)
    try {
      const payload = {
        items: cart.map(item => ({
          product_id: parseInt(item.id),
          quantity: item.quantity
        })),
        creneau_livraison: selectedTimeSlot,
        mode_paiement: selectedPayment,
        contact_phone: phoneNumber.trim() ? normalizeMoroccanPhone(phoneNumber) : null,
        delivery_address: address.trim(),
        delivery_city: city.trim(),
        delivery_instructions: instructions.trim() || null,
        // On envoie l'ID du brouillon vocal s'il existe, sinon null
        brouillon_vocal_id: commandeId ? parseInt(commandeId) : null,
        panier_id: panierId ? parseInt(panierId) : null
      }

      // Authentification par cookie httpOnly (credentials: "include"), plus de JWT cote JS.
      const res = await fetch(`${API_BASE_URL}/api/checkout`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        credentials: "include",
        body: JSON.stringify(payload)
      })

      if (res.ok) {
        const data = await res.json()
        // L'overlay anime remplace le toast comme feedback immediat ; la
        // redirection existante est juste differee le temps de la celebration.
        setConfirmedOrderId(data.commande_id)
        if (typeof navigator !== "undefined" && "vibrate" in navigator) {
          navigator.vibrate([15, 40, 20])
        }
        window.setTimeout(() => {
          router.push(`/catalogue?commande_validee=${data.commande_id}`)
        }, 1600)
      } else {
        const errData = await res.json().catch(() => ({}))
        toast.error(errData.detail || "Erreur lors de la validation de la commande.")
      }
    } catch (error) {
      toast.error("Erreur de connexion au serveur.")
    } finally {
      setIsSubmitting(false)
    }
  }

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#F5F5F0] flex items-center justify-center">
        <div className="text-center">
          <div className="w-16 h-16 border-4 border-[#1E8A3C] border-t-transparent rounded-full animate-spin mx-auto mb-4"></div>
          <p className="text-[#1E8A3C] font-bold text-xl">Préparation du panier</p>
        </div>
      </div>
    )
  }

  if (voiceError) {
    return (
      <div className="min-h-screen bg-[#F5F5F0] flex items-center justify-center">
        <div className="text-center bg-white p-8 rounded-2xl shadow-lg max-w-md">
          <p className="text-red-500 text-xl font-bold mb-4">Impossible de charger votre commande vocale.</p>
          <Link href="/" className="text-[#1E8A3C] font-bold hover:underline">Retour à l'accueil</Link>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[#F5F5F0] pb-40 md:pb-0">
      {confirmedOrderId !== null && (
        <div
          className="fixed inset-0 z-[110] flex flex-col items-center justify-center bg-white/95 backdrop-blur-sm px-6"
          role="status"
          aria-live="assertive"
        >
          <span className="relative flex h-24 w-24 items-center justify-center">
            <span className="absolute inset-0 rounded-full bg-[#4CB84A]/30 animate-souki-success-ring" />
            <span className="absolute -inset-3 rounded-full bg-[#4CB84A]/15 animate-souki-success-ring [animation-delay:0.35s]" />
            <span className="relative flex h-24 w-24 items-center justify-center rounded-full bg-[#1E8A3C] shadow-xl shadow-[#1E8A3C]/25 animate-souki-success-pop">
              <svg viewBox="0 0 24 24" className="h-12 w-12" fill="none" aria-hidden="true">
                <path
                  d="M6 12.5l4 4 8-9"
                  pathLength={100}
                  className="souki-check-draw"
                  stroke="white"
                  strokeWidth={2.5}
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
            </span>
          </span>
          <p className="mt-6 text-2xl font-bold text-[#233127] animate-fade-in-up">
            Commande N-{confirmedOrderId} confirmée
          </p>
          <p className="mt-2 text-sm text-[#66756B] animate-fade-in-up-delay-1">
            Vos produits frais arrivent demain matin, du champ au panier.
          </p>
          <img
            src="/illustrations/checkout-celebration.webp"
            alt=""
            decoding="async"
            width={144}
            height={144}
            aria-hidden="true"
            className="mt-4 h-36 w-36 object-contain animate-fade-in-up-delay-2"
          />
        </div>
      )}
      {/* En-tête mobile natif (← + titre centré), façon référence. Desktop garde son header. */}
      <div className="md:hidden">
        <PwaHeader title="Finaliser ma commande" onBack={() => router.push(editCartHref)} />
      </div>

      <header className="sticky top-0 z-10 hidden glass-ios26 border-b border-gray-100 md:block">
        <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between py-3">
            <div className="flex flex-col items-start gap-2">
              <Link
                href="/"
                className="group inline-flex items-center gap-2 rounded-xl bg-[#F0FAF1] px-4 py-2 text-sm font-semibold text-[#1E8A3C] shadow-sm ring-1 ring-[#D7EBD9] transition-all hover:-translate-y-0.5 hover:bg-[#E7F5E8] hover:shadow"
              >
                <ArrowLeft className="h-4 w-4 transition-transform group-hover:-translate-x-0.5" />
                <span>Retour à l'accueil</span>
              </Link>
              <Link
                href={editCartHref}
                className="group inline-flex items-center gap-2 rounded-xl bg-white px-4 py-2 text-sm font-semibold text-[#F07C00] shadow-sm ring-1 ring-[#F5D7B8] transition-all hover:-translate-y-0.5 hover:bg-[#FFF7EE] hover:shadow"
              >
                <ArrowLeft className="h-4 w-4 transition-transform group-hover:-translate-x-0.5" />
                <span>Modifier dans le catalogue</span>
              </Link>
            </div>
            <SoukiLogoLink height={36} priority />
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-6xl px-4 py-5 sm:px-6 md:py-8 lg:px-8">
        <div className="mb-6 md:mb-8">
          <h1 className="hidden text-2xl font-bold leading-tight text-[#1E8A3C] md:block lg:text-3xl">Finaliser ma commande</h1>
          <p className="text-sm font-medium text-[#6F8070] md:hidden">
            Vérifiez le panier, choisissez la livraison, puis confirmez.
          </p>
        </div>

        {blacklistStatus && (blacklistStatus.is_blacklisted || shouldShowLiftNotification) && (
          <div className={cn("mb-6 rounded-2xl border p-4", blacklistStatus.is_blacklisted ? "border-red-200 bg-red-50" : "border-emerald-200 bg-emerald-50")}>
            <div className="flex items-start gap-3">
              <AlertTriangle className={cn("mt-0.5 h-5 w-5 shrink-0", blacklistStatus.is_blacklisted ? "text-red-600" : "text-[#1E8A3C]")} />
              <div className="min-w-0">
                <p className={cn("text-sm font-semibold", blacklistStatus.is_blacklisted ? "text-red-700" : "text-[#1E8A3C]")}>
                  {blacklistStatus.is_blacklisted ? "Votre compte ne peut plus passer de commandes COD" : "Restriction COD levee"}
                </p>
                <p className={cn("mt-1 text-xs", blacklistStatus.is_blacklisted ? "text-red-500" : "text-[#1E8A3C]")}>
                  {blacklistStatus.is_blacklisted ? "Suite a un refus de livraison. Wallet et CMI restent disponibles." : "Vous pouvez a nouveau choisir le paiement a la livraison."}
                </p>
                {blacklistStatus.last_action === "LIFT_REQUESTED" && (
                  <p className="mt-2 text-xs font-medium text-amber-600">Demande de levee en attente de decision admin.</p>
                )}
                {blacklistStatus.last_action === "LIFT_REJECTED" && (
                  <p className="mt-2 text-xs font-medium text-red-600">Demande refusee. Motif : {blacklistStatus.last_reason}</p>
                )}
                {shouldShowLiftNotification && (
                  <p className="mt-2 text-xs font-medium text-[#1E8A3C]">Restriction levee. COD disponible a nouveau.</p>
                )}
                {shouldShowLiftNotification && (
                  <button
                    type="button"
                    onClick={() => void acknowledgeLiftNotification()}
                    className="mt-3 rounded-lg border border-[#1E8A3C] bg-white px-3 py-1.5 text-xs font-semibold text-[#1E8A3C] transition hover:bg-[#F0FAF1]"
                  >
                    J'ai compris
                  </button>
                )}
                {liftRequestMessage && <p className="mt-2 text-xs font-medium text-[#1E8A3C]">{liftRequestMessage}</p>}
                {blacklistStatus.last_action !== "LIFT_REQUESTED" && blacklistStatus.last_action !== "LIFTED" && (
                  <button
                    type="button"
                    onClick={() => {
                      setLiftRequestMessage("")
                      setShowLiftModal(true)
                    }}
                    className="mt-3 rounded-lg border border-red-300 bg-white px-3 py-1.5 text-xs font-semibold text-red-600 transition hover:bg-red-50"
                  >
                    Demander la levee de restriction
                  </button>
                )}
              </div>
            </div>
          </div>
        )}

        {voiceData && (
          <div className="bg-[#1E8A3C] text-white rounded-2xl p-5 mb-8 shadow-lg flex items-start gap-4">
            <MessageCircle className="w-8 h-8 shrink-0 mt-1" />
            <div>
              <h2 className="font-bold text-lg mb-1">Récapitulatif de votre commande vocale</h2>
              <p className="text-white/90 italic">« {voiceData.transcription} »</p>
              {voiceData.lignes.some((l: any) => l.message_ajustement) && (
                <p className="text-yellow-300 text-sm mt-2 font-medium">⚠️ Certains produits ont été ajustés selon leur disponibilité.</p>
              )}
            </div>
          </div>
        )}

        {panierData && (
          <div className="bg-[#1E8A3C] text-white rounded-2xl p-5 mb-8 shadow-lg flex items-start gap-4">
            <MessageCircle className="w-8 h-8 shrink-0 mt-1" />
            <div>
              <h2 className="font-bold text-lg mb-1">Récapitulatif de votre panier</h2>
              <p className="text-white/90">{panierData.nombre_articles || cart.length} article{(panierData.nombre_articles || cart.length) > 1 ? "s" : ""} pour {panierData.sous_total?.toFixed(2) || "calculé"} DH</p>
            </div>
          </div>
        )}

        {isSmartBasket && (
          <div className="bg-[#1E8A3C] text-white rounded-2xl p-5 mb-8 shadow-lg flex items-start gap-4">
            <MessageCircle className="w-8 h-8 shrink-0 mt-1" />
            <div>
              <h2 className="font-bold text-lg mb-1">Panier intelligent IA-SOUKI</h2>
              <p className="text-white/90">
                {cart.length} article{cart.length > 1 ? "s" : ""} genere{cart.length > 1 ? "s" : ""} par le modele ML, affiches dans votre checkout.
              </p>
            </div>
          </div>
        )}

        <div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_minmax(24rem,0.92fr)] lg:gap-8">
          {/* Left Column - Cart */}
          <div id="checkout-cart" className="space-y-6 lg:sticky lg:top-28 lg:self-start">
            <div className="overflow-hidden rounded-2xl bg-white shadow-sm">
              <div className="border-b border-gray-100 p-5 sm:p-6">
                <h2 className="text-xl font-bold text-[#1E8A3C]">{voiceData ? "Panier validé par l'IA" : isSmartBasket ? "Panier intelligent" : panierData ? "Votre panier validé" : "Votre Panier"}</h2>
              </div>

              <div className="divide-y divide-gray-100">
                {cart.map(item => (
                  <div key={item.id} className="flex gap-3 p-4 sm:gap-4">
                    <Image
                      src={item.image}
                      alt={item.name}
                      width={80}
                      height={80}
                      className="h-20 w-20 shrink-0 rounded-xl object-cover"
                    />
                    <div className="min-w-0 flex-1">
                      <h3 className="font-semibold text-[#3D3D3D]">{item.name}</h3>
                      <p className="text-[#F07C00] font-bold">{item.price.toFixed(2)} DH/{item.unit}</p>
                      <div className="mt-3 flex items-center gap-2">
                        <div className="flex min-h-10 items-center overflow-hidden rounded-xl border border-gray-200">
                          <button onClick={() => updateQuantity(item.id, -0.5)} className="flex h-10 w-10 items-center justify-center hover:bg-gray-100"><Minus className="w-4 h-4" /></button>
                          <span className="min-w-16 px-2 text-center text-sm font-medium">{item.quantity} {item.unit}</span>
                          <button onClick={() => updateQuantity(item.id, 0.5)} className="flex h-10 w-10 items-center justify-center hover:bg-gray-100"><Plus className="w-4 h-4" /></button>
                        </div>
                        <button onClick={() => removeItem(item.id)} className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl text-red-400 hover:bg-red-50 hover:text-red-600" aria-label={`Retirer ${item.name}`}>
                          <Trash2 className="w-4 h-4" />
                        </button>
                      </div>
                    </div>
                    <div className="hidden text-right sm:block">
                      <p className="font-bold text-[#3D3D3D]">{(item.price * item.quantity).toFixed(2)} DH</p>
                    </div>
                  </div>
                ))}
              </div>

              <div className="p-6 bg-[#F0FAF1] space-y-2">
                <div className="rounded-xl border border-[#D7EBD9] bg-white px-4 py-3">
                  <div className="mb-2 flex items-center justify-between gap-3 text-sm">
                    <span className="font-semibold text-[#3D3D3D]">Livraison</span>
                    <span className={cn(
                      "font-bold",
                      deliveryFee > 0 ? "text-amber-700" : "text-[#1E8A3C]"
                    )}>
                      {deliveryFee > 0 ? `${deliveryFee.toFixed(0)} DH` : "Offerte ✅"}
                    </span>
                  </div>

                  <div className="w-full bg-gray-200 rounded-full h-1.5">
                    <div
                      className="h-1.5 rounded-full transition-all duration-300"
                      style={{
                        width: `${progressionLivraison}%`,
                        backgroundColor: progressionLivraison >= 100 ? "#1E8A3C" : "#F59E0B"
                      }}
                    />
                  </div>
                </div>

                <div className="flex justify-between text-sm">
                  <span className="text-[#8A8A8A]">Sous-total produits</span>
                  <span className="font-medium">{subtotal.toFixed(2)} DH</span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-[#8A8A8A]">Frais de livraison</span>
                  <span className="font-medium">
                    {deliveryFee > 0 ? `${deliveryFee.toFixed(2)} DH` : "Offerte ✅"}
                  </span>
                </div>
                <div className="flex justify-between text-sm">
                  <span className="text-[#8A8A8A]">Réduction Wallet</span>
                  <span className="font-medium">-{walletDiscount.toFixed(2)} DH</span>
                </div>
                <div className="flex justify-between font-bold text-lg pt-2 border-t border-[#4CB84A]/30">
                  <span>Total TTC</span>
                  <span className="text-[#F07C00]">{total.toFixed(2)} DH</span>
                </div>
                <div className="flex items-center gap-2 text-[#1E8A3C] text-sm">
                  <PartyPopper className="w-4 h-4" />
                  <span>{voiceData ? "Commande traitée par IA-SOUKI" : isSmartBasket ? "Panier compose par le modele ML SOUKI" : `Économie vs marchand : -${savings.toFixed(2)} DH`}</span>
                </div>
              </div>
            </div>

            {isSmartBasket && suggestionsByLevel.length > 0 && (
              <div className="overflow-hidden rounded-2xl bg-white shadow-sm">
                <div className="border-b border-gray-100 p-5 sm:p-6">
                  <h2 className="text-lg font-bold text-[#1E8A3C]">Completer le panier par niveau</h2>
                  <p className="mt-1 text-sm font-medium text-[#6F8070]">
                    Suggestions catalogue pour enrichir votre panier genere.
                  </p>
                </div>
                <div className="space-y-5 p-5 sm:p-6">
                  {suggestionsByLevel.map((group) => (
                    <div key={group.level}>
                      <div className="mb-3 flex items-center justify-between gap-3">
                        <span className="text-sm font-bold text-[#264129]">Niveau {group.level}</span>
                        <span className="rounded-full bg-[#F0FAF1] px-3 py-1 text-xs font-bold text-[#1E8A3C]">
                          {group.items.length} suggestion{group.items.length > 1 ? "s" : ""}
                        </span>
                      </div>
                      <div className="grid gap-3 sm:grid-cols-3">
                        {group.items.map((product) => (
                          <div key={product.id} className="overflow-hidden rounded-xl border border-gray-200 bg-white">
                            <img src={product.image} alt={product.name} className="h-24 w-full object-cover" />
                            <div className="p-3">
                              <p className="truncate text-sm font-semibold text-[#264129]">{product.name}</p>
                              <p className="mt-1 text-xs font-medium text-[#6F8070]">
                                {product.price.toFixed(2)} DH/{product.displayUnit}
                              </p>
                              <button
                                type="button"
                                onClick={() => addSuggestionToCart(product)}
                                className="mt-3 flex min-h-9 w-full items-center justify-center gap-2 rounded-xl bg-[#1E8A3C] px-3 py-2 text-sm font-bold text-white transition-colors hover:bg-[#176B2E]"
                              >
                                <Plus className="h-4 w-4" />
                                Ajouter
                              </button>
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Right Column - Details */}
          <div className="space-y-5 lg:space-y-6">
            <div className="rounded-2xl bg-white p-5 shadow-sm sm:p-6">
              <h3 className="font-bold text-[#3D3D3D] mb-4 flex items-center gap-2">
                <MapPin className="w-5 h-5 text-[#1E8A3C]" />
                Adresse de livraison
              </h3>
              <div className="space-y-4">
                <div>
                  <label className="block text-sm font-medium text-[#3D3D3D] mb-2">Adresse</label>
                  <input type="text" value={address} onChange={(e) => setAddress(e.target.value)} placeholder="Entrez votre adresse de livraison" className="min-h-12 w-full rounded-xl border-2 border-gray-200 px-4 py-3 focus:border-[#4CB84A] focus:outline-none" />
                  {isAddressMissing && (
                    <p className="mt-2 text-xs font-semibold text-red-500">
                      Ajoutez votre adresse de livraison.
                    </p>
                  )}
                </div>

                {/* "Me localiser" button with Mapbox */}
                <button
                  onClick={() => setMapboxModalOpen(true)}
                  className="flex min-h-12 w-full items-center justify-center gap-2 rounded-xl border-2 border-[#1E8A3C] px-4 py-3 font-semibold text-[#1E8A3C] transition-colors hover:bg-[#F0FAF1]"
                >
                  <Navigation className="w-4 h-4" />
                  Me localiser
                </button>

                <div>
                  <label className="block text-sm font-medium text-[#3D3D3D] mb-2">Ville</label>
                  <input type="text" value={city} onChange={(e) => setCity(e.target.value)} placeholder="Ville" className="min-h-12 w-full rounded-xl border-2 border-gray-200 px-4 py-3 focus:border-[#4CB84A] focus:outline-none" />
                  {isCityMissing && (
                    <p className="mt-2 text-xs font-semibold text-red-500">
                      Ajoutez votre ville pour la livraison.
                    </p>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#3D3D3D] mb-2">Numero de telephone</label>
                  <input
                    type="tel"
                    value={phoneNumber}
                    onChange={(e) => setPhoneNumber(e.target.value)}
                    placeholder={profileLoading ? "Chargement du numéro..." : "+212..."}
                    className="min-h-12 w-full rounded-xl border-2 border-gray-200 px-4 py-3 focus:border-[#4CB84A] focus:outline-none"
                  />
                  {isPhoneMissing && (
                    <p className="mt-2 text-xs font-semibold text-red-500">
                      Ajoutez un numéro pour que SOUKI confirme la livraison.
                    </p>
                  )}
                  {isPhoneInvalid && (
                    <p className="mt-2 text-xs font-semibold text-red-500">
                      {PHONE_ERROR_MSG}
                    </p>
                  )}
                </div>

                <div>
                  <label className="block text-sm font-medium text-[#3D3D3D] mb-2">Instructions livraison (optionnel)</label>
                  <textarea value={instructions} onChange={(e) => setInstructions(e.target.value)} placeholder="Ex: 2ème étage, code porte 1234..." rows={3} className="w-full resize-none rounded-xl border-2 border-gray-200 px-4 py-3 focus:border-[#4CB84A] focus:outline-none" />
                </div>
              </div>
            </div>

            <div className="rounded-2xl bg-white p-5 shadow-sm sm:p-6">
              <h3 className="mb-1 flex items-center gap-2 font-bold text-[#3D3D3D]">
                <Clock className="h-5 w-5 text-[#1E8A3C]" />
                Heure de livraison
              </h3>
              <p className="mb-4 text-sm text-[#8A8A8A]">
                Choisissez l&apos;heure exacte, demain entre 8h00 et 15h00.
              </p>

              {/* Heure choisie mise en avant + sélecteur précis */}
              <div className="mb-4 flex items-center justify-between gap-3 rounded-2xl bg-[#F0FAF1] px-4 py-3">
                <div className="min-w-0">
                  <p className="text-xs font-semibold text-[#6F8070]">Livraison prévue vers</p>
                  <p className="souki-tabular-nums text-2xl font-black leading-tight text-[#1E8A3C]">
                    {formatDeliveryTime(selectedTimeSlot)}
                  </p>
                </div>
                <input
                  type="time"
                  min={DELIVERY_MIN_TIME}
                  max={DELIVERY_MAX_TIME}
                  step={900}
                  value={selectedTimeSlot}
                  onChange={(event) => handleTimeChange(event.target.value)}
                  aria-label="Heure de livraison souhaitée"
                  className="shrink-0 rounded-xl border-2 border-[#CDE8D0] bg-white px-3 py-2.5 text-base font-bold text-[#264129] outline-none transition-colors focus:border-[#4CB84A]"
                />
              </div>

              {/* Raccourcis d'heures fréquentes */}
              <div className="flex flex-wrap gap-2">
                {DELIVERY_TIME_PRESETS.map((preset) => (
                  <button
                    key={preset}
                    type="button"
                    onClick={() => {
                      haptic("light")
                      setTimeError("")
                      setSelectedTimeSlot(preset)
                    }}
                    className={cn(
                      "min-h-11 rounded-full px-4 py-2 text-sm font-bold transition-all active:scale-95",
                      selectedTimeSlot === preset
                        ? "bg-[#1E8A3C] text-white shadow-sm"
                        : "bg-gray-100 text-[#3D3D3D] hover:bg-gray-200",
                    )}
                  >
                    {formatDeliveryTime(preset)}
                  </button>
                ))}
              </div>

              {timeError ? (
                <p className="mt-3 text-xs font-semibold text-red-500">{timeError}</p>
              ) : (
                <p className="mt-3 text-sm text-[#8A8A8A]">Livraison le lendemain entre 8h et 15h, à l&apos;heure choisie.</p>
              )}
            </div>

            <div className="rounded-2xl bg-white p-5 shadow-sm sm:p-6">
              <h3 className="font-bold text-[#3D3D3D] mb-4 flex items-center gap-2">
                <CreditCard className="w-5 h-5 text-[#1E8A3C]" />
                Méthode de Paiement
              </h3>
              <div className="space-y-3">
                {/* Cash on Delivery */}
                <button
                  onClick={() => {
                    if (!isCodBlocked) {
                      haptic("light")
                      setSelectedPayment("cod")
                    }
                  }}
                  disabled={isCodBlocked}
                  className={cn("flex min-h-16 w-full items-start gap-4 rounded-xl border-2 p-4 text-left transition-all", selectedPayment === "cod" ? "border-[#F07C00] bg-[#F07C00]/5" : "border-gray-200 hover:border-gray-300", isCodBlocked && "cursor-not-allowed opacity-60")}
                >
                  <div className={cn("p-2 rounded-lg", selectedPayment === "cod" ? "bg-[#F07C00] text-white" : "bg-gray-100 text-[#3D3D3D]")}><Banknote className="w-5 h-5" /></div>
                  <div className="flex-1">
                    <p className="font-semibold text-[#3D3D3D]">Cash on Delivery</p>
                    {isCodBlocked && (
                      <p className="mt-1 text-xs font-semibold text-red-500">
                        Indisponible tant que la restriction est active.
                      </p>
                    )}
                    <p className="text-sm text-[#8A8A8A] mt-1">Payez à la porte, confirmation appel la veille</p>
                  </div>
                  {selectedPayment === "cod" && (
                    <div className="w-6 h-6 rounded-full bg-[#F07C00] flex items-center justify-center"><Check className="w-4 h-4 text-white" /></div>
                  )}
                </button>

                {/* Wallet */}
                <button
                  onClick={() => { haptic("light"); setSelectedPayment("wallet") }}
                  className={cn("flex min-h-16 w-full items-start gap-4 rounded-xl border-2 p-4 text-left transition-all", selectedPayment === "wallet" ? "border-[#F07C00] bg-[#F07C00]/5" : "border-gray-200 hover:border-gray-300")}
                >
                  <div className={cn("p-2 rounded-lg", selectedPayment === "wallet" ? "bg-[#F07C00] text-white" : "bg-gray-100 text-[#3D3D3D]")}><Wallet className="w-5 h-5" /></div>
                  <div className="flex-1">
                    <p className="font-semibold text-[#3D3D3D]">Wallet SOUKI</p>
                    <p className={cn("text-sm mt-1", isWalletInsufficient ? "text-red-500 font-semibold" : "text-[#8A8A8A]")}>
                      Solde : {walletBalance.toFixed(2)} DH
                      {isWalletInsufficient && " — Crédit insuffisant"}
                    </p>
                  </div>
                  {selectedPayment === "wallet" && (
                    <div className="w-6 h-6 rounded-full bg-[#F07C00] flex items-center justify-center"><Check className="w-4 h-4 text-white" /></div>
                  )}
                </button>

                {/* Card Payment - Disabled */}
                <button
                  disabled
                  className="flex min-h-16 w-full cursor-not-allowed items-start gap-4 rounded-xl border-2 border-gray-200 p-4 text-left opacity-60 transition-all"
                >
                  <div className="p-2 rounded-lg bg-gray-100 text-[#8A8A8A]"><CreditCard className="w-5 h-5" /></div>
                  <div className="flex-1">
                    <div className="flex items-center gap-2">
                      <p className="font-semibold text-[#8A8A8A]">Carte Bancaire CMI</p>
                      <span className="inline-flex items-center gap-1 px-2 py-1 bg-gray-200 text-[#8A8A8A] text-xs font-semibold rounded-lg">
                        <AlertTriangle className="w-3 h-3" />
                        Non disponible
                      </span>
                    </div>
                    <p className="text-sm text-[#8A8A8A] mt-1">Visa / Mastercard marocain — Bientôt disponible</p>
                  </div>
                </button>
              </div>
            </div>

            <div className="space-y-4 rounded-2xl bg-white p-5 shadow-sm sm:p-6">
              {isOrderCutoffActive && (
                <div className="rounded-xl border border-amber-300 bg-amber-50 p-4 text-sm text-amber-800">
                  {orderLockMessage}
                </div>
              )}
              <label className="flex items-start gap-3 cursor-pointer">
                <div onClick={() => setAcceptTerms(!acceptTerms)} className={cn("w-5 h-5 rounded border-2 flex items-center justify-center transition-colors flex-shrink-0 mt-0.5", acceptTerms ? "bg-[#1E8A3C] border-[#1E8A3C]" : "border-gray-300")}>
                  {acceptTerms && <Check className="w-3 h-3 text-white" />}
                </div>
                <span className="text-sm text-[#3D3D3D]">J'ai lu et j'accepte la <PolicyLink className="text-[#1A4F8A] hover:underline" /></span>
              </label>

              <button
                onClick={handleFinalSubmit}
                disabled={!canSubmitOrder}
                className={cn("hidden min-h-14 w-full items-center justify-center gap-2 rounded-xl py-4 text-lg font-bold transition-all md:flex", canSubmitOrder ? "bg-[#F07C00] text-white hover:bg-[#D66B00] shadow-lg shadow-[#F07C00]/30" : "bg-gray-200 text-gray-500 cursor-not-allowed")}
              >
                {isSubmitting ? (
                  <>
                    <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                    Validation en cours...
                  </>
                ) : (
                  <>
                    <Check className="w-5 h-5" />
                    Passer la Commande
                  </>
                )}
              </button>

              <div className="flex items-center justify-center gap-2 text-sm text-[#8A8A8A]">
                <Shield className="w-4 h-4" />
                <span>Paiement sécurisé — Données protégées</span>
                <Lock className="w-4 h-4" />
              </div>
            </div>
          </div>
        </div>
      </main>

      {showLiftModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4">
          <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl">
            <h3 className="text-lg font-bold text-[#3D3D3D]">Demande de levee</h3>
            <p className="mt-2 text-sm text-[#8A8A8A]">Expliquez la situation pour que l'admin puisse prendre une decision.</p>
            <textarea
              value={liftMotif}
              onChange={(event) => setLiftMotif(event.target.value)}
              placeholder="Expliquez la situation..."
              rows={5}
              className="mt-4 w-full resize-none rounded-xl border-2 border-gray-200 px-4 py-3 text-sm text-[#3D3D3D] outline-none transition-colors focus:border-red-300"
            />
            {liftRequestMessage && <p className="mt-2 text-xs font-medium text-red-500">{liftRequestMessage}</p>}
            <div className="mt-5 flex justify-end gap-3">
              <button
                type="button"
                onClick={() => {
                  setShowLiftModal(false)
                  setLiftMotif("")
                  setLiftRequestMessage("")
                }}
                disabled={isSendingLiftRequest}
                className="rounded-xl border border-gray-200 px-4 py-2 text-sm font-medium text-[#3D3D3D] transition hover:bg-gray-50 disabled:opacity-60"
              >
                Annuler
              </button>
              <button
                type="button"
                onClick={() => void submitLiftRequest()}
                disabled={isSendingLiftRequest || liftMotif.trim().length === 0}
                className="rounded-xl bg-red-500 px-4 py-2 text-sm font-semibold text-white transition hover:bg-red-600 disabled:cursor-not-allowed disabled:opacity-60"
              >
                {isSendingLiftRequest ? "Envoi..." : "Envoyer la demande"}
              </button>
            </div>
          </div>
        </div>
      )}

      {/* ===== CTA STICKY BAS (mobile) : total + passer la commande, à portée de pouce ===== */}
      {cart.length > 0 && confirmedOrderId === null && (
        <StickyBottomBar aboveNav>
          <button
            onClick={() => {
              haptic("medium")
              handleFinalSubmit()
            }}
            disabled={!canSubmitOrder}
            className={cn(
              "flex w-full items-center justify-between gap-3 rounded-2xl px-4 py-3.5 text-white transition-all active:scale-[0.98]",
              canSubmitOrder
                ? "bg-[#F07C00] shadow-[0_12px_28px_-14px_rgba(240,124,0,0.8)]"
                : "cursor-not-allowed bg-gray-300",
            )}
          >
            <span className="flex flex-col items-start leading-tight">
              <span className="text-[11px] font-semibold text-white/80">Total TTC</span>
              <span className="text-[17px] font-black souki-tabular-nums">{total.toFixed(2)} DH</span>
            </span>
            <span className="flex items-center gap-1.5 text-[15px] font-black">
              {isSubmitting ? (
                <>
                  <span className="h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent" />
                  Validation…
                </>
              ) : (
                <>
                  <Check className="h-4 w-4" />
                  Passer la commande
                </>
              )}
            </span>
          </button>
        </StickyBottomBar>
      )}

      {/* Mapbox Locator Modal */}
      <MapboxLocator
        isOpen={mapboxModalOpen}
        onClose={() => setMapboxModalOpen(false)}
        onAddressDetected={handleAddressDetected}
      />
      <MobileBottomNav
        cartCount={cart.length}
        onCartClick={() => document.getElementById("checkout-cart")?.scrollIntoView({ behavior: "smooth" })}
      />
    </div>
  )
}

export default function CheckoutPage() {
  return (
    <Suspense fallback={
      <div className="min-h-screen bg-[#F5F5F0] flex items-center justify-center">
        <div className="text-[#1E8A3C]">Chargement...</div>
      </div>
    }>
      <CheckoutContent />
    </Suspense>
  )
}

"use client"

import { useEffect, useMemo, useState } from "react"
import { useRouter } from "next/navigation"
import { Heart, Sprout } from "lucide-react"

import { FarmerAvatar } from "@/components/avatar/farmer-avatar"
import { MobileBottomNav } from "@/components/souki/mobile-bottom-nav"
import { ProductCard } from "@/components/souki/product-card"
import { PwaHeader, PwaScreen, ProductDetailSheet } from "@/components/souki/pwa"
import type { CatalogueProduct } from "@/lib/catalogue"
import {
  fetchCatalogueProducts,
  loadStoredCart,
  saveStoredCart,
  upsertCartItem,
} from "@/lib/catalogue"
import { isPwaStandalone } from "@/lib/pwa"
import { useAuth } from "@/hooks/useAuth"
import { useFavorites } from "@/hooks/useFavorites"
import { useHaptic } from "@/hooks/useHaptic"

/**
 * Ecran « Mes favoris » (PWA). Liste les produits marques en favori (coeur),
 * source de verite serveur via useFavorites. Retirer un favori le fait
 * disparaitre de la grille ; clic sur une carte ouvre la fiche detail.
 *
 * Ecran mobile/PWA uniquement : en dehors du mode standalone, on renvoie vers
 * l'accueil web (comme app/pwa-welcome).
 */
export default function FavorisPage() {
  const router = useRouter()
  const { isAuthenticated, isLoading } = useAuth()
  const { favorites: favoriteIds, isFavorite, toggleFavorite } = useFavorites()
  const haptic = useHaptic()

  const [isReady, setIsReady] = useState(false)
  const [products, setProducts] = useState<CatalogueProduct[]>([])
  const [isFetching, setIsFetching] = useState(true)
  const [detailProduct, setDetailProduct] = useState<CatalogueProduct | null>(null)
  const [detailOpen, setDetailOpen] = useState(false)
  const [cartCount, setCartCount] = useState(0)

  // Garde standalone (identique a l'accueil PWA).
  useEffect(() => {
    const canPreview =
      process.env.NODE_ENV !== "production" &&
      new URLSearchParams(window.location.search).get("preview") === "pwa"
    if (!isPwaStandalone() && !canPreview) {
      router.replace("/")
      return
    }
    setIsReady(true)
  }, [router])

  // Garde de session.
  useEffect(() => {
    if (isReady && !isLoading && !isAuthenticated) {
      router.replace("/login?redirect=/favoris")
    }
  }, [isReady, isLoading, isAuthenticated, router])

  // Chargement catalogue (les produits favoris en sont derives).
  useEffect(() => {
    if (!isReady) return
    let isMounted = true
    void (async () => {
      try {
        const catalogue = await fetchCatalogueProducts()
        if (isMounted) setProducts(catalogue)
      } catch {
        // silencieux
      } finally {
        if (isMounted) setIsFetching(false)
      }
    })()
    return () => {
      isMounted = false
    }
  }, [isReady])

  useEffect(() => {
    setCartCount(loadStoredCart().length)
  }, [])

  const favoriteProducts = useMemo(
    () => products.filter((product) => favoriteIds.includes(product.id)),
    [products, favoriteIds],
  )

  const handleAddToCart = (id: number | string, quantity: number) => {
    const product = products.find((item) => item.id === Number(id))
    if (!product) return
    saveStoredCart(upsertCartItem(loadStoredCart(), product, quantity))
    setCartCount(loadStoredCart().length)
    haptic("success")
  }

  const openDetail = (id: number | string) => {
    const product = products.find((item) => item.id === Number(id))
    if (!product) return
    setDetailProduct(product)
    setDetailOpen(true)
    haptic("light")
  }

  const handleToggleFavorite = (id: number | string) => {
    toggleFavorite(Number(id))
    haptic("medium")
  }

  if (!isReady || isLoading || !isAuthenticated) {
    return (
      <PwaScreen>
        <div className="flex min-h-dvh items-center justify-center">
          <div className="h-10 w-10 animate-pulse rounded-2xl bg-[#1E8A3C]" />
        </div>
      </PwaScreen>
    )
  }

  return (
    <PwaScreen>
      <PwaHeader
        title="Mes favoris"
        subtitle={
          favoriteProducts.length > 0
            ? `${favoriteProducts.length} produit${favoriteProducts.length > 1 ? "s" : ""}`
            : "Vos coups de cœur"
        }
        onBack={() => router.push("/pwa-welcome")}
      />

      {isFetching ? (
        <div className="grid grid-cols-2 gap-3 px-4 pt-2">
          {Array.from({ length: 4 }).map((_, index) => (
            <div key={index} className="souki-skeleton h-56 rounded-3xl" />
          ))}
        </div>
      ) : favoriteProducts.length === 0 ? (
        <div className="flex flex-col items-center px-8 pt-14 text-center">
          <div className="relative mb-5">
            <div className="flex h-24 w-24 items-center justify-center rounded-full bg-[#EAF8EC]">
              <FarmerAvatar size="md" expression="explain" />
            </div>
            <span className="absolute -right-1 -top-1 flex h-9 w-9 items-center justify-center rounded-full bg-white shadow-md">
              <Heart className="h-5 w-5 text-[#E4405F]" />
            </span>
          </div>
          <h2 className="text-lg font-black text-[#233127]">Aucun favori pour l&apos;instant</h2>
          <p className="mt-1.5 max-w-[16rem] text-[13px] font-medium leading-relaxed text-[#6F8070]">
            Touchez le cœur sur un produit pour le retrouver ici et recevoir de meilleures suggestions.
          </p>
          <button
            type="button"
            onClick={() => router.push("/catalogue")}
            className="mt-6 flex items-center gap-2 rounded-2xl bg-[#1E8A3C] px-5 py-3 text-sm font-black text-white shadow-[0_14px_30px_-16px_rgba(30,138,60,0.9)] active:scale-[0.98]"
          >
            <Sprout className="h-4 w-4" />
            Découvrir le marché
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-3 px-4 pt-2">
          {favoriteProducts.map((product) => (
            <ProductCard
              key={product.id}
              id={product.id}
              name={product.name}
              image={product.image}
              fallbackImage={product.fallbackImage}
              price={product.price}
              prixKhddarEstime={product.prix_khddar_estime}
              niveau={product.niveau}
              unit={product.unit}
              displayUnit={product.displayUnit}
              quantityStep={product.quantityStep}
              stock={product.stock}
              isFavorite={isFavorite(product.id)}
              onToggleFavorite={handleToggleFavorite}
              onView={openDetail}
              onAddToCart={handleAddToCart}
            />
          ))}
        </div>
      )}

      <ProductDetailSheet
        product={detailProduct}
        open={detailOpen}
        onClose={() => setDetailOpen(false)}
        onAddToCart={handleAddToCart}
        isFavorite={detailProduct ? isFavorite(detailProduct.id) : false}
        onToggleFavorite={() => detailProduct && toggleFavorite(detailProduct.id)}
      />

      <MobileBottomNav cartCount={cartCount} />
    </PwaScreen>
  )
}

"use client"

import { SoukiLogoLink } from "@/components/souki/souki-logo"
import { Suspense, useCallback, useEffect, useState, type CSSProperties } from "react"
import Link from "next/link"
import { useSearchParams } from "next/navigation"
import {
  ArrowLeft,
  Clock,
  History,
  Leaf,
  PackageCheck,
  ReceiptText,
  RefreshCw,
  ShoppingBasket,
} from "lucide-react"

import { MobileBottomNav } from "@/components/souki/mobile-bottom-nav"
import { SoukiEmptyState } from "@/components/souki/empty-state"
import { useAuth } from "@/hooks/useAuth"
import { useScrollReveal } from "@/hooks/useScrollReveal"
import type { CommandeHistoriqueDTO } from "@/lib/api"
import {
  fetchCatalogueProducts,
  fetchOrderHistory,
  resolveCatalogueImage,
} from "@/lib/catalogue"
import { getOrderStatusClassName, getOrderStatusLabel } from "@/lib/order-status"
import { cn } from "@/lib/utils"

type RecentProduct = {
  id: number
  name: string
  image: string
  price: number
  unit: string
  displayUnit?: string
  viewedAt: string
}

const formatDh = (value: number | string) => `${Number(value || 0).toFixed(2)} DH`

const formatOrderDate = (value?: string | null) => {
  if (!value) {
    return "Date non disponible"
  }

  const date = new Date(value)
  if (Number.isNaN(date.getTime())) {
    return "Date non disponible"
  }

  return new Intl.DateTimeFormat("fr-MA", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
  }).format(date)
}

function HistoriqueContent() {
  const searchParams = useSearchParams()
  const { isAuthenticated, isLoading } = useAuth()
  const revealRef = useScrollReveal<HTMLDivElement>()
  const [recentProducts, setRecentProducts] = useState<RecentProduct[]>([])
  const [catalogueImages, setCatalogueImages] = useState<Record<string, string>>({})
  const [orderHistory, setOrderHistory] = useState<CommandeHistoriqueDTO[]>([])
  const [isFetchingOrders, setIsFetchingOrders] = useState(false)
  const [historyError, setHistoryError] = useState("")
  const successOrderId = searchParams.get("commande_validee")

  const loadRecentProducts = () => {
    try {
      const rawHistory = window.localStorage.getItem("souki_recent_products")
      const parsedHistory = rawHistory ? JSON.parse(rawHistory) : []
      setRecentProducts(Array.isArray(parsedHistory) ? parsedHistory.slice(0, 12) : [])
    } catch {
      setRecentProducts([])
    }
  }

  const loadOrderHistory = useCallback(async () => {
    if (!isAuthenticated) {
      setOrderHistory([])
      setHistoryError("")
      return
    }

    try {
      setIsFetchingOrders(true)
      const history = await fetchOrderHistory()
      setOrderHistory(history)
      setHistoryError("")
    } catch {
      setHistoryError("Impossible de charger votre historique de commandes pour le moment.")
    } finally {
      setIsFetchingOrders(false)
    }
  }, [isAuthenticated])

  useEffect(() => {
    loadRecentProducts()
  }, [])

  useEffect(() => {
    let isMounted = true

    fetchCatalogueProducts()
      .then((products) => {
        if (!isMounted) {
          return
        }

        const imageMap = products.reduce<Record<string, string>>((acc, product) => {
          acc[String(product.id)] = product.image
          acc[product.name.toLowerCase()] = product.image
          return acc
        }, {})
        setCatalogueImages(imageMap)
      })
      .catch(() => {
        setCatalogueImages({})
      })

    return () => {
      isMounted = false
    }
  }, [])

  useEffect(() => {
    if (isLoading) {
      return
    }

    void loadOrderHistory()
  }, [isLoading, loadOrderHistory])

  const resolveOrderProductImage = (product: CommandeHistoriqueDTO["produits"][number]) => {
    const productWithImage = product as CommandeHistoriqueDTO["produits"][number] & { image?: string | null }
    if (productWithImage.image) {
      return productWithImage.image
    }

    return (
      catalogueImages[String(product.product_id)] ||
      catalogueImages[product.nom_fr.toLowerCase()] ||
      resolveCatalogueImage(product.nom_fr)
    )
  }

  return (
    <div ref={revealRef} className="min-h-screen bg-[#FBFDF9] pb-24 md:pb-0">
      <header className="sticky top-0 z-40 hidden glass-ios26 border-b border-[#E7F0E8] md:block">
        <div className="mx-auto flex h-20 max-w-7xl items-center justify-between px-4 sm:px-6 lg:px-8">
          <Link href="/catalogue" className="inline-flex items-center gap-2 rounded-2xl bg-[#F0FAF1] px-4 py-3 text-sm font-bold text-[#1E8A3C]">
            <ArrowLeft className="h-4 w-4" />
            Catalogue
          </Link>
          <SoukiLogoLink height={36} priority />
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-4 py-5 sm:px-6 md:py-8 lg:px-8">
        {successOrderId && (
          <div className="mb-5 rounded-2xl border border-[#BFE6C4] bg-[#EAF8EC] px-5 py-4 text-sm font-semibold text-[#1E8A3C]">
            Votre commande N-{successOrderId} a été enregistrée avec succès.
          </div>
        )}

        <section className="mb-6 rounded-[28px] border border-[#D7EBD9] bg-[linear-gradient(135deg,#FFFFFF_0%,#F7FCF7_58%,#FFF7EE_100%)] p-5 shadow-[0_18px_50px_-34px_rgba(0,0,0,0.2)] md:p-6">
          <div className="flex flex-col gap-5 md:flex-row md:items-end md:justify-between">
            <div>
              <span className="inline-flex items-center gap-2 rounded-full bg-white px-3 py-1.5 text-xs font-bold uppercase tracking-[0.18em] text-[#1E8A3C] ring-1 ring-[#D7EBD9]">
                <History className="h-4 w-4" />
                Historique
              </span>
              <h1 className="mt-4 text-3xl font-black leading-tight text-[#1E8A3C] md:text-4xl">
                Retrouvez vos produits consultés et vos commandes.
              </h1>
              <p className="mt-3 max-w-2xl text-sm leading-6 text-[#5F735F] md:text-base">
                Le catalogue reste dédié aux produits disponibles. Ici, vous retrouvez le contexte utile pour recommander plus vite.
              </p>
            </div>
            <button
              type="button"
              onClick={() => {
                loadRecentProducts()
                void loadOrderHistory()
              }}
              className="inline-flex min-h-12 items-center justify-center gap-2 rounded-2xl border border-[#CFE6D2] bg-white px-4 py-3 text-sm font-bold text-[#1E8A3C] transition-colors hover:bg-[#F0FAF1]"
            >
              <RefreshCw className="h-4 w-4" />
              Actualiser
            </button>
          </div>
        </section>

        <section className="mb-8" data-reveal="up">
          <div className="mb-4 flex items-center justify-between gap-4">
            <div className="flex items-center gap-2 text-[#1E8A3C]">
              <Leaf className="h-5 w-5" />
              <h2 className="text-xl font-black">Produits consultés récemment</h2>
            </div>
            <span className="rounded-full bg-white px-3 py-1 text-xs font-bold text-[#F07C00] ring-1 ring-[#F5D7B8]">
              {recentProducts.length}
            </span>
          </div>

          {recentProducts.length === 0 ? (
            <SoukiEmptyState
              icon={ShoppingBasket}
              title="Aucun produit consulté pour le moment."
              action={
                <Link href="/catalogue" className="inline-flex min-h-12 items-center justify-center rounded-2xl bg-[#1E8A3C] px-5 text-sm font-bold text-white">
                  Explorer le catalogue
                </Link>
              }
            />
          ) : (
            // Tuiles carrees cote a cote, defilement horizontal avec snap
            <div className="flex gap-3 overflow-x-auto pb-2 snap-x snap-mandatory [-webkit-overflow-scrolling:touch] sm:gap-4">
              {recentProducts.map((product, productIndex) => (
                <article
                  key={product.id}
                  className="w-36 shrink-0 snap-start overflow-hidden rounded-2xl border border-[#E6F0E7] bg-white shadow-[0_16px_45px_-34px_rgba(30,65,41,0.3)] animate-cascade sm:w-40"
                  style={{ "--cascade-i": productIndex } as CSSProperties}
                >
                  <img
                    src={resolveCatalogueImage(product.name, product.image)}
                    alt={product.name}
                    loading="lazy"
                    decoding="async"
                    className="aspect-square w-full object-cover"
                  />
                  <div className="p-3">
                    <h3 className="truncate text-sm font-black text-[#264129]">{product.name}</h3>
                    <div className="mt-1 flex items-baseline justify-between gap-2">
                      <p className="text-sm font-black text-[#F07C00]">{formatDh(product.price)}</p>
                      <span className="truncate text-[11px] font-semibold text-[#6F8070]">/ {product.displayUnit || product.unit}</span>
                    </div>
                    <div className="mt-2 flex items-center gap-1.5 text-[11px] font-semibold text-[#7B8B7D]">
                      <Clock className="h-3.5 w-3.5 shrink-0" />
                      <span className="truncate">{formatOrderDate(product.viewedAt)}</span>
                    </div>
                  </div>
                </article>
              ))}
            </div>
          )}
        </section>

        <section data-reveal="up">
          <div className="mb-4 flex flex-col justify-between gap-3 sm:flex-row sm:items-center">
            <div className="flex items-center gap-2 text-[#1E8A3C]">
              <ReceiptText className="h-5 w-5" />
              <h2 className="text-xl font-black">Historique des commandes</h2>
            </div>
            {isAuthenticated && (
              <span className="rounded-full bg-white px-3 py-1 text-xs font-bold text-[#F07C00] ring-1 ring-[#F5D7B8]">
                {orderHistory.length} commande{orderHistory.length > 1 ? "s" : ""}
              </span>
            )}
          </div>

          {!isAuthenticated && !isLoading ? (
            <div className="rounded-[24px] border border-[#F3D8B2] bg-[#FFF7EE] p-6">
              <p className="text-sm font-semibold text-[#9A5C11]">
                Connectez-vous pour afficher vos commandes validées.
              </p>
              <Link href="/login?redirect=/historique" className="mt-4 inline-flex min-h-12 items-center justify-center rounded-2xl bg-[#F07C00] px-5 text-sm font-bold text-white">
                Se connecter
              </Link>
            </div>
          ) : isFetchingOrders ? (
            <div className="grid gap-4 lg:grid-cols-2">
              {Array.from({ length: 2 }).map((_, index) => (
                <div key={index} className="souki-skeleton h-44 rounded-[24px]" />
              ))}
            </div>
          ) : historyError ? (
            <div className="rounded-[24px] border border-red-200 bg-red-50 p-5 text-sm font-semibold text-red-600">
              {historyError}
            </div>
          ) : orderHistory.length === 0 ? (
            <SoukiEmptyState
              icon={PackageCheck}
              illustrationSrc="/illustrations/empty-orders.webp"
              title="Aucune commande validée pour le moment."
              description="Votre première commande de produits frais apparaîtra ici."
            />
          ) : (
            <div className="grid gap-4 lg:grid-cols-2">
              {orderHistory.map((order, orderIndex) => (
                <article
                  key={order.id}
                  className="overflow-hidden rounded-2xl border border-[#E6F0E7] bg-white shadow-[0_18px_55px_-36px_rgba(30,65,41,0.35)] animate-cascade"
                  style={{ "--cascade-i": orderIndex } as CSSProperties}
                >
                  <div className="h-1.5 bg-gradient-to-r from-[#1E8A3C] via-[#4CB84A] to-[#F07C00]" />
                  <div className="flex flex-wrap items-start justify-between gap-3 p-5">
                    <div>
                      <p className="text-xs font-bold uppercase tracking-[0.18em] text-[#7B8B7D]">Commande N-{order.id}</p>
                      <h3 className="mt-1 text-lg font-black text-[#264129]">{formatOrderDate(order.date_commande)}</h3>
                    </div>
                    <span className={cn("rounded-full border px-3 py-1 text-xs font-bold", getOrderStatusClassName(order.statut))}>
                      {getOrderStatusLabel(order.statut)}
                    </span>
                  </div>
                  <div className="space-y-3 px-5 pb-5">
                    {order.produits.slice(0, 4).map((product, index) => (
                      <div key={`${order.id}-${product.nom_fr}-${index}`} className="flex items-center gap-3 rounded-2xl bg-[#F7FCF7] p-3 text-sm">
                        <img
                          src={resolveOrderProductImage(product)}
                          alt={product.nom_fr}
                          className="h-12 w-12 shrink-0 rounded-xl object-cover"
                        />
                        <div className="min-w-0 flex-1">
                          <p className="truncate font-semibold text-[#264129]">{product.nom_fr}</p>
                          <p className="text-xs font-semibold text-[#6F8070]">{product.quantite_kg} kg</p>
                        </div>
                        <span className="shrink-0 text-sm font-bold text-[#F07C00]">
                          {typeof product.sous_total === "number" ? formatDh(product.sous_total) : ""}
                        </span>
                      </div>
                    ))}
                    <div className="flex items-center justify-between border-t border-[#EEF2EE] pt-4">
                      <span className="font-bold text-[#264129]">Total</span>
                      <span className="text-xl font-black text-[#F07C00]">{formatDh(order.montant_total || 0)}</span>
                    </div>
                    <Link
                      href={`/suivi-commande?commande=${order.id}`}
                      className="inline-flex min-h-11 w-full items-center justify-center rounded-2xl bg-[#F0FAF1] px-4 text-sm font-bold text-[#176B2E] transition-colors hover:bg-[#E4F5E7] active:translate-y-px"
                    >
                      Voir l’avancement
                    </Link>
                  </div>
                </article>
              ))}
            </div>
          )}
        </section>
      </main>

      <MobileBottomNav />
    </div>
  )
}

export default function HistoriquePage() {
  return (
    <Suspense
      fallback={
        <div className="flex min-h-screen items-center justify-center bg-[#FBFDF9]">
          <div className="h-10 w-10 animate-spin rounded-full border-4 border-[#1E8A3C] border-t-transparent" />
        </div>
      }
    >
      <HistoriqueContent />
    </Suspense>
  )
}

"use client"

import { SoukiLogoLink } from "@/components/souki/souki-logo"
import { Suspense, useState } from "react"
import Link from "next/link"
import { useRouter, useSearchParams } from "next/navigation"
import { useAuth } from "@/hooks/useAuth"
import { API_BASE_URL } from "@/lib/api"
import { isValidMoroccanPhone, normalizeMoroccanPhone, PHONE_ERROR_MSG } from "@/lib/phoneValidator"
import { GoogleLoginButton } from "@/components/auth/google-login-button"
import { PasswordStrength } from "@/components/souki/password-strength"
import { PolicyLink } from "@/components/souki/policy-link"
import { shouldShowOnboarding } from "@/lib/onboarding"
import { toast } from "sonner"
import {
  Eye,
  EyeOff,
  Mail,
  Lock,
  User,
  Phone,
  MapPin,
  Clock,
  ChevronDown,
  Check,
  Loader2,
  AlertCircle,
  Gift
} from "lucide-react"

type AuthMode = "login" | "signup"
type UserRole = "client"

const cities = ["Fès", "Meknès", "Casablanca", "Rabat"]
function ClientLoginContent() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const { login, googleLogin } = useAuth()
  const requestedRedirect = searchParams.get("redirect") || "/"
  const redirectTarget =
    requestedRedirect.startsWith("/") &&
    !requestedRedirect.startsWith("//") &&
    !/[\\\u0000-\u0020]/.test(requestedRedirect)
      ? requestedRedirect
      : "/"
  const refParam = (searchParams.get("ref") || "").toUpperCase()
  const [mode, setMode] = useState<AuthMode>(refParam ? "signup" : "login")

  // UI States
  const [showPassword, setShowPassword] = useState(false)
  const [showConfirmPassword, setShowConfirmPassword] = useState(false)
  const [rememberMe, setRememberMe] = useState(false)
  const [acceptTerms, setAcceptTerms] = useState(false)
  const [showCityDropdown, setShowCityDropdown] = useState(false)

  // Form States
  const [selectedRole, setSelectedRole] = useState<UserRole>("client")
  const [selectedCity, setSelectedCity] = useState("")
  const [firstName, setFirstName] = useState("");
  const [lastName, setLastName] = useState("");
  const [phone, setPhone] = useState("");
  const [loginId, setLoginId] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [referralCode, setReferralCode] = useState(refParam);

  // Loading & Error States
  const [error, setError] = useState("");
  const [formErrors, setFormErrors] = useState<{ [key: string]: string }>({});
  const [loading, setLoading] = useState(false);

  const resetForm = () => {
    setError("");
    setFormErrors({});
    setPassword("");
    setConfirmPassword("");
    setPhone("");
    setLoginId("");
  };

  const handleFieldChange = (field: string, value: string) => {
    if (field === "firstName") setFirstName(value);
    if (field === "lastName") setLastName(value);
    if (field === "loginId") setLoginId(value);
    if (field === "phone") setPhone(value);
    if (field === "password") setPassword(value);
    if (field === "confirmPassword") setConfirmPassword(value);

    if (mode === "signup") {
      let currentError = "";

      if (field === "phone") {
        if (value && !isValidMoroccanPhone(value)) {
          currentError = PHONE_ERROR_MSG;
        }
      }

      if (field === "password") {
        if (value.length > 0 && value.length < 8) currentError = "8 caractères minimum requis.";
        else if (value.length > 0 && !/[A-Z]/.test(value)) currentError = "Doit contenir une lettre majuscule.";
        else if (value.length > 0 && !/[0-9]/.test(value)) currentError = "Doit contenir au moins un chiffre.";

        if (confirmPassword && value !== confirmPassword) {
          setFormErrors(prev => ({ ...prev, confirmPassword: "Les mots de passe ne correspondent pas." }));
        } else if (confirmPassword && value === confirmPassword) {
          setFormErrors(prev => { const n = {...prev}; delete n.confirmPassword; return n; });
        }
      }

      if (field === "confirmPassword") {
        if (value && value !== password) {
          currentError = "Les mots de passe ne correspondent pas.";
        }
      }

      setFormErrors(prev => {
        if (!currentError) {
          const newErrors = { ...prev };
          delete newErrors[field];
          return newErrors;
        }
        return { ...prev, [field]: currentError };
      });
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError("");

    if (Object.keys(formErrors).length > 0) return;

    // ── Strict email format validation (prevents malformed input & injection) ──
    const EMAIL_REGEX = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*\.[a-zA-Z]{2,}$/
    const trimmedId = loginId.trim()
    // Validate as email only when the field looks like an email (contains @)
    if (trimmedId.includes("@") && !EMAIL_REGEX.test(trimmedId)) {
      setError("Format d'email invalide. Veuillez saisir une adresse email correcte (ex: nom@domaine.ma).")
      return
    }

    setLoading(true);

    try {
      if (mode === "signup") {
        if (password !== confirmPassword) {
          setFormErrors(prev => ({ ...prev, confirmPassword: "Les mots de passe ne correspondent pas." }));
          setLoading(false);
          return;
        }
        if (!acceptTerms) {
          throw new Error("Vous devez accepter la politique de confidentialité.");
        }

        const formattedPhone = phone.trim() ? normalizeMoroccanPhone(phone) : "";

        const response = await fetch(`${API_BASE_URL}/auth/register`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            email: loginId,
            phone: formattedPhone || undefined,
            password: password,
            role: selectedRole.toUpperCase(),
            code_parrainage: referralCode.trim() || undefined
          }),
        });

        const data = await response.json();

        if (!response.ok) {
          if (response.status === 422 && typeof data.detail === "object") {
             setFormErrors(data.detail);
             setLoading(false);
             return;
          }
          throw new Error(data.detail || "Erreur lors de la création du compte.");
        }

        router.push(
          `/verify?userId=${data.id}&channel=${data.verification_channel}&target=${encodeURIComponent(data.verification_target || "")}&role=${String(data.role || selectedRole).toLowerCase()}${redirectTarget !== "/" ? `&redirect=${encodeURIComponent(redirectTarget)}` : ""}`
        );
        toast.success("Compte cree avec succes. Vous pouvez maintenant vous connecter.")
        return;

      } else {
        // --- NOUVELLE LOGIQUE DE CONNEXION SÉCURISÉE ---
        const nextUser = await login(loginId, password, "CLIENT");
        // Mark this device as having logged in before (used for "Rebonjour" greeting)
        if (typeof window !== "undefined") {
          window.localStorage.setItem("souki_has_logged_in", "true")
        }
        const dest = redirectTarget !== "/" ? redirectTarget : shouldShowOnboarding(nextUser) ? "/onboarding" : nextUser.default_dashboard || "/";
        router.push(dest);
      }
    } catch (err: any) {
      setError(
        err instanceof TypeError
          ? `Impossible de joindre l'API (${API_BASE_URL}). Verifiez que le back-end est demarre et accessible depuis le front.`
          : err.message || "Une erreur inattendue est survenue."
      );
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async (credential: string) => {
    setError("")
    const nextUser = await googleLogin(credential, "CLIENT")
    const dest = redirectTarget !== "/" ? redirectTarget : shouldShowOnboarding(nextUser) ? "/onboarding" : nextUser.default_dashboard || "/"
    router.push(dest)
  }

  const ErrorMessage = ({ message }: { message?: string }) => {
    if (!message) return null;
    return (
      <div className="flex items-center gap-1.5 mt-1.5 ml-1">
        <AlertCircle className="w-4 h-4 text-red-500" />
        <span className="text-red-500 text-xs font-medium">{message}</span>
      </div>
    );
  };

  return (
    <div className="min-h-screen flex">
      {/* Left Side - Brand Visual */}
      <div className="hidden lg:flex lg:w-1/2 bg-gradient-to-br from-[#1E8A3C] to-[#4CB84A] p-12 flex-col justify-between relative overflow-hidden">
        <div className="absolute inset-0 opacity-10">
          <div className="absolute top-20 left-20 text-8xl rotate-12 animate-bounce" style={{ animationDuration: '3s' }}></div>
          <div className="absolute top-40 right-32 text-7xl -rotate-12 animate-bounce" style={{ animationDuration: '4s', animationDelay: '1s' }}></div>
          <div className="absolute bottom-40 left-32 text-6xl rotate-45 animate-bounce" style={{ animationDuration: '5s', animationDelay: '0.5s' }}></div>
          <div className="absolute bottom-20 right-20 text-8xl -rotate-6 animate-bounce" style={{ animationDuration: '3.5s', animationDelay: '1.5s' }}></div>
        </div>

        <div className="relative z-10">
          <SoukiLogoLink variant="secondary" height={104} support priority />
        </div>

        <div className="relative z-10 flex-1 flex flex-col justify-center">
          <h1 className="text-4xl xl:text-5xl font-bold text-white mb-6 leading-tight text-balance">
            Du champ au panier, le matin même.
          </h1>
          <p className="text-xl text-white/80 mb-8 max-w-md">
            Légumes frais du marché de gros de Fès, livrés chez vous entre 8h et 15h.
          </p>

          <div className="flex items-center gap-3 bg-white/10 backdrop-blur-sm rounded-2xl p-4 max-w-sm">
            <div className="p-2 bg-white/20 rounded-xl">
              <Clock className="w-6 h-6 text-white" />
            </div>
            <div>
              <p className="text-white font-semibold">Livraison dès 8h00</p>
              <p className="text-white/70 text-sm">Fès, Maroc</p>
            </div>
          </div>
        </div>

        <div className="relative z-10 text-white/60 text-sm">
          © 2026 SOUKI Fresh Market
        </div>
      </div>

      {/* Right Side - Form */}
      <div className="flex-1 flex flex-col justify-center px-6 lg:px-12 xl:px-20 py-12 bg-white overflow-y-auto">
        <div className="max-w-md mx-auto w-full">
          {/* Mobile logo */}
          <div className="lg:hidden mb-8">
            <SoukiLogoLink variant="secondary" height={104} support priority />
          </div>

          {/* Tabs */}
          <div className="flex gap-4 mb-6 border-b border-gray-200">
            <button
              onClick={() => { setMode("login"); resetForm(); }}
              className={`pb-4 px-2 font-semibold text-lg transition-colors relative ${
                mode === "login" ? "text-[#1E8A3C]" : "text-[#8A8A8A] hover:text-[#3D3D3D]"
              }`}
            >
              Se connecter
              {mode === "login" && (
                <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-[#1E8A3C]" />
              )}
            </button>
            <button
              onClick={() => { setMode("signup"); resetForm(); }}
              className={`pb-4 px-2 font-semibold text-lg transition-colors relative ${
                mode === "signup" ? "text-[#1E8A3C]" : "text-[#8A8A8A] hover:text-[#3D3D3D]"
              }`}
            >
              S'inscrire
              {mode === "signup" && (
                <span className="absolute bottom-0 left-0 right-0 h-0.5 bg-[#1E8A3C]" />
              )}
            </button>
          </div>

          {/* Affichage des Erreurs Générales */}
          {error && (
            <div className="mb-6 flex items-start gap-3 p-4 bg-red-50 text-red-700 rounded-xl text-sm font-medium border border-red-200">
              <AlertCircle className="w-5 h-5 flex-shrink-0" />
              <p>{error}</p>
            </div>
          )}

          {/* Login Form */}
          {mode === "login" && (
            <form onSubmit={handleSubmit} className="space-y-5">
              <div>
                <label className="block text-sm font-medium text-[#3D3D3D] mb-2">
                  Email ou Téléphone
                </label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#8A8A8A]" />
                  <input
                    type="text"
                    required
                    placeholder="votre@email.com ou 06XXXXXXXX"
                    className="w-full pl-12 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors"
                    value={loginId}
                    onChange={(e) => handleFieldChange("loginId", e.target.value)}
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-[#3D3D3D] mb-2">
                  Mot de passe
                </label>
                <div className="relative">
                  <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#8A8A8A]" />
                  <input
                    type={showPassword ? "text" : "password"}
                    required
                    placeholder="••••••••"
                    className="w-full pl-12 pr-12 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors"
                    value={password}
                    onChange={(e) => handleFieldChange("password", e.target.value)}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-4 top-1/2 -translate-y-1/2 text-[#8A8A8A] hover:text-[#3D3D3D]"
                  >
                    {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                  </button>
                </div>
              </div>

              <div className="flex items-center justify-between">
                <label className="flex items-center gap-2 cursor-pointer">
                  <div
                    onClick={() => setRememberMe(!rememberMe)}
                    className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-colors ${
                      rememberMe ? "bg-[#1E8A3C] border-[#1E8A3C]" : "border-gray-300"
                    }`}
                  >
                    {rememberMe && <Check className="w-3 h-3 text-white" />}
                  </div>
                  <span className="text-sm text-[#3D3D3D]">Se souvenir de moi</span>
                </label>
                <Link href="/forgot-password" className="text-sm text-[#1A4F8A] hover:underline">
                  Mot de passe oublié ?
                </Link>
              </div>

              <button
                type="submit"
                disabled={loading}
                className="w-full flex items-center justify-center py-3.5 bg-[#1E8A3C] text-white rounded-xl font-semibold text-lg hover:bg-[#166E2B] transition-colors shadow-lg shadow-[#1E8A3C]/30 disabled:opacity-70"
              >
                {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : "Se connecter"}
              </button>

              <div className="relative my-6">
                <div className="absolute inset-0 flex items-center">
                  <div className="w-full border-t border-gray-200" />
                </div>
                <div className="relative flex justify-center text-sm">
                  <span className="px-4 bg-white text-[#8A8A8A]">ou continuer avec</span>
                </div>
              </div>

              <GoogleLoginButton
                onCredential={handleGoogleLogin}
                onError={setError}
                disabled={loading}
              />
            </form>
          )}

          {/* Signup Form */}
          {mode === "signup" && (
            <form onSubmit={handleSubmit} className="space-y-4 pb-12">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-[#3D3D3D] mb-2">Prénom</label>
                  <div className="relative">
                    <User className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#8A8A8A]" />
                    <input
                      type="text"
                      placeholder="Prénom"
                      value={firstName}
                      onChange={(e) => handleFieldChange("firstName", e.target.value)}
                      className="w-full pl-12 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors"
                    />
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-medium text-[#3D3D3D] mb-2">Nom</label>
                  <input
                    type="text"
                    placeholder="Nom"
                    value={lastName}
                    onChange={(e) => handleFieldChange("lastName", e.target.value)}
                    className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors"
                  />
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-[#3D3D3D] mb-2">Email</label>
                <div className="relative">
                  <Mail className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#8A8A8A]" />
                  <input
                    type="email"
                    required
                    placeholder="votre@email.com"
                    value={loginId}
                    onChange={(e) => handleFieldChange("loginId", e.target.value)}
                    className={`w-full pl-12 pr-4 py-3 border-2 rounded-xl focus:outline-none transition-colors ${
                      formErrors.email ? "border-red-500 bg-red-50" : "border-gray-200 focus:border-[#4CB84A]"
                    }`}
                  />
                </div>
                <ErrorMessage message={formErrors.email} />
              </div>

              <div>
                <label className="block text-sm font-medium text-[#3D3D3D] mb-2">Téléphone</label>
                <div className="flex gap-2">
                  <div className={`flex items-center gap-1 px-3 py-3 border-2 rounded-xl text-[#3D3D3D] ${
                    formErrors.phone ? "border-red-500 bg-red-50" : "border-gray-200 bg-gray-50"
                  }`}>
                    <span className="text-lg font-bold">MA</span>
                    <span>+212</span>
                  </div>
                  <div className="relative flex-1">
                    <Phone className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#8A8A8A]" />
                    <input
                      type="tel"
                      placeholder="6XX-XXXXXX"
                      value={phone}
                      onChange={(e) => handleFieldChange("phone", e.target.value)}
                      className={`w-full pl-12 pr-4 py-3 border-2 rounded-xl focus:outline-none transition-colors ${
                        formErrors.phone ? "border-red-500 bg-red-50" : "border-gray-200 focus:border-[#4CB84A]"
                      }`}
                    />
                  </div>
                </div>
                <ErrorMessage message={formErrors.phone} />
              </div>

              <div>
                <label className="block text-sm font-medium text-[#3D3D3D] mb-2">Ville</label>
                <div className="relative">
                  <MapPin className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#8A8A8A]" />
                  <button
                    type="button"
                    onClick={() => setShowCityDropdown(!showCityDropdown)}
                    className="w-full pl-12 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors text-left flex items-center justify-between bg-white"
                  >
                    <span className={selectedCity ? "text-[#3D3D3D]" : "text-[#8A8A8A]"}>
                      {selectedCity || "Sélectionnez votre ville"}
                    </span>
                    <ChevronDown className={`w-5 h-5 text-[#8A8A8A] transition-transform ${showCityDropdown ? "rotate-180" : ""}`} />
                  </button>
                  {showCityDropdown && (
                    <div className="absolute top-full left-0 right-0 mt-2 bg-white border-2 border-gray-200 rounded-xl shadow-lg z-10 overflow-hidden">
                      {cities.map(city => (
                        <button
                          key={city}
                          type="button"
                          onClick={() => {
                            setSelectedCity(city)
                            setShowCityDropdown(false)
                          }}
                          className={`w-full px-4 py-3 text-left hover:bg-[#F0FAF1] transition-colors ${
                            selectedCity === city ? "bg-[#F0FAF1] text-[#1E8A3C]" : "text-[#3D3D3D]"
                          }`}
                        >
                          {city}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-[#3D3D3D] mb-2">Mot de passe</label>
                <div className="relative">
                  <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#8A8A8A]" />
                  <input
                    type={showPassword ? "text" : "password"}
                    required
                    placeholder="••••••••"
                    value={password}
                    onChange={(e) => handleFieldChange("password", e.target.value)}
                    className={`w-full pl-12 pr-12 py-3 border-2 rounded-xl focus:outline-none transition-colors ${
                      formErrors.password ? "border-red-500 bg-red-50" : "border-gray-200 focus:border-[#4CB84A]"
                    }`}
                  />
                  <button
                    type="button"
                    onClick={() => setShowPassword(!showPassword)}
                    className="absolute right-4 top-1/2 -translate-y-1/2 text-[#8A8A8A] hover:text-[#3D3D3D]"
                  >
                    {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                  </button>
                </div>
                <PasswordStrength password={password} />
                <ErrorMessage message={formErrors.password} />
              </div>

              <div>
                <label className="block text-sm font-medium text-[#3D3D3D] mb-2">Confirmer le mot de passe</label>
                <div className="relative">
                  <Lock className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#8A8A8A]" />
                  <input
                    type={showConfirmPassword ? "text" : "password"}
                    required
                    placeholder="••••••••"
                    value={confirmPassword}
                    onChange={(e) => handleFieldChange("confirmPassword", e.target.value)}
                    className={`w-full pl-12 pr-12 py-3 border-2 rounded-xl focus:outline-none transition-colors ${
                      formErrors.confirmPassword ? "border-red-500 bg-red-50" : "border-gray-200 focus:border-[#4CB84A]"
                    }`}
                  />
                  <button
                    type="button"
                    onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                    className="absolute right-4 top-1/2 -translate-y-1/2 text-[#8A8A8A] hover:text-[#3D3D3D]"
                  >
                    {showConfirmPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
                  </button>
                </div>
                <ErrorMessage message={formErrors.confirmPassword} />
              </div>

              {/* Role Selector */}
              <div>
                <label className="block text-sm font-medium text-[#3D3D3D] mb-2">Type de compte</label>
                <div className="flex gap-2">
                  {[
                    { value: "client", label: "Client" },
                  ].map(role => (
                    <button
                      key={role.value}
                      type="button"
                      onClick={() => setSelectedRole(role.value as UserRole)}
                      className={`flex-1 py-2.5 rounded-xl font-medium text-sm transition-all border-2 ${
                        selectedRole === role.value
                          ? "bg-[#1E8A3C] border-[#1E8A3C] text-white shadow-md shadow-[#1E8A3C]/20"
                          : "bg-white border-gray-200 text-[#3D3D3D] hover:border-[#1E8A3C]/30 hover:bg-[#F0FAF1]"
                      }`}
                    >
                      {role.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Code de parrainage (optionnel) */}
              <div>
                <label className="block text-sm font-medium text-[#3D3D3D] mb-2">
                  Code de parrainage <span className="text-[#8A8A8A] font-normal">(optionnel)</span>
                </label>
                <div className="relative">
                  <Gift className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-[#8A8A8A]" />
                  <input
                    type="text"
                    placeholder="Ex : K7M2P9"
                    value={referralCode}
                    onChange={(e) => setReferralCode(e.target.value.toUpperCase())}
                    maxLength={10}
                    className="w-full pl-12 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors font-mono tracking-[0.2em] uppercase placeholder:font-sans placeholder:tracking-normal placeholder:normal-case"
                  />
                </div>
                {referralCode && (
                  <p className="flex items-center gap-1.5 mt-1.5 ml-1 text-xs font-medium text-[#1E8A3C]">
                    <Gift className="w-3.5 h-3.5" /> Tu recevras un produit offert sur ta 1ère commande livrée.
                  </p>
                )}
              </div>

              <div className="flex items-start gap-2 pt-2">
                <div
                  onClick={() => setAcceptTerms(!acceptTerms)}
                  className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-colors cursor-pointer flex-shrink-0 mt-0.5 ${
                    acceptTerms ? "bg-[#1E8A3C] border-[#1E8A3C]" : "border-gray-300"
                  }`}
                >
                  {acceptTerms && <Check className="w-3 h-3 text-white" />}
                </div>
                <span className="text-sm text-[#3D3D3D]">
                  J'accepte la{" "}
                  <PolicyLink className="text-[#1A4F8A] hover:underline" />
                </span>
              </div>

              <button
                type="submit"
                disabled={loading || Object.keys(formErrors).length > 0}
                className="w-full flex items-center justify-center py-3.5 bg-[#1E8A3C] text-white rounded-xl font-semibold text-lg hover:bg-[#166E2B] transition-colors shadow-lg shadow-[#1E8A3C]/30 disabled:opacity-50 mt-4"
              >
                {loading ? <Loader2 className="w-6 h-6 animate-spin" /> : "Créer mon compte"}
              </button>
            </form>
          )}
        </div>
      </div>
    </div>
  )
}

export default function LoginPage() {
  return (
    <Suspense
      fallback={
        <div className="min-h-screen bg-white flex items-center justify-center">
          <Loader2 className="h-6 w-6 animate-spin text-[#1E8A3C]" />
        </div>
      }
    >
      <ClientLoginContent />
    </Suspense>
  )
}

"use client"

import { SoukiLogoLink } from "@/components/souki/souki-logo"
import { useEffect, useMemo, useRef, useState } from "react"
import Link from "next/link"
import { usePathname, useRouter } from "next/navigation"
import {
  ArrowLeft, User, Bell, Shield, CreditCard, MapPin, Phone, Mail, Camera, Save, Trash2, LogOut,
  Globe, Smartphone, Lock, Eye, EyeOff, Check, ChevronRight, Wallet, Loader2, Copy, ShieldCheck, Sparkles, AlertTriangle, Gift, Share2
} from "lucide-react"
import { cn } from "@/lib/utils"
import {
  getBlacklistStatus,
  markBlacklistLiftNotificationSeen,
  requestBlacklistLift,
  type BlacklistStatusDTO,
} from "@/lib/api"
import { useProfile } from "@/hooks/useProfile"
import { useNotifications, type NotificationPrefs } from "@/hooks/useNotifications"
import { usePushNotifications } from "@/hooks/usePushNotifications"
import { useSecurity } from "@/hooks/useSecurity"
import { useWallet, type WalletState } from "@/hooks/useWallet"
import { useAuth } from "@/hooks/useAuth"


type Section = "compte" | "notifications" | "securite" | "paiement"
const sections: Section[] = ["compte", "notifications", "securite", "paiement"]
const getSectionFromPath = (pathname: string): Section => {
  const lastSegment = pathname.split("/").filter(Boolean).at(-1)
  return sections.includes(lastSegment as Section) ? (lastSegment as Section) : "compte"
}

type SettingsBootstrapResponse = {
  profile: {
    prenom: string
    nom: string
    email: string
    telephone: string
    photo_url?: string | null
    avatar_url?: string | null
    email_verified: boolean
    address: {
      adresse: string
      ville: string
      code_postal: string
    }
  }
  notifications: NotificationPrefs
  sessions: Array<any>
  wallet: any
}

const moroccanCities = ["Fès", "Casablanca", "Rabat", "Marrakech", "Agadir", "Tanger", "Meknès", "Oujda", "Kénitra", "Tétouan"]
const initialNotif: NotificationPrefs = { email: true, push: true, sms: false, promotions: true, orderUpdates: true, newsletter: false, livraison: true }
const acceptedPhotoTypes = ["image/jpeg", "image/png", "image/webp"]
const maxPhotoSize = 2 * 1024 * 1024

function Toggle({ checked, onCheckedChange, disabled }: { checked: boolean; onCheckedChange: (v: boolean) => void; disabled?: boolean }) {
  return <button type="button" role="switch" aria-checked={checked} disabled={disabled} onClick={() => onCheckedChange(!checked)} className={cn("relative inline-flex h-6 w-11 shrink-0 items-center rounded-full transition-colors duration-200 focus:outline-none disabled:opacity-50", checked ? "bg-[#1E8A3C]" : "bg-gray-200")}><span className={cn("inline-block h-4 w-4 transform rounded-full bg-white shadow-md transition-transform duration-200", checked ? "translate-x-6" : "translate-x-1")} /></button>
}

function SectionCard({ title, children, onSave, saving }: { title: string; children: React.ReactNode; onSave?: () => void; saving?: boolean }) {
  return (
    <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
      <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between">
        <h2 className="font-bold text-[#3D3D3D] text-lg">{title}</h2>
        {onSave && <button onClick={onSave} disabled={saving} className="flex items-center gap-2 px-4 py-2 bg-[#1E8A3C] text-white rounded-xl text-sm font-semibold hover:bg-[#176B2E] transition-colors disabled:opacity-70">{saving ? <Loader2 className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}Enregistrer</button>}
      </div>
      <div className="p-6">{children}</div>
    </div>
  )
}

function dhFromCentimes(c: number) { return `${(c / 100).toFixed(2).replace(".", ",")} DH` }
import { isValidMoroccanPhone, normalizeMoroccanPhone } from "@/lib/phoneValidator"
const isMoroccanPhone = (v: string) => isValidMoroccanPhone(v)
const isEmail = (v: string) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)
const walletPasswordChecks = (value: string) => ({
  minLength: value.length >= 8,
  uppercase: /[A-Z]/.test(value),
  number: /\d/.test(value),
  special: /[^A-Za-z0-9]/.test(value),
})
const isWalletPasswordStrong = (value: string) => {
  const checks = walletPasswordChecks(value)
  return Object.values(checks).every(Boolean)
}

export default function ParametresPage() {
  const router = useRouter()
  const pathname = usePathname()
  const { user, logout, isLoading: isAuthLoading, isAuthenticated, token } = useAuth()
  const profileApi = useProfile()
  const notifApi = useNotifications()
  const push = usePushNotifications()
  const securityApi = useSecurity()
  const walletApi = useWallet()
  const { callApi } = profileApi
  const fileInputRef = useRef<HTMLInputElement>(null)
  const bootstrapRequestRef = useRef(false)
  const [activeSection, setActiveSection] = useState<Section>(() => getSectionFromPath(pathname))
  const [saved, setSaved] = useState(false)
  const [showPassword, setShowPassword] = useState(false)
  const [showDeleteModal, setShowDeleteModal] = useState(false)
  const [showWalletActivate, setShowWalletActivate] = useState(false)
  const [showWalletPassword, setShowWalletPassword] = useState(false)
  const [showWalletConfirmPassword, setShowWalletConfirmPassword] = useState(false)
  const [showWalletIdModal, setShowWalletIdModal] = useState(false)
  const [walletIdFull, setWalletIdFull] = useState("")
  const [deleteText, setDeleteText] = useState("")
  const [errors, setErrors] = useState<Record<string, string>>({})
  const [personal, setPersonal] = useState({ prenom: "", nom: "", email: "", telephone: "" })
  const [photoUrl, setPhotoUrl] = useState<string | null>(null)
  const [emailVerified, setEmailVerified] = useState(false)
  const [address, setAddress] = useState({ adresse: "", ville: moroccanCities[0], code_postal: "" })
  const [notifications, setNotifications] = useState<NotificationPrefs>(initialNotif)
  const [passwords, setPasswords] = useState({ current_password: "", new_password: "", confirm_password: "" })
  const [sessions, setSessions] = useState<Array<any>>([])
  const [walletState, setWalletState] = useState<WalletState | null>(null)
  const [walletCreate, setWalletCreate] = useState({ password: "", confirm_password: "" })
  const [photoUploading, setPhotoUploading] = useState(false)
  // Pop bref de l'avatar une fois la photo reellement enregistree cote API.
  const [photoJustSaved, setPhotoJustSaved] = useState(false)
  const [pageLoading, setPageLoading] = useState(true)
  const [blacklistStatus, setBlacklistStatus] = useState<BlacklistStatusDTO | null>(null)
  const [showLiftModal, setShowLiftModal] = useState(false)
  const [hideLiftNotification, setHideLiftNotification] = useState(false)
  const [liftMotif, setLiftMotif] = useState("")
  const [liftRequestMessage, setLiftRequestMessage] = useState("")
  const [isSendingLiftRequest, setIsSendingLiftRequest] = useState(false)

  const showSaved = () => { setSaved(true); setTimeout(() => setSaved(false), 2000) }

  const [copiedReferral, setCopiedReferral] = useState(false)
  const referralCode = user?.profiles?.client?.code_parrainage || ""
  const referralLink =
    typeof window !== "undefined" && referralCode
      ? `${window.location.origin}/login/client?ref=${referralCode}`
      : ""

  const copyReferralCode = async () => {
    if (!referralCode) return
    try {
      await navigator.clipboard.writeText(referralCode)
      setCopiedReferral(true)
      setTimeout(() => setCopiedReferral(false), 2000)
    } catch {
      /* presse-papiers indisponible */
    }
  }

  const shareReferral = async () => {
    if (!referralCode) return
    const message = `Rejoins-moi sur SOUKI avec mon code de parrainage ${referralCode} et reçois un produit offert sur ta 1ère commande livrée !`
    try {
      if (typeof navigator !== "undefined" && navigator.share) {
        await navigator.share({ title: "SOUKI Fresh Market", text: message, url: referralLink })
      } else {
        await navigator.clipboard.writeText(`${message} ${referralLink}`)
        setCopiedReferral(true)
        setTimeout(() => setCopiedReferral(false), 2000)
      }
    } catch {
      /* partage annule par l'utilisateur */
    }
  }

  useEffect(() => {
    setActiveSection(getSectionFromPath(pathname))
  }, [pathname])

  useEffect(() => {
    const load = async () => {
      if (isAuthLoading) {
        return
      }

      if (!isAuthenticated && !token) {
        bootstrapRequestRef.current = false
        setPageLoading(false)
        router.push("/login?redirect=/parametres")
        return
      }

      if (bootstrapRequestRef.current) {
        return
      }

      bootstrapRequestRef.current = true

      setPageLoading(true)
      try {
        const data = await callApi<SettingsBootstrapResponse>("/api/user/bootstrap")
        const p = data.profile
        const n = data.notifications
        const s = data.sessions
        const w = data.wallet
        setPersonal({ prenom: p.prenom ?? "", nom: p.nom ?? "", email: p.email ?? "", telephone: p.telephone ?? "" })
        setPhotoUrl(p.photo_url ?? p.avatar_url ?? null)
        setEmailVerified(Boolean(p.email_verified))
        setAddress({ adresse: p.address.adresse ?? "", ville: p.address.ville || moroccanCities[0], code_postal: p.address.code_postal ?? "" })
        setNotifications(n)
        setSessions(s)
        setWalletState(w)
      } catch (e) {
        setErrors((prev) => ({
          ...prev,
          page: e instanceof Error ? e.message : "Impossible de charger vos paramètres",
        }))
        bootstrapRequestRef.current = false
      } finally {
        setPageLoading(false)
      }
    }
    void load()
  }, [
    isAuthLoading,
    isAuthenticated,
    token,
    router,
    callApi,
  ])

  useEffect(() => {
    if (!token || isAuthLoading || !isAuthenticated) {
      setBlacklistStatus(null)
      return
    }

    let isMounted = true
    getBlacklistStatus(token)
      .then((status) => {
        if (isMounted) {
          setBlacklistStatus(status)
        }
      })
      .catch(() => {
        if (isMounted) {
          setBlacklistStatus(null)
        }
      })

    return () => {
      isMounted = false
    }
  }, [isAuthLoading, isAuthenticated, token])

  const sidebarName = `${personal.prenom} ${personal.nom}`.trim() || "Utilisateur"
  const initialLetter = (personal.nom?.[0] || personal.prenom?.[0] || "U").toUpperCase()

  const onSavePersonal = async () => {
    const nextErrors: Record<string, string> = {}
    if (!isEmail(personal.email)) nextErrors.email = "Email invalide"
    if (!isMoroccanPhone(personal.telephone)) nextErrors.telephone = "Format marocain requis (ex: 0612345678)"
    setErrors(nextErrors); if (Object.keys(nextErrors).length) return
    const normalizedPersonal = { ...personal, telephone: normalizeMoroccanPhone(personal.telephone) }
    try {
      const res = await profileApi.updateProfile(normalizedPersonal)
      if (res.email_changed) setErrors((e) => ({ ...e, email_info: "Un email de vérification a été envoyé" }))
      showSaved()
    } catch (e) { setErrors((v) => ({ ...v, email: e instanceof Error ? e.message : "Erreur" })) }
  }

  const onSaveAddress = async () => { try { await profileApi.updateAddress(address); showSaved() } catch (e) { setErrors((v) => ({ ...v, address: e instanceof Error ? e.message : "Erreur" })) } }
  const onSaveNotifications = async () => { try { await notifApi.updateNotifications(notifications); showSaved() } catch {} }

  // Le push n'est pas une simple preference serveur : il exige une autorisation
  // navigateur et un abonnement. L'interrupteur ne bascule donc que si
  // l'abonnement a reellement ete cree (ou retire) sur cet appareil.
  const onToggleNotification = async (key: keyof NotificationPrefs, value: boolean) => {
    if (key !== "push") {
      setNotifications((p) => ({ ...p, [key]: value }))
      return
    }

    const applied = value ? await push.enable() : await push.disable()
    if (applied) setNotifications((p) => ({ ...p, push: value }))
  }

  const onSendTestPush = async () => { if (await push.sendTest()) showSaved() }
  const onChangePassword = async () => { try { await securityApi.changePassword(passwords); setPasswords({ current_password: "", new_password: "", confirm_password: "" }); showSaved() } catch (e) { setErrors((v) => ({ ...v, password: e instanceof Error ? e.message : "Erreur" })) } }
  const onDisconnectSession = async (id: number) => { await securityApi.disconnectSession(id); setSessions((prev) => prev.filter((s) => s.id !== id)) }
  const onDisconnectAll = async () => { await securityApi.disconnectAll(); logout(); router.push("/login") }
  const onDeleteAccount = async () => { await securityApi.deleteAccount("SUPPRIMER"); logout(); router.push("/app?page=deleted") }
  const onRequestLift = async () => {
    if (!token) {
      setLiftRequestMessage("Connectez-vous pour envoyer la demande.")
      return
    }

    const motif = liftMotif.trim()
    if (!motif) {
      setLiftRequestMessage("Expliquez la situation avant l'envoi.")
      return
    }

    setIsSendingLiftRequest(true)
    setLiftRequestMessage("")
    try {
      await requestBlacklistLift(token, motif)
      const status = await getBlacklistStatus(token)
      setBlacklistStatus(status)
      setLiftMotif("")
      setShowLiftModal(false)
      setLiftRequestMessage("Demande envoyée.")
    } catch (e) {
      setLiftRequestMessage(e instanceof Error ? e.message : "Impossible d'envoyer la demande.")
    } finally {
      setIsSendingLiftRequest(false)
    }
  }

  const onClickCamera = () => fileInputRef.current?.click()
  const onUploadPhoto = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0]
    if (!file) return
    if (!acceptedPhotoTypes.includes(file.type)) {
      e.target.value = ""
      return setErrors((v) => ({ ...v, photo: "Choisissez une image JPG, PNG ou WEBP." }))
    }
    if (file.size > maxPhotoSize) {
      e.target.value = ""
      return setErrors((v) => ({ ...v, photo: "L'image ne doit pas depasser 2 Mo." }))
    }

    const previousPhotoUrl = photoUrl
    const previewUrl = URL.createObjectURL(file)
    try {
      setErrors((v) => {
        const next = { ...v }
        delete next.photo
        return next
      })
      setPhotoUploading(true)
      setPhotoUrl(previewUrl)
      const response = await profileApi.uploadPhoto(file)
      setPhotoUrl(response.photo_url ?? response.avatar_url ?? previewUrl)
      // Bump photo version so ProfileAvatar / ProfileDropdown re-fetch
      const v = Number(localStorage.getItem("souki_photo_version") || "0") + 1
      localStorage.setItem("souki_photo_version", String(v))
      window.dispatchEvent(new CustomEvent("souki:photo-updated", { detail: { version: v } }))
      showSaved()
      setPhotoJustSaved(true)
      window.setTimeout(() => setPhotoJustSaved(false), 800)
    } catch (err) {
      setPhotoUrl(previousPhotoUrl)
      setErrors((v) => ({
        ...v,
        photo: err instanceof Error ? err.message : "Le téléversement de l'image a échoué. Réessayez dans un instant.",
      }))
    } finally {
      URL.revokeObjectURL(previewUrl)
      setPhotoUploading(false)
      e.target.value = ""
    }
  }

  const onActivateWallet = async () => {
    const nextErrors: Record<string, string> = {}
    if (!isWalletPasswordStrong(walletCreate.password)) {
      nextErrors.wallet_password = "Le mot de passe doit contenir 8 caractères, une majuscule, un chiffre et un caractère spécial."
    }
    if (walletCreate.password !== walletCreate.confirm_password) {
      nextErrors.wallet_confirm = "Les deux mots de passe doivent etre identiques."
    }
    if (Object.keys(nextErrors).length > 0) {
      setErrors((prev) => ({ ...prev, ...nextErrors }))
      return
    }

    try {
      const res = await walletApi.activateWallet(walletCreate)
      setErrors((prev) => {
        const next = { ...prev }
        delete next.wallet_password
        delete next.wallet_confirm
        delete next.wallet
        return next
      })
      setWalletIdFull(res.wallet_code)
      setShowWalletIdModal(true)
      const fresh = await walletApi.getWallet()
      setWalletState(fresh)
      setWalletCreate({ password: "", confirm_password: "" })
      setShowWalletActivate(false)
      setShowWalletPassword(false)
      setShowWalletConfirmPassword(false)
      showSaved()
    } catch (e) {
      setErrors((prev) => ({
        ...prev,
        wallet: e instanceof Error ? e.message : "Impossible de créer le portefeuille pour le moment.",
      }))
    }
  }

  const notifRows = useMemo(() => [
    { key: "email", label: "Notifications par email", desc: "Mises à jour et confirmations par email", icon: Mail },
    { key: "push", label: "Notifications push", desc: "Alertes instantanées sur votre appareil", icon: Smartphone },
    { key: "orderUpdates", label: "Mises à jour des commandes", desc: "Statut de livraison, confirmations", icon: Bell },
    { key: "livraison", label: "Alertes de livraison", desc: "Notifications de passage du livreur", icon: MapPin },
    { key: "promotions", label: "Promotions et offres", desc: "Remises exclusives et offres spéciales", icon: CreditCard },
    { key: "newsletter", label: "Newsletter SOUKI", desc: "Actualités et conseils hebdomadaires", icon: Globe },
  ] as const, [])
  // Message d'etat sous l'interrupteur push : l'utilisateur doit comprendre
  // pourquoi rien n'arrive (appareil non compatible, permission refusee...).
  const pushHint = useMemo((): { message: string; tone: "info" | "error" } | null => {
    if (push.error) return { message: push.error, tone: "error" }
    if (!push.supported) return { message: "Cet appareil ne prend pas en charge les notifications push. Installez SOUKI sur votre ecran d'accueil pour en profiter.", tone: "info" }
    if (push.permission === "denied") return { message: "Notifications bloquees pour SOUKI. Autorisez-les dans les reglages de votre navigateur.", tone: "error" }
    if (!push.configured) return { message: "Les notifications push ne sont pas encore activees sur SOUKI.", tone: "info" }
    if (notifications.push && !push.subscribed) return { message: "Cet appareil n'est pas encore abonne. Reactivez l'interrupteur pour l'abonner.", tone: "info" }
    return null
  }, [push.error, push.supported, push.permission, push.configured, push.subscribed, notifications.push])

  const walletPasswordState = useMemo(() => walletPasswordChecks(walletCreate.password), [walletCreate.password])
  const shouldShowLiftNotification = Boolean(
    blacklistStatus?.last_action === "LIFTED" &&
    !blacklistStatus.lift_notification_seen &&
    !hideLiftNotification
  )

  const acknowledgeLiftNotification = async () => {
    if (!token) {
      setHideLiftNotification(true)
      return
    }

    try {
      await markBlacklistLiftNotificationSeen(token)
      setBlacklistStatus((current) => current ? { ...current, lift_notification_seen: true } : current)
    } catch {
      return
    }
    setHideLiftNotification(true)
  }

  if (pageLoading || isAuthLoading) {
    return (
      <div className="min-h-screen bg-[#F5F5F0] flex items-center justify-center">
        <div className="flex items-center gap-3 text-[#1E8A3C] font-semibold">
          <Loader2 className="w-5 h-5 animate-spin" />
          Chargement des paramètres...
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-[#F5F5F0] pb-24 md:pb-0">
      <header className="sticky top-0 z-50 hidden bg-white/80 backdrop-blur-md border-b border-gray-100/50 shadow-[0_4px_30px_rgba(0,0,0,0.03)] md:block"><div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8"><div className="flex items-center justify-between h-20"><div className="flex items-center gap-4"><Link href="/" className="p-2 text-[#3D3D3D] hover:text-[#1E8A3C] hover:bg-[#F0FAF1] rounded-xl transition-colors"><ArrowLeft className="w-5 h-5" /></Link><SoukiLogoLink height={36} priority /></div><div><h1 className="text-lg font-bold text-[#3D3D3D]">Paramètres</h1><p className="text-xs text-[#8A8A8A]">Gérez votre compte et vos préférences</p></div></div></div></header>
      <div className="mx-auto max-w-6xl px-4 pt-5 md:hidden">
        <h1 className="text-2xl font-black text-[#1E8A3C]">Paramètres</h1>
        <p className="mt-1 text-sm font-medium text-[#6F8070]">Gérez votre compte et vos préférences.</p>
      </div>
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {saved && <div className="fixed top-24 right-6 z-50 flex items-center gap-2 bg-[#1E8A3C] text-white px-4 py-3 rounded-xl shadow-lg animate-in slide-in-from-right-5 duration-300"><Check className="w-4 h-4" />Modifications enregistrées !</div>}
        {errors.page && <div className="mb-6 rounded-2xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-600">{errors.page}</div>}
        {blacklistStatus && (blacklistStatus.is_blacklisted || shouldShowLiftNotification) && (
          <div className={cn("mb-6 rounded-2xl border p-4", blacklistStatus.is_blacklisted ? "border-red-200 bg-red-50" : "border-emerald-200 bg-emerald-50")}>
            <div className="flex items-start gap-3">
              <AlertTriangle className={cn("mt-0.5 h-5 w-5 shrink-0", blacklistStatus.is_blacklisted ? "text-red-600" : "text-[#1E8A3C]")} />
              <div className="min-w-0">
                <p className={cn("text-sm font-semibold", blacklistStatus.is_blacklisted ? "text-red-700" : "text-[#1E8A3C]")}>
                  {blacklistStatus.is_blacklisted ? "Votre compte ne peut plus passer de commandes COD" : "Restriction COD levee"}
                </p>
                <p className={cn("mt-1 text-xs", blacklistStatus.is_blacklisted ? "text-red-500" : "text-[#1E8A3C]")}>
                  {blacklistStatus.is_blacklisted ? "Suite a un refus de livraison. Wallet et CMI restent disponibles." : "Vous pouvez a nouveau choisir le paiement a la livraison."}
                </p>
                {blacklistStatus.last_action === "LIFT_REQUESTED" && <p className="mt-2 text-xs font-medium text-amber-600">Demande de levee en attente de decision admin.</p>}
                {blacklistStatus.last_action === "LIFT_REJECTED" && <p className="mt-2 text-xs font-medium text-red-600">Demande refusee. Motif : {blacklistStatus.last_reason}</p>}
                {shouldShowLiftNotification && <p className="mt-2 text-xs font-medium text-[#1E8A3C]">Restriction levee. COD disponible a nouveau.</p>}
                {shouldShowLiftNotification && (
                  <button
                    type="button"
                    onClick={() => void acknowledgeLiftNotification()}
                    className="mt-3 rounded-lg border border-[#1E8A3C] bg-white px-3 py-1.5 text-xs font-semibold text-[#1E8A3C] transition hover:bg-[#F0FAF1]"
                  >
                    J'ai compris
                  </button>
                )}
                {liftRequestMessage && <p className="mt-2 text-xs font-medium text-[#1E8A3C]">{liftRequestMessage}</p>}
                {blacklistStatus.last_action !== "LIFT_REQUESTED" && blacklistStatus.last_action !== "LIFTED" && <button type="button" onClick={() => { setLiftRequestMessage(""); setShowLiftModal(true) }} className="mt-3 rounded-lg border border-red-300 bg-white px-3 py-1.5 text-xs font-semibold text-red-600 transition hover:bg-red-50">Demander la levee de restriction</button>}
              </div>
            </div>
          </div>
        )}
        <div className="flex flex-col lg:flex-row gap-8">
          <aside className="lg:w-64 flex-shrink-0">
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-5 mb-4"><div className="flex items-center gap-4"><div className="relative"><div className={`relative w-14 h-14 rounded-xl bg-[#F0FAF1] overflow-hidden flex items-center justify-center font-bold text-[#1E8A3C] ${photoJustSaved ? "animate-souki-success-pop" : ""}`}>{photoUrl ? <img src={photoUrl} alt={sidebarName} className="w-full h-full object-cover" /> : initialLetter}{photoUploading && <div className="absolute inset-0 bg-black/30 flex items-center justify-center"><Loader2 className="w-5 h-5 animate-spin text-white" /></div>}</div><button onClick={onClickCamera} className="absolute -bottom-1 -right-1 w-6 h-6 bg-[#1E8A3C] rounded-full flex items-center justify-center text-white shadow-sm hover:bg-[#176B2E] transition-colors"><Camera className="w-3 h-3" /></button><input ref={fileInputRef} onChange={onUploadPhoto} type="file" accept="image/jpeg,image/png,image/webp" className="hidden" /></div><div><p className="font-bold text-[#3D3D3D]">{sidebarName}</p><p className="text-sm text-[#8A8A8A]">{personal.email}</p>{emailVerified && <span className="inline-flex items-center gap-1 mt-1 px-2 py-0.5 bg-[#F0FAF1] text-[#1E8A3C] rounded-full text-xs font-medium"><Check className="w-3 h-3" /> Vérifié</span>}{errors.photo && <p className="text-xs text-red-500">{errors.photo}</p>}</div></div></div>
            <nav className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden">{([{ id: "compte", icon: User, label: "Compte" }, { id: "notifications", icon: Bell, label: "Notifications" }, { id: "securite", icon: Shield, label: "Sécurité" }, { id: "paiement", icon: CreditCard, label: "Paiement" }] as const).map((item) => <button key={item.id} onClick={() => { setActiveSection(item.id); router.push(`/parametres/${item.id}`) }} className={cn("w-full flex items-center justify-between px-5 py-4 border-b border-gray-50 last:border-0 transition-colors", activeSection === item.id ? "bg-[#F0FAF1] text-[#1E8A3C]" : "text-[#3D3D3D] hover:bg-gray-50")}><div className="flex items-center gap-3"><item.icon className="w-4 h-4" /><span className="font-medium text-sm">{item.label}</span></div><ChevronRight className={cn("w-4 h-4 transition-transform", activeSection === item.id && "rotate-90")} /></button>)}</nav>
          </aside>
          <main className="flex-1 space-y-6">
            {activeSection === "compte" && <>
              <SectionCard title="Informations personnelles" onSave={onSavePersonal} saving={profileApi.loading}><div className="grid gap-5 md:grid-cols-2"><div><label className="block text-sm font-medium text-[#3D3D3D] mb-2">Prénom</label><input value={personal.prenom} onChange={(e) => setPersonal((p) => ({ ...p, prenom: e.target.value }))} className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors text-[#3D3D3D]" /></div><div><label className="block text-sm font-medium text-[#3D3D3D] mb-2">Nom</label><input value={personal.nom} onChange={(e) => setPersonal((p) => ({ ...p, nom: e.target.value }))} className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors text-[#3D3D3D]" /></div><div><label className="block text-sm font-medium text-[#3D3D3D] mb-2">Email</label><div className="relative"><Mail className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#8A8A8A]" /><input value={personal.email} onChange={(e) => setPersonal((p) => ({ ...p, email: e.target.value }))} type="email" className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors text-[#3D3D3D]" /></div>{errors.email && <p className="text-xs text-red-500 mt-1">{errors.email}</p>}{errors.email_info && <p className="text-xs text-[#1E8A3C] mt-1">{errors.email_info}</p>}</div><div><label className="block text-sm font-medium text-[#3D3D3D] mb-2">Téléphone</label><div className="relative"><Phone className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#8A8A8A]" /><input value={personal.telephone} onChange={(e) => setPersonal((p) => ({ ...p, telephone: e.target.value }))} type="tel" className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors text-[#3D3D3D]" /></div>{errors.telephone && <p className="text-xs text-red-500 mt-1">{errors.telephone}</p>}</div></div></SectionCard>
              <SectionCard title="Adresse de livraison" onSave={onSaveAddress} saving={profileApi.loading}><div className="grid gap-5"><div><label className="block text-sm font-medium text-[#3D3D3D] mb-2">Adresse</label><div className="relative"><MapPin className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#8A8A8A]" /><input value={address.adresse} onChange={(e) => setAddress((p) => ({ ...p, adresse: e.target.value }))} className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors text-[#3D3D3D]" /></div></div><div className="grid grid-cols-2 gap-4"><div><label className="block text-sm font-medium text-[#3D3D3D] mb-2">Ville</label><select value={address.ville} onChange={(e) => setAddress((p) => ({ ...p, ville: e.target.value }))} className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors text-[#3D3D3D] appearance-none bg-white">{moroccanCities.map((city) => <option key={city} value={city}>{city}</option>)}</select></div><div><label className="block text-sm font-medium text-[#3D3D3D] mb-2">Code postal</label><input value={address.code_postal} onChange={(e) => setAddress((p) => ({ ...p, code_postal: e.target.value }))} className="w-full px-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors text-[#3D3D3D]" /></div></div>{errors.address && <p className="text-xs text-red-500 mt-1">{errors.address}</p>}</div></SectionCard>
              <SectionCard title="Préférences d'affichage" onSave={showSaved}><div className="space-y-1"><div className="flex items-center justify-between py-4"><div className="flex items-center gap-3"><div className="w-9 h-9 rounded-xl bg-gray-100 flex items-center justify-center"><Globe className="w-4 h-4 text-[#3D3D3D]" /></div><div><p className="font-medium text-[#3D3D3D] text-sm">Langue</p><p className="text-xs text-[#8A8A8A]">Non fonctionnel pour le moment</p></div></div><select className="px-3 py-2 border border-gray-200 rounded-lg text-sm text-[#3D3D3D] focus:outline-none focus:border-[#4CB84A] bg-white"><option value="fr">Français</option><option value="ar">Arabe</option><option value="en">English</option></select></div></div></SectionCard>
              {referralCode && (
                <div className="rounded-[28px] border border-[#1E8A3C]/10 bg-[radial-gradient(circle_at_top_right,_rgba(255,255,255,0.3),_transparent_38%),linear-gradient(135deg,#165f2e_0%,#1E8A3C_52%,#79d65e_100%)] p-6 text-white shadow-[0_18px_60px_rgba(30,138,60,0.22)]">
                  <div className="flex items-center gap-3">
                    <div className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/18 backdrop-blur-sm">
                      <Gift className="h-6 w-6 text-white" />
                    </div>
                    <div>
                      <p className="text-xs font-semibold uppercase tracking-[0.24em] text-white/70">Parrainage</p>
                      <h3 className="text-xl font-bold tracking-tight">Invite tes proches, gagnez chacun un cadeau</h3>
                    </div>
                  </div>
                  <p className="mt-4 max-w-xl text-sm leading-6 text-white/80">
                    Partage ton code avec tes colocataires ou voisins. À leur 1ère commande livrée, vous recevez chacun un crédit sur votre portefeuille Souki.
                  </p>
                  <div className="mt-5 flex flex-col gap-3 sm:flex-row sm:items-stretch">
                    <div className="flex items-center justify-between gap-3 rounded-2xl border border-white/20 bg-white/10 px-4 py-3 backdrop-blur-sm sm:flex-1">
                      <div>
                        <p className="text-xs uppercase tracking-[0.24em] text-white/65">Ton code</p>
                        <p className="mt-1 font-mono text-2xl font-bold tracking-[0.3em] text-white">{referralCode}</p>
                      </div>
                      <button
                        onClick={copyReferralCode}
                        className="inline-flex items-center gap-2 rounded-xl bg-white/18 px-3 py-2 text-sm font-semibold text-white transition hover:bg-white/28"
                      >
                        {copiedReferral ? <Check className="h-4 w-4" /> : <Copy className="h-4 w-4" />}
                        {copiedReferral ? "Copié" : "Copier"}
                      </button>
                    </div>
                    <button
                      onClick={shareReferral}
                      className="inline-flex items-center justify-center gap-2 rounded-2xl bg-white px-5 py-3 text-sm font-semibold text-[#1E8A3C] shadow-sm transition hover:bg-white/90"
                    >
                      <Share2 className="h-4 w-4" />
                      Partager
                    </button>
                  </div>
                </div>
              )}
            </>}
            {activeSection === "notifications" && (
              <SectionCard title="Notifications" onSave={onSaveNotifications} saving={notifApi.loading}>
                <div className="space-y-1">
                  {notifRows.map((row) => (
                    <div key={row.key} className="py-4 border-b border-gray-50 last:border-0">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-3">
                          <div className="w-9 h-9 rounded-xl bg-[#F0FAF1] flex items-center justify-center"><row.icon className="w-4 h-4 text-[#1E8A3C]" /></div>
                          <div><p className="font-medium text-[#3D3D3D] text-sm">{row.label}</p><p className="text-xs text-[#8A8A8A]">{row.desc}</p></div>
                        </div>
                        <Toggle
                          checked={notifications[row.key]}
                          disabled={row.key === "push" && (push.busy || !push.supported)}
                          onCheckedChange={(v) => void onToggleNotification(row.key, v)}
                        />
                      </div>
                      {row.key === "push" && pushHint && (
                        <p className={`mt-2 pl-12 text-xs ${pushHint.tone === "error" ? "text-[#C2410C]" : "text-[#6F8070]"}`}>{pushHint.message}</p>
                      )}
                      {row.key === "push" && push.subscribed && notifications.push && (
                        <button
                          type="button"
                          onClick={() => void onSendTestPush()}
                          disabled={push.busy}
                          className="mt-2 ml-12 text-xs font-semibold text-[#1E8A3C] underline underline-offset-2 disabled:opacity-50"
                        >
                          Envoyer une notification de test
                        </button>
                      )}
                    </div>
                  ))}
                </div>
              </SectionCard>
            )}
            {activeSection === "securite" && <>
              <SectionCard title="Changer le mot de passe" onSave={onChangePassword} saving={securityApi.loading}><div className="space-y-4 max-w-md"><div><label className="block text-sm font-medium text-[#3D3D3D] mb-2">Mot de passe actuel</label><div className="relative"><Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#8A8A8A]" /><input type={showPassword ? "text" : "password"} value={passwords.current_password} onChange={(e) => setPasswords((p) => ({ ...p, current_password: e.target.value }))} className="w-full pl-10 pr-12 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors" /><button type="button" onClick={() => setShowPassword((v) => !v)} className="absolute right-3 top-1/2 -translate-y-1/2 text-[#8A8A8A] hover:text-[#3D3D3D]">{showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}</button></div></div><div><label className="block text-sm font-medium text-[#3D3D3D] mb-2">Nouveau mot de passe</label><div className="relative"><Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#8A8A8A]" /><input type="password" value={passwords.new_password} onChange={(e) => setPasswords((p) => ({ ...p, new_password: e.target.value }))} className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors" /></div></div><div><label className="block text-sm font-medium text-[#3D3D3D] mb-2">Confirmer le nouveau mot de passe</label><div className="relative"><Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-[#8A8A8A]" /><input type="password" value={passwords.confirm_password} onChange={(e) => setPasswords((p) => ({ ...p, confirm_password: e.target.value }))} className="w-full pl-10 pr-4 py-3 border-2 border-gray-200 rounded-xl focus:border-[#4CB84A] focus:outline-none transition-colors" /></div>{errors.password && <p className="text-xs text-red-500 mt-1">{errors.password}</p>}</div></div></SectionCard>
              <SectionCard title="Sessions actives"><div className="space-y-3">{sessions.map((s) => <div key={s.id} className={cn("flex items-center justify-between p-4 rounded-xl border", s.is_current ? "bg-[#F0FAF1] border-[#4CB84A]/20" : "border-gray-100")}><div className="flex items-center gap-3"><div className={cn("w-9 h-9 rounded-xl flex items-center justify-center", s.is_current ? "bg-[#1E8A3C]" : "bg-gray-100")}><Smartphone className={cn("w-4 h-4", s.is_current ? "text-white" : "text-[#8A8A8A]")} /></div><div><p className="font-medium text-[#3D3D3D] text-sm">{s.device_name || s.browser || "Session"}</p><p className="text-xs text-[#8A8A8A]">{s.location || "Maroc"} - {s.last_active ? "Actif récemment" : "Inconnu"}</p></div></div>{s.is_current ? <span className="text-xs bg-[#1E8A3C] text-white px-2 py-1 rounded-full font-medium">Cet appareil</span> : <button onClick={() => onDisconnectSession(s.id)} className="text-sm text-red-500 hover:text-red-700 font-medium transition-colors">Déconnecter</button>}</div>)}</div></SectionCard>
