                  <p className="text-xs text-[#6C7E6E]">Suggestion ML selon vos criteres</p>
                </div>
              </div>
              <button
                onClick={closeModal}
                className="rounded-full p-2 text-gray-400 transition-colors hover:bg-gray-100 hover:text-gray-700"
