                    placeholder="Ex: 150"
                  />
                  <span className="absolute right-4 top-1/2 -translate-y-1/2 text-sm font-medium text-[#6C7E6E]">
                    DH
                  </span>
                </div>
                {isDishSelected && (
                  <p className="mt-1 text-[11px] text-[#9AA79B]">
                    Non applicable pour un plat — quantites selon le nombre de personnes
                  </p>
