                      </div>
                    )
                    : "IA-SOUKI compose votre panier avec l'IA Groq selon vos criteres et votre choix."}
              </div>

              {error && (
                <div className="rounded-2xl border border-red-200 bg-red-50 p-4 text-sm text-red-600">
