              {smartPreview.length > 0 && (
                <div className="rounded-3xl border border-[#F3E2CE] bg-[#FFFBF7] p-4 animate-slide-in-up">
                  <div className="mb-3 flex items-center gap-2 text-[#C96A00]">
                    <Check className="h-4 w-4" />
