              )}
            </div>

            <div className="mt-auto border-t border-gray-100 p-6">
              <div className="grid gap-3 sm:grid-cols-2">
                <button
                  onClick={handleSmartGeneration}
                  disabled={isGeneratingSmart || isOrderLocked}
                  className="flex items-center justify-center gap-2 rounded-2xl border border-[#F5D4AE] bg-[#FFF5EB] px-4 py-3 font-semibold text-[#C96A00] transition-colors hover:bg-[#FFE8CC] disabled:cursor-not-allowed disabled:opacity-70"
                >
                  {isGeneratingSmart ? (
                    <Loader2 className="h-4 w-4 animate-spin" />
                  ) : (
                    <Zap className="h-4 w-4" />
                  )}
                  {isGeneratingSmart ? "Generation..." : "Generer"}
                </button>
                <button
                  onClick={handleApplySmartBasket}
                  disabled={smartSelections.length === 0 || isOrderLocked || isGeneratingSmart}
                  className={cn(
                    "flex items-center justify-center gap-2 rounded-2xl px-4 py-3 font-semibold text-white transition-colors",
                    smartSelections.length === 0 || isOrderLocked || isGeneratingSmart
                      ? "cursor-not-allowed bg-gray-300"
                      : "bg-[#F07C00] hover:bg-[#D66B00]"
                  )}
                >
                  {isOrderLocked ? "Commandes fermees" : "Aller au checkout"}
                  <ArrowRight className="h-4 w-4" />
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

"use client"

import type { CSSProperties, ReactNode } from "react"
import type { LucideIcon } from "lucide-react"

import { cn } from "@/lib/utils"

interface SoukiEmptyStateProps {
  /** Icone lucide de secours tant qu'aucune illustration n'est fournie. */
  icon?: LucideIcon
  /** Illustration de marque (mascotte Recolte) — chargee en lazy, jamais bloquante. */
  illustrationSrc?: string
  illustrationAlt?: string
  title: string
  description?: string
  action?: ReactNode
  className?: string
}

/**
 * Etat vide SOUKI : meme carte blanche arrondie que les etats vides existants,
 * avec une entree douce et un emplacement pour l'illustration de la mascotte.
 * L'illustration est decorative : le texte porte toujours l'information.
 */
export function SoukiEmptyState({
  icon: Icon,
  illustrationSrc,
  illustrationAlt = "",
  title,
  description,
  action,
  className,
}: SoukiEmptyStateProps) {
  return (
    <div
      className={cn(
        "rounded-[24px] border border-[#E6EFE7] bg-white p-8 text-center animate-fade-in-up",
        className
      )}
    >
      {illustrationSrc ? (
        <img
          src={illustrationSrc}
          alt={illustrationAlt}
          loading="lazy"
          decoding="async"
          width={160}
          height={160}
          className="mx-auto mb-4 h-40 w-40 object-contain animate-gentle-float"
          aria-hidden={illustrationAlt === ""}
        />
      ) : (
        Icon && <Icon className="mx-auto mb-3 h-10 w-10 text-[#B8C9BA]" />
      )}
      <p className="font-semibold text-[#264129]">{title}</p>
      {description && (
        <p
          className="mx-auto mt-2 max-w-xs text-sm text-[#8A8A8A] animate-fade-in-up-delay-1"
