import {
  Crown,
  Home,
  Leaf,
  Menu,
  PackageCheck,
  Settings,
  ShoppingCart,
  User,
  Wallet,
  X,
} from "lucide-react"

import { useAuth } from "@/hooks/useAuth"
import { isPwaStandalone } from "@/lib/pwa"
