}

/**
 * Navigation mobile :
 * - PWA installee (standalone) : barre d'onglets en bas d'ecran (look natif).
 * - Version web : navbar haute fixe (logo SOUKI a gauche, profil + burger a
 *   droite) ; le burger regroupe tous les liens de l'ancienne barre basse.
 *   Aucune barre en bas de page sur le web.
 */
export function MobileBottomNav({ cartCount = 0, onCartClick, onMenuClick }: MobileBottomNavProps) {
  const [drawerOpen, setDrawerOpen] = useState(false)
  const pathname = usePathname()
  const router = useRouter()
  const { user } = useAuth()


  // Accueil : /pwa-welcome en standalone (navigation directe, sans passer par
  // la redirection React de "/" qui fait flasher l'accueil web), "/" sur le web.
  // Resolu apres montage : le SSR rend "/" et le display-mode ne change pas
  // en cours de session.
  const [homeHref, setHomeHref] = useState("/")
  // null tant que le display-mode n'est pas resolu cote client : on ne rend
  // rien pour eviter le flash barre basse <-> navbar haute.
  const [isStandalone, setIsStandalone] = useState<boolean | null>(null)

  useEffect(() => {
    const standalone = isPwaStandalone()
    setIsStandalone(standalone)
    if (standalone) setHomeHref("/pwa-welcome")
  }, [])

  // Version web : pousse le contenu sous la navbar haute fixe et decale les
  // en-tetes sticky des pages (regles dans globals.css).
  useEffect(() => {
    if (isStandalone !== false) return
    document.body.classList.add("souki-web-topnav")
    return () => document.body.classList.remove("souki-web-topnav")
  }, [isStandalone])

  const linkItems = [
    { label: "Accueil", href: homeHref, icon: Home },
    { label: "Produits", href: "/catalogue", icon: Leaf },
  ]

  const secondaryItems = [
    { label: "Historique", href: "/historique", icon: PackageCheck },
    { label: "Abonnements", href: "/abonnements", icon: Crown },
    { label: "Mon Wallet", href: "/wallet", icon: Wallet },
    { label: "Mon profil", href: "/parametres/compte", icon: User },
    { label: "Paramètres", href: "/parametres/notifications", icon: Settings },
  ]

  const gridCols = "grid-cols-4"

  // Actif si la route correspond exactement ("/") ou en prefixe (sous-routes,
  // query string). Sans cela, "/catalogue?..." n'allumait jamais l'onglet.
  const isActiveLink = (href: string) =>
    href === "/" ? pathname === "/" : pathname === href || pathname.startsWith(`${href}/`)

  const openDrawer = () => {
    if (onMenuClick) {
      onMenuClick()
      return
    }
    setDrawerOpen(true)
  }

  const handleCartClick = onCartClick ?? (() => {
    if (typeof window !== "undefined") {
      sessionStorage.setItem("souki_open_cart", "true")
    }
    router.push("/catalogue")
  })

  if (isStandalone === null) return null

  if (!isStandalone) {
    return (
      <>
        <nav
          className="fixed inset-x-0 top-0 z-40 border-b border-[#DDEBDD] bg-white/95 backdrop-blur-md shadow-[0_4px_24px_rgba(0,0,0,0.04)] md:hidden"
          aria-label="Navigation principale"
        >
          <div className="flex h-14 items-center justify-between px-4">
            <SoukiLogoLink href={homeHref} height={36} priority />

            <div className="flex items-center gap-2">
              <Link
                href={user ? "/parametres/compte" : "/login"}
                aria-label={user ? "Mon profil" : "Se connecter"}
                className="flex h-10 w-10 items-center justify-center rounded-full bg-gradient-to-br from-[#1E8A3C] to-[#4CB84A] text-white shadow-sm ring-2 ring-white transition-transform active:scale-90"
              >
                <User className="h-5 w-5" />
              </Link>
              <button
                type="button"
                onClick={openDrawer}
                aria-label="Ouvrir le menu"
                className="relative flex h-10 w-10 items-center justify-center rounded-xl border border-[#DDEBDD] bg-white text-[#264129] transition-transform active:scale-90"
              >
                <Menu className="h-5 w-5" />
                {cartCount > 0 && (
                  <span
                    key={cartCount}
                    className="absolute -right-1.5 -top-1.5 flex h-5 min-w-5 items-center justify-center rounded-full bg-[#F07C00] px-1 text-[10px] font-black text-white animate-badge-pop"
                  >
                    {cartCount}
                  </span>
                )}
              </button>
            </div>
          </div>
        </nav>

        {drawerOpen && (
          <div className="fixed inset-0 z-[70] bg-[#122018]/45 backdrop-blur-sm md:hidden" onClick={() => setDrawerOpen(false)}>
            <div
              className="absolute inset-x-0 top-0 max-h-[85dvh] overflow-y-auto rounded-b-[28px] bg-white/95 p-4 pt-[max(env(safe-area-inset-top),1rem)] shadow-[0_8px_32px_rgba(0,0,0,0.1)] backdrop-blur-md"
              onClick={(event) => event.stopPropagation()}
            >
              <div className="mb-4 flex items-center justify-between">
                <div>
                  <p className="text-sm font-black text-[#264129]">SOUKI</p>
                  <p className="text-xs font-semibold text-[#7B8B7D]">Menu de navigation</p>
                </div>
                <button
                  type="button"
                  onClick={() => setDrawerOpen(false)}
                  className="flex h-11 w-11 items-center justify-center rounded-2xl border border-[#DDEBDD] text-[#607061]"
                  aria-label="Fermer le menu"
                >
                  <X className="h-5 w-5" />
                </button>
              </div>

              <div className="space-y-2">
                {linkItems.map((item) => {
                  const Icon = item.icon
                  const isActive = isActiveLink(item.href)
                  return (
                    <Link
                      key={item.href}
                      href={item.href}
                      onClick={() => setDrawerOpen(false)}
                      className={cn(
                        "flex min-h-14 items-center gap-3 rounded-2xl border px-4 text-sm font-bold",
                        isActive
                          ? "border-[#CDE8D0] bg-[#EAF8EC] text-[#1E8A3C]"
                          : "border-[#EEF2EE] bg-[#FBFDF9] text-[#264129]",
                      )}
                    >
                      <Icon className="h-5 w-5 text-[#1E8A3C]" />
                      {item.label}
                    </Link>
                  )
                })}

                <button
                  type="button"
                  onClick={() => {
                    setDrawerOpen(false)
                    handleCartClick()
                  }}
                  className="flex min-h-14 w-full items-center gap-3 rounded-2xl border border-[#EEF2EE] bg-[#FBFDF9] px-4 text-sm font-bold text-[#264129]"
                >
                  <ShoppingCart className="h-5 w-5 text-[#1E8A3C]" />
                  Panier
                  {cartCount > 0 && (
                    <span className="ml-auto flex h-5 min-w-5 items-center justify-center rounded-full bg-[#F07C00] px-1.5 text-[10px] font-black text-white">
                      {cartCount}
                    </span>
                  )}
                </button>

                {secondaryItems.map((item) => {
                  const Icon = item.icon
                  return (
                    <Link
                      key={item.label}
                      href={item.href}
                      onClick={() => setDrawerOpen(false)}
                      className="flex min-h-14 items-center gap-3 rounded-2xl border border-[#EEF2EE] bg-[#FBFDF9] px-4 text-sm font-bold text-[#264129]"
                    >
                      <Icon className="h-5 w-5 text-[#1E8A3C]" />
                      {item.label}
                    </Link>
                  )
                })}
              </div>
            </div>
          </div>
        )}
      </>
    )
  }

  return (
    <>
      <nav
        className="fixed inset-x-0 bottom-0 z-30 bg-white/95 backdrop-blur-md border-t border-[#DDEBDD] px-3 pb-[max(env(safe-area-inset-bottom),0.75rem)] pt-2 md:hidden shadow-[0_-4px_24px_rgba(0,0,0,0.04)]"
        aria-label="Navigation mobile principale"
      >
        <div className={cn("mx-auto grid max-w-md gap-1", gridCols)}>
          {linkItems.map((item) => {
            const Icon = item.icon
            const isActive = isActiveLink(item.href)
            return (
              <Link
                key={item.href}
                href={item.href}
                className={cn(
                  "flex min-h-14 flex-col items-center justify-center gap-1 rounded-2xl px-2 text-[11px] font-bold transition-colors",
                  isActive ? "bg-[#EAF8EC] text-[#1E8A3C]" : "text-[#607061] hover:bg-[#F7FCF7]"
                )}
              >
                <Icon className="h-5 w-5" />
                <span>{item.label}</span>
              </Link>
            )
          })}

          <button
            type="button"
            onClick={handleCartClick}
            className={cn(
              "relative flex min-h-14 flex-col items-center justify-center gap-1 rounded-2xl px-2 text-[11px] font-bold transition-colors",
              pathname === "/checkout" ? "bg-[#FFF7EE] text-[#F07C00]" : "text-[#607061] hover:bg-[#F7FCF7]"
            )}
          >
            <ShoppingCart className="h-5 w-5" />
            <span>Panier</span>
            {cartCount > 0 && (
              // key={cartCount} : rejoue le pop a chaque changement de quantite
              <span
                key={cartCount}
                className="absolute right-4 top-1 flex h-5 min-w-5 items-center justify-center rounded-full bg-[#F07C00] px-1 text-[10px] font-black text-white animate-badge-pop"
              >
                {cartCount}
              </span>
            )}
          </button>

          <button
            type="button"
            onClick={openDrawer}
            className="flex min-h-14 flex-col items-center justify-center gap-1 rounded-2xl px-2 text-[11px] font-bold text-[#607061] transition-colors hover:bg-[#F7FCF7]"
          >
            <Menu className="h-5 w-5" />
            <span>Plus</span>
          </button>
        </div>
      </nav>

      {drawerOpen && (
        <div className="fixed inset-0 z-[70] bg-[#122018]/45 backdrop-blur-sm md:hidden">
          <div className="absolute bottom-0 left-0 right-0 rounded-t-[28px] bg-white/95 backdrop-blur-md p-4 pb-[max(env(safe-area-inset-bottom),1rem)] shadow-[0_-8px_32px_rgba(0,0,0,0.1)]">
            <div className="mb-4 flex items-center justify-between">
              <div>
                <p className="text-sm font-black text-[#264129]">SOUKI</p>
                <p className="text-xs font-semibold text-[#7B8B7D]">Options secondaires</p>
              </div>
              <button
                type="button"
                onClick={() => setDrawerOpen(false)}
                className="flex h-11 w-11 items-center justify-center rounded-2xl border border-[#DDEBDD] text-[#607061]"
                aria-label="Fermer le menu"
              >
                <X className="h-5 w-5" />
              </button>
            </div>

            <div className="space-y-2">
              {secondaryItems.map((item) => {
                const Icon = item.icon
                return (
                  <Link
                    key={item.label}
                    href={item.href}
                    onClick={() => setDrawerOpen(false)}
                    className="flex min-h-14 items-center gap-3 rounded-2xl border border-[#EEF2EE] bg-[#FBFDF9] px-4 text-sm font-bold text-[#264129]"
                  >
                    <Icon className="h-5 w-5 text-[#1E8A3C]" />
                    {item.label}
                  </Link>
                )
              })}
            </div>
          </div>
        </div>
      )}
    </>
  )
}

"use client"

import { useEffect, useState } from "react"
import { Check, Heart, Minus, Plus, ShoppingCart } from "lucide-react"

import { formatQuantity, isIllustrationImage } from "@/lib/catalogue"
import { cn } from "@/lib/utils"

interface ProductCardProps {
  id: number | string
  name: string
  image: string
  fallbackImage?: string
  price: number
  prixKhddarEstime?: number | null
  niveau?: 1 | 2 | 3
  unit: string
  displayUnit?: string
  quantityStep?: number
  stock?: number
  disabled?: boolean
  disabledLabel?: string
  featured?: boolean
  /**
   * Affiche le visuel avec les proportions compactes d'origine (bandeau court)
   * au lieu du carre plein. Utilise sur l'accueil pour retrouver l'ancien rendu
   * des cartes produits tout en gardant les nouvelles images.
   */
  compactImage?: boolean
  /**
   * "minimal" : rendu aere aligne sur les cartes de l'accueil PWA — visuel carre,
   * nom, prix, et un « + » flottant qui remplace le stepper et le bouton pleine
   * largeur (c'est leur empilement qui rendait la grille catalogue si dense).
   * Mobile uniquement : toutes les classes md: restaurent le rendu web d'origine.
   */
  variant?: "default" | "minimal"
  /**
   * Favori (coeur). Affiche uniquement en overlay sur mobile/PWA (`md:hidden`) :
   * le catalogue desktop reste pixel-identique. Fourni par le parent (useFavorites).
   */
  isFavorite?: boolean
  onToggleFavorite?: (id: number | string) => void
  onView?: (id: number | string) => void
  onAddToCart?: (id: number | string, quantity: number) => void
}

export function ProductCard({
  id,
  name,
  image,
  fallbackImage,
  price,
  prixKhddarEstime,
  niveau,
  unit,
  displayUnit,
  quantityStep = unit === "kg" ? 0.5 : 1,
  stock,
  disabled = false,
  disabledLabel = "Indisponible",
  featured = false,
  compactImage = false,
  variant = "default",
  isFavorite = false,
  onToggleFavorite,
  onView,
  onAddToCart,
}: ProductCardProps) {
  const isMinimal = variant === "minimal"
  const [quantity, setQuantity] = useState(quantityStep)
  const [isAdded, setIsAdded] = useState(false)
  const [resolvedImage, setResolvedImage] = useState(image)
  const resolvedDisplayUnit = displayUnit || unit

  useEffect(() => {
    setResolvedImage(image)
  }, [image])

  const isOutOfStock = false // Précommande : la disponibilité est gérée par le catalogue actif.
  const isUnavailable = isOutOfStock || disabled
  // Illustration locale (fond blanc) : rendu poli `contain`+`multiply` UNIQUEMENT
  // sur mobile/PWA (< md). Le desktop web (md:) est reinitialise a l'identique
  // (object-cover, sans padding ni blend) pour rester pixel-identique.
  const isIllustration = isIllustrationImage(resolvedImage)

  // Remise vs prix "khddar" estimé (marché de gros) : badge -X% + prix barré,
  // façon référence e-commerce. Affiché seulement si le prix khddar est plus élevé.
  const oldPrice =
    typeof prixKhddarEstime === "number" && prixKhddarEstime > price ? prixKhddarEstime : null
  const discountPct = oldPrice ? Math.round((1 - price / oldPrice) * 100) : 0

  const getUnitHint = () => {
    if (resolvedDisplayUnit === "250g") {
      return "Prix affiche par portion de 250g"
    }
    if (resolvedDisplayUnit === "lot") {
      return "Vente par lot"
    }
    if (unit === "kg") {
      return "Vente au kg"
    }
    return `Vente a l'unite ${resolvedDisplayUnit}`
  }

  const handleAdd = () => {
    if (isUnavailable) {
      return
    }
    onAddToCart?.(id, quantity)
    setIsAdded(true)
    // En minimal, l'unique retour visuel est la coche du « + » : on la laisse
    // assez longtemps pour etre vue.
    setTimeout(() => setIsAdded(false), isMinimal ? 900 : 300)
  }

  const increment = () => {
    setQuantity((currentQuantity) => currentQuantity + quantityStep)
  }

  const decrement = () => {
    setQuantity((currentQuantity) => Math.max(quantityStep, currentQuantity - quantityStep))
  }

  return (
    <article
      onClick={() => onView?.(id)}
      className={cn(
        "group flex h-full flex-col bg-white transition-all duration-300",
        // md: identique a l'origine dans les deux variantes.
        isMinimal
          ? "rounded-3xl border border-gray-100 p-2 shadow-sm shadow-gray-200/50 md:overflow-hidden md:rounded-2xl md:border-[#DDEFE0] md:p-0 md:shadow-[0_18px_45px_-22px_rgba(30,138,60,0.25)]"
          : "overflow-hidden rounded-2xl border border-[#DDEFE0] shadow-[0_18px_45px_-22px_rgba(30,138,60,0.25)]",
        isUnavailable
          ? "opacity-65 grayscale-[0.55]"
          : "hover:-translate-y-1 hover:shadow-[0_22px_55px_-20px_rgba(30,138,60,0.28)]"
      )}
    >
      <div
        className={cn(
          "relative w-full overflow-hidden",
          // Illustration sur mobile : fond degrade doux. md: revient au fond plat
          // d'origine (pixel-identique web).
          isIllustration
            ? "bg-gradient-to-b from-[#EFF7F0] to-[#F7FBF7] md:bg-none md:bg-[#F4FAF3]"
            : "bg-[#F4FAF3]",
          // Accueil : proportions compactes d'origine. Sinon : visuel carre
          // (look e-commerce moderne) conserve pour le catalogue.
          // Mobile : cadre plus court (aspect-[4/3]) pour des cartes moins hautes ;
          // md: revient au carre plein → catalogue web pixel-identique.
          isMinimal
            ? "aspect-square rounded-2xl md:rounded-none"
            : compactImage
              ? (featured ? "h-40 sm:h-52 md:h-56 2xl:h-64" : "h-28 sm:h-44 2xl:h-48")
              : (featured ? "aspect-square sm:aspect-[4/3]" : "aspect-[4/3] md:aspect-square")
        )}
      >
        <img
          src={resolvedImage}
          alt={name}
          onError={() => {
            if (fallbackImage && resolvedImage !== fallbackImage) {
              setResolvedImage(fallbackImage)
            }
          }}
          className={cn(
            "h-full w-full transition-transform duration-500 group-hover:scale-105",
            // Mobile : contain + multiply (cadre blanc efface). md: object-cover
            // sans padding ni blend → rendu web d'origine inchange.
            isIllustration
              ? "object-contain p-2 mix-blend-multiply md:object-cover md:p-0 md:mix-blend-normal"
              : "object-cover",
          )}
        />
        {isOutOfStock ? (
          <>
            <span
              className={cn(
                "absolute top-3 rounded-full bg-red-500 px-3 py-1 text-xs font-semibold text-white shadow-sm",
                // En minimal, le coeur favoris occupe le coin haut-gauche : les tags
                // passent a droite pour rester visibles. md: rendu web d'origine.
                isMinimal ? "right-3 md:left-3 md:right-auto" : "left-3",
              )}
            >
              Rupture
            </span>
            <div className="absolute inset-0 bg-white/35" />
          </>
        ) : (
          discountPct > 0 && (
            <span
              className={cn(
                "absolute top-2.5 rounded-full bg-[#F07C00] px-2.5 py-1 text-[11px] font-black text-white shadow-[0_6px_16px_-6px_rgba(240,124,0,0.8)]",
                isMinimal ? "right-2.5 md:left-2.5 md:right-auto" : "left-2.5",
              )}
            >
              -{discountPct}%
            </span>
          )
        )}
        {onToggleFavorite && (
          <button
            type="button"
            aria-label={isFavorite ? "Retirer des favoris" : "Ajouter aux favoris"}
            aria-pressed={isFavorite}
            onClick={(event) => {
              event.stopPropagation()
              onToggleFavorite(id)
            }}
            className={cn(
              "absolute top-2 flex h-8 w-8 items-center justify-center rounded-full bg-white/90 shadow-md backdrop-blur transition-transform active:scale-90 md:hidden",
              // En minimal, le « + » occupe le coin bas-droit : le coeur passe a
              // gauche, comme sur les cartes de l'accueil.
              isMinimal ? "left-2" : "right-2",
            )}
          >
            <Heart
              className={cn(
                "h-4 w-4 transition-colors",
                isFavorite ? "fill-[#E4405F] text-[#E4405F]" : "text-[#7C8B7D]",
              )}
            />
          </button>
        )}

        {/* Ajout rapide en minimal : remplace le stepper + le bouton pleine largeur,
            dont l'empilement rendait la grille catalogue tres dense sur mobile. */}
        {isMinimal && (
          <button
            type="button"
            aria-label={`Ajouter ${name}`}
            disabled={isUnavailable}
            onClick={(event) => {
              event.stopPropagation()
              handleAdd()
            }}
            className={cn(
              "absolute bottom-2 right-2 flex h-9 w-9 items-center justify-center rounded-full shadow-md transition-all active:scale-90 md:hidden",
              isUnavailable
                ? "cursor-not-allowed bg-gray-200 text-gray-400"
                : "bg-white text-[#1E8A3C]",
              isAdded && "scale-110 bg-[#1E8A3C] text-white",
            )}
          >
            {isAdded ? <Check className="h-4 w-4" /> : <Plus className="h-4 w-4" />}
          </button>
        )}
      </div>

      <div
        className={cn(
          "flex flex-1 flex-col",
          isMinimal ? "mt-2.5 px-1 pb-1 md:mt-0 md:p-3 2xl:p-4" : "p-2 sm:p-3 2xl:p-4",
        )}
      >
        <div className={cn("min-w-0", isMinimal ? "mb-1 md:mb-2" : "mb-1.5 sm:mb-2")}>
          <h3 className="truncate text-sm font-bold text-[#264129] sm:text-base">{name}</h3>
          <p
            className={cn(
              "mt-0.5 truncate text-[11px] leading-4 text-[#6C7E6E] sm:text-xs",
              // L'unite tient deja dans la ligne de prix : on la masque en minimal
              // pour garder une carte a deux lignes, comme sur l'accueil.
              isMinimal && "hidden md:block",
            )}
          >
            {getUnitHint()}
          </p>
        </div>

        <div className="mb-2 flex flex-wrap items-baseline gap-x-1.5 gap-y-0.5 sm:mb-2.5">
          <span className="text-base font-black leading-none text-[#F07C00] sm:text-lg 2xl:text-xl">
            {price.toFixed(2)} DH
          </span>
          <span className="shrink-0 whitespace-nowrap text-[11px] text-[#6C7E6E]">
            / {resolvedDisplayUnit}
          </span>
          {oldPrice && (
            <span className="shrink-0 text-[11px] font-semibold text-[#9AA49B] line-through">
              {oldPrice.toFixed(2)} DH
            </span>
          )}
        </div>

        {/* Stepper + bouton pleine largeur : masques en minimal sur mobile, ou le
            « + » flottant les remplace. Intacts a partir de md:. */}
        <div className={cn("mb-2 space-y-2 sm:mb-2.5", isMinimal && "hidden md:block")}>
          <div className="flex w-full items-center overflow-hidden rounded-full border border-[#CDE8D0] bg-[#F7FCF7]">
          <button
              onClick={(event) => {
                event.stopPropagation()
                decrement()
              }}
              className="flex h-7 w-7 shrink-0 items-center justify-center text-[#2E5A33] transition-colors hover:bg-[#E7F5E8] sm:h-10 sm:w-10 2xl:h-11 2xl:w-11"
              disabled={isUnavailable}
            >
              <Minus className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
            </button>
            <span className="min-w-0 flex-1 px-1 text-center text-xs font-semibold text-[#264129] sm:px-2 sm:text-sm">
              {formatQuantity(quantity, unit)}
            </span>
          <button
              onClick={(event) => {
                event.stopPropagation()
                increment()
              }}
              className="flex h-7 w-7 shrink-0 items-center justify-center text-[#2E5A33] transition-colors hover:bg-[#E7F5E8] sm:h-10 sm:w-10 2xl:h-11 2xl:w-11"
              disabled={isUnavailable}
            >
              <Plus className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
            </button>
          </div>
        </div>

        <button
          onClick={(event) => {
            event.stopPropagation()
            handleAdd()
          }}
          disabled={isUnavailable}
          className={cn(
            "mt-auto flex w-full items-center justify-center gap-1.5 rounded-xl px-2 py-1.5 text-xs font-semibold transition-all sm:gap-2 sm:rounded-2xl sm:px-4 sm:py-2.5 sm:text-sm 2xl:py-3 2xl:text-base",
            isMinimal && "hidden md:flex",
            isUnavailable
              ? "cursor-not-allowed bg-gray-200 text-gray-500"
              : "bg-[#1E8A3C] text-white hover:bg-[#176B2E]",
            isAdded && "animate-pop"
          )}
        >
          <ShoppingCart className="h-3.5 w-3.5 sm:h-4 sm:w-4" />
          {disabled ? (
            <span className="truncate">{disabledLabel}</span>
          ) : (
            <>
              <span className="sm:hidden">Ajouter</span>
              <span className="hidden sm:inline">Ajouter au panier</span>
            </>
          )}
        </button>
      </div>
    </article>
  )
}

"use client"

import { useEffect, useState, useCallback } from "react"
import { usePathname, useRouter } from "next/navigation"
import { useAuth } from "@/hooks/useAuth"
import { useProfile } from "@/hooks/useProfile"

// Routes sans avatar flottant : accueil (avatar dedie), parcours d'auth, et page Parametres (exigence : masque uniquement sur Reglages).
const HIDE_ON_ROUTES = ["/pwa-welcome", "/login", "/verify", "/onboarding", "/parametres"]

export function ProfileAvatar() {
  const pathname = usePathname()
  const { user } = useAuth()
  const { getProfile } = useProfile()
  const router = useRouter()
  const [avatarUrl, setAvatarUrl] = useState<string | null>(null)
  const [photoVersion, setPhotoVersion] = useState(
    () => Number(typeof window !== "undefined" ? localStorage.getItem("souki_photo_version") || "0" : "0")
  )

  // Listen for cross-component photo update events
  const handlePhotoUpdated = useCallback((e: Event) => {
    const detail = (e as CustomEvent).detail
    if (detail?.version) setPhotoVersion(detail.version)
  }, [])

  useEffect(() => {
    window.addEventListener("souki:photo-updated", handlePhotoUpdated)
    return () => window.removeEventListener("souki:photo-updated", handlePhotoUpdated)
  }, [handlePhotoUpdated])

  useEffect(() => {
    let isMounted = true
    const loadAvatar = async () => {
      try {
        const profile = await getProfile()
        if (!isMounted) return
        setAvatarUrl(profile.photo_url ?? profile.avatar_url ?? null)
      } catch {
        if (!isMounted) return
        setAvatarUrl(null)
      }
    }
    if (user) void loadAvatar()
    return () => { isMounted = false }
  }, [getProfile, user?.id, photoVersion])

  if (!user) return null
  if (HIDE_ON_ROUTES.some((r) => pathname.startsWith(r))) return null

  const initials = user.email
    ? user.email.substring(0, 1).toUpperCase()
    : user.phone
      ? user.phone.slice(-2)
      : "U"

  return (
    <button
      onClick={() => router.push("/parametres")}
      className="fixed right-3 top-3 z-50 flex h-11 w-11 items-center justify-center overflow-hidden rounded-full bg-gradient-to-br from-[#1B4332] to-[#2D6A4F] text-sm font-black text-white shadow-md ring-2 ring-white transition-transform active:scale-95 md:hidden"
      aria-label="Profil et paramètres"
    >
      {avatarUrl ? (
        <img src={`${avatarUrl}${avatarUrl.includes("?") ? "&" : "?"}v=${photoVersion}`} alt="Profil" className="h-full w-full object-cover" />
      ) : (
        initials
      )}
    </button>
  )
}

"use client"

import { useEffect, useState } from "react"
import { Download, X } from "lucide-react"

import { Button } from "@/components/ui/button"
import { isPwaStandalone } from "@/lib/pwa"
import { useAuth } from "@/hooks/useAuth"

type BeforeInstallPromptEvent = Event & {
  prompt: () => Promise<void>
  userChoice: Promise<{ outcome: "accepted" | "dismissed"; platform: string }>
}

// Seul l'admin ne voit PAS la banniere d'installation. Tous les autres profils
// Les clients et les visiteurs anonymes peuvent installer cette PWA.
const EXCLUDED_ROLES = ["ADMIN"]

export function PwaInstallPrompt() {
  const { user } = useAuth()
  const [installPrompt, setInstallPrompt] = useState<BeforeInstallPromptEvent | null>(null)
  const [isMobile, setIsMobile] = useState(false)
  const [isStandalone, setIsStandalone] = useState(true)
  const [dismissed, setDismissed] = useState(false)
  const [showHelp, setShowHelp] = useState(false)

  // Detection mobile + standalone (cote client uniquement). Tant que l'effet
  // n'a pas tourne, isMobile=false / isStandalone=true => rien ne s'affiche
  // (pas de flash au rendu serveur).
  useEffect(() => {
    const mediaQuery = window.matchMedia("(max-width: 767px)")
    const updateIsMobile = () => setIsMobile(mediaQuery.matches)
    updateIsMobile()
    mediaQuery.addEventListener("change", updateIsMobile)

    setIsStandalone(isPwaStandalone())

    return () => mediaQuery.removeEventListener("change", updateIsMobile)
  }, [])

  useEffect(() => {
    const handleBeforeInstallPrompt = (event: Event) => {
      // On capture l'evenement pour declencher l'installation au clic.
      event.preventDefault()
      if (isPwaStandalone()) return
      setInstallPrompt(event as BeforeInstallPromptEvent)
    }

    const handleAppInstalled = () => {
      setInstallPrompt(null)
      setDismissed(true)
    }

    window.addEventListener("beforeinstallprompt", handleBeforeInstallPrompt)
    window.addEventListener("appinstalled", handleAppInstalled)

    return () => {
      window.removeEventListener("beforeinstallprompt", handleBeforeInstallPrompt)
      window.removeEventListener("appinstalled", handleAppInstalled)
    }
  }, [])

  // Masquee uniquement pour l'admin ; visible pour tous les autres profils.
  const isExcludedUser =
    !!user &&
    [user.role, user.legacy_role, ...(user.roles ?? [])]
      .filter(Boolean)
      .map((role) => String(role).toUpperCase())
      .some((role) => EXCLUDED_ROLES.includes(role))

  const handleDownload = async () => {
    if (installPrompt) {
      await installPrompt.prompt()
      await installPrompt.userChoice
      setInstallPrompt(null)
      setDismissed(true)
      return
    }
    // Pas de prompt natif disponible (iOS, ou criteres pas encore remplis) :
    // on deplie les instructions manuelles.
    setShowHelp((value) => !value)
  }

  if (isStandalone || !isMobile || isExcludedUser || dismissed) {
    return null
  }

  return (
    <div
      className="fixed inset-x-3 bottom-24 z-[70] mx-auto max-w-md rounded-2xl border border-[#1E8A3C]/20 bg-white p-3 shadow-2xl shadow-black/15"
      role="status"
      aria-live="polite"
    >
      <div className="flex items-center gap-3">
        <div className="flex size-10 shrink-0 items-center justify-center rounded-xl bg-[#1E8A3C] text-white">
          <Download className="size-5" aria-hidden="true" />
        </div>
        <div className="min-w-0 flex-1">
          <p className="text-sm font-semibold text-[#264129]">Télécharger SOUKI</p>
          <p className="text-xs leading-5 text-[#6F8070]">
            Installez l&apos;application pour un accès rapide, en plein écran.
          </p>
        </div>
        <Button
          type="button"
          size="icon-sm"
          variant="ghost"
          className="shrink-0"
          onClick={() => setDismissed(true)}
          aria-label="Masquer l'installation"
        >
          <X className="size-4" aria-hidden="true" />
        </Button>
      </div>

      <Button
        type="button"
        className="mt-3 w-full bg-[#F07C00] text-white hover:bg-[#D66B00]"
        onClick={handleDownload}
      >
        <Download className="size-4" aria-hidden="true" />
        Télécharger l&apos;application
      </Button>

      {showHelp && (
        <p className="mt-3 rounded-xl bg-[#1E8A3C]/10 px-3 py-2 text-xs font-medium leading-5 text-[#1E8A3C]">
          Sur iPhone : appuyez sur <strong>Partager</strong> puis « Sur l&apos;écran d&apos;accueil ».
          Sur Android : menu <strong>⋮</strong> puis « Installer l&apos;application ».
        </p>
      )}
    </div>
  )
}

"use client"

import { useEffect, useState } from "react"
import { usePathname } from "next/navigation"
import { useAuth } from "@/hooks/useAuth"
import { loadStoredCart } from "@/lib/catalogue"
import { isPwaStandalone } from "@/lib/pwa"
import { MobileBottomNav } from "@/components/souki/mobile-bottom-nav"
import { ProfileAvatar } from "@/components/souki/profile-avatar"

const HIDDEN_ROUTES = [
  "/login",
  "/verify",
  "/onboarding",
  "/catalogue",
  "/checkout",
  "/historique",
]

function isNavHidden(pathname: string): boolean {
  return HIDDEN_ROUTES.some((route) => pathname.startsWith(route))
}

export function PwaNavShell() {
  const pathname = usePathname()
  const { isAuthenticated } = useAuth()
  const [isStandalone, setIsStandalone] = useState(false)
  const [cartCount, setCartCount] = useState(0)

  useEffect(() => {
    setIsStandalone(isPwaStandalone())
    setCartCount(loadStoredCart().length)

    const updateCartCount = () => setCartCount(loadStoredCart().length)
    window.addEventListener("souki:cart-updated", updateCartCount)
    window.addEventListener("storage", updateCartCount)

    return () => {
      window.removeEventListener("souki:cart-updated", updateCartCount)
      window.removeEventListener("storage", updateCartCount)
    }
  }, [])

  if (!isStandalone || isNavHidden(pathname)) return null

  return (
    <>
      {isAuthenticated && <ProfileAvatar />}
      <MobileBottomNav cartCount={cartCount} />
    </>
  )
}

"use client"

import { useEffect, useState } from "react"
import { Heart, Minus, Plus, Share2, ShoppingBasket, X } from "lucide-react"

import type { CatalogueProduct } from "@/lib/catalogue"
import { formatQuantity, getProductDescription, isIllustrationImage } from "@/lib/catalogue"
import { cn } from "@/lib/utils"
import { useHaptic } from "@/hooks/useHaptic"

/**
 * Fiche produit en feuille plein écran (mobile) / modale centrée (desktop),
 * inspirée des références (image hero, note, prix + prix barré + remise,
 * stepper de quantité, favori en cœur, CTA "Ajouter au panier" collant en bas).
 *
 * L'ajout referme la feuille : l'utilisateur revient au catalogue et poursuit
 * ses achats. Le favori est piloté par le parent (localStorage via useFavorites).
 */
export function ProductDetailSheet({
  product,
  open,
  onClose,
  onAddToCart,
  isFavorite,
  onToggleFavorite,
}: {
  product: CatalogueProduct | null
  open: boolean
  onClose: () => void
  onAddToCart: (id: number, quantity: number) => void
  isFavorite: boolean
  onToggleFavorite: () => void
}) {
  const haptic = useHaptic()
  const step = product?.quantityStep ?? (product?.unit === "kg" ? 0.5 : 1)
  const [quantity, setQuantity] = useState(step)

  // Réinitialise la quantité à chaque produit ouvert.
  useEffect(() => {
    if (product) setQuantity(product.quantityStep ?? (product.unit === "kg" ? 0.5 : 1))
  }, [product])

  // Verrou du scroll de fond + fermeture au clavier.
  useEffect(() => {
    if (!open) return
    const previous = document.body.style.overflow
    document.body.style.overflow = "hidden"
    const onKey = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose()
    }
    window.addEventListener("keydown", onKey)
    return () => {
      document.body.style.overflow = previous
      window.removeEventListener("keydown", onKey)
    }
  }, [open, onClose])

  if (!open || !product) return null

  const displayUnit = product.displayUnit || product.unit
  const isOutOfStock = false
  const oldPrice =
    typeof product.prix_khddar_estime === "number" && product.prix_khddar_estime > product.price
      ? product.prix_khddar_estime
      : null
  const discountPct = oldPrice ? Math.round((1 - product.price / oldPrice) * 100) : 0
  const lineTotal = product.price * quantity

  const increment = () => {
    haptic("light")
    setQuantity((value) => Number((value + step).toFixed(2)))
  }
  const decrement = () => {
    haptic("light")
    setQuantity((value) => Math.max(step, Number((value - step).toFixed(2))))
  }

  const handleFavorite = () => {
    haptic("medium")
    onToggleFavorite()
  }

  const handleShare = async () => {
    haptic("light")
    try {
      if (typeof navigator !== "undefined" && navigator.share) {
        await navigator.share({ title: product.name, text: `${product.name} sur SOUKI` })
      }
    } catch {
      // partage annulé : rien à faire
    }
  }

  const handleAdd = () => {
    if (isOutOfStock) return
    haptic("success")
    onAddToCart(product.id, quantity)
    onClose()
  }

  return (
    <div
      className="fixed inset-0 z-[80] flex flex-col justify-end bg-[#122018]/55 backdrop-blur-sm sm:items-center sm:justify-center sm:p-6"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-label={`Fiche produit ${product.name}`}
    >
      <div
        className="animate-slide-up flex max-h-[92dvh] w-full flex-col overflow-hidden rounded-t-[28px] bg-white shadow-[0_-8px_40px_rgba(0,0,0,0.18)] sm:max-w-md sm:rounded-[28px]"
        onClick={(event) => event.stopPropagation()}
      >
        <div className="flex-1 overflow-y-auto scrollbar-none">
          {/* Image hero + actions superposées */}
          <div className="relative aspect-square w-full overflow-hidden bg-gradient-to-b from-[#EAF6EC] via-[#F3FAF4] to-white">
            {/* halo lumineux derriere le produit (profondeur, effet studio) */}
            <div className="pointer-events-none absolute left-1/2 top-[44%] h-[62%] w-[62%] -translate-x-1/2 -translate-y-1/2 rounded-full bg-white/70 blur-2xl" />
            <img
              src={product.image}
              alt={product.name}
              className={cn(
                "relative h-full w-full",
                isIllustrationImage(product.image)
                  ? "object-contain p-7 mix-blend-multiply"
                  : "object-cover",
              )}
              onError={(event) => {
                if (product.fallbackImage) {
                  ;(event.currentTarget as HTMLImageElement).src = product.fallbackImage
                }
              }}
            />
            <div className="absolute inset-x-0 top-0 flex items-center justify-between p-3 pt-[max(env(safe-area-inset-top),0.75rem)]">
              <button
                type="button"
                onClick={onClose}
                aria-label="Fermer"
                className="flex h-10 w-10 items-center justify-center rounded-full bg-white/90 text-[#264129] shadow-md backdrop-blur active:scale-90"
              >
                <X className="h-5 w-5" />
              </button>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={handleShare}
                  aria-label="Partager"
                  className="flex h-10 w-10 items-center justify-center rounded-full bg-white/90 text-[#264129] shadow-md backdrop-blur active:scale-90"
                >
                  <Share2 className="h-5 w-5" />
                </button>
                <button
                  type="button"
                  onClick={handleFavorite}
                  aria-label={isFavorite ? "Retirer des favoris" : "Ajouter aux favoris"}
                  aria-pressed={isFavorite}
                  className="flex h-10 w-10 items-center justify-center rounded-full bg-white/90 shadow-md backdrop-blur active:scale-90"
                >
                  <Heart
                    className={cn("h-5 w-5 transition-colors", isFavorite ? "fill-[#E4405F] text-[#E4405F]" : "text-[#264129]")}
                  />
                </button>
              </div>
            </div>
            {isOutOfStock ? (
              <span className="absolute bottom-3 left-3 rounded-full bg-red-500 px-3 py-1 text-xs font-bold text-white shadow-sm">
                Rupture de stock
              </span>
            ) : (
              discountPct > 0 && (
                <span className="absolute bottom-3 left-3 rounded-full bg-[#F07C00] px-3 py-1 text-xs font-black text-white shadow-[0_6px_16px_-6px_rgba(240,124,0,0.8)]">
                  -{discountPct}%
                </span>
              )
            )}
          </div>

          <div className="px-5 py-4">
            <div className="flex items-start justify-between gap-3">
              <h2 className="text-2xl font-black leading-tight text-[#233127]">{product.name}</h2>
            </div>
            {product.alias && (
              <p className="mt-1 text-sm font-semibold text-[#6F8070]">« {product.alias} »</p>
            )}

            <div className="mt-3 flex flex-wrap items-baseline gap-x-2 gap-y-1">
              <span className="text-2xl font-black text-[#F07C00]">{product.price.toFixed(2)} DH</span>
              <span className="text-sm font-semibold text-[#6C7E6E]">/ {displayUnit}</span>
              {oldPrice && (
                <span className="text-sm font-semibold text-[#9AA49B] line-through">{oldPrice.toFixed(2)} DH</span>
              )}
            </div>

            <div className="mt-4">
              <h3 className="text-sm font-black uppercase tracking-wide text-[#264129]">Description</h3>
              <p className="mt-1.5 text-sm leading-relaxed text-[#5F735F]">
                {getProductDescription(product.name)}
              </p>
            </div>

            <div className="mt-5 flex items-center justify-between">
              <div>
                <p className="text-sm font-black uppercase tracking-wide text-[#264129]">Quantité</p>
                <p className="mt-0.5 text-xs font-medium text-[#8A8A8A]">{formatQuantity(quantity, product.unit)}</p>
              </div>
              <div className="flex items-center overflow-hidden rounded-full border border-[#CDE8D0] bg-[#F7FCF7]">
                <button
                  type="button"
                  onClick={decrement}
                  disabled={isOutOfStock}
                  className="flex h-11 w-11 items-center justify-center text-[#2E5A33] transition-colors hover:bg-[#E7F5E8] disabled:opacity-40"
                  aria-label="Diminuer"
                >
                  <Minus className="h-4 w-4" />
                </button>
                <span className="min-w-[3.5rem] px-1 text-center text-sm font-black text-[#264129]">
                  {formatQuantity(quantity, product.unit)}
                </span>
                <button
                  type="button"
                  onClick={increment}
                  disabled={isOutOfStock}
                  className="flex h-11 w-11 items-center justify-center text-[#2E5A33] transition-colors hover:bg-[#E7F5E8] disabled:opacity-40"
                  aria-label="Augmenter"
                >
                  <Plus className="h-4 w-4" />
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* CTA collant : total + ajouter au panier */}
        <div className="border-t border-[#EEF2EE] bg-white px-5 pt-3 pb-[max(env(safe-area-inset-bottom),1rem)]">
          <button
            type="button"
            onClick={handleAdd}
            disabled={isOutOfStock}
            className={cn(
              "flex w-full items-center justify-between gap-3 rounded-2xl px-4 py-3.5 text-white transition-all active:scale-[0.98]",
              isOutOfStock
                ? "cursor-not-allowed bg-gray-300"
                : "bg-[#1E8A3C] shadow-[0_14px_30px_-16px_rgba(30,138,60,0.9)]",
            )}
          >
            <span className="flex flex-col items-start leading-tight">
              <span className="text-[11px] font-semibold text-white/80">Total</span>
              <span className="souki-tabular-nums text-[17px] font-black">{lineTotal.toFixed(2)} DH</span>
            </span>
            <span className="flex items-center gap-2 text-[15px] font-black">
              {isOutOfStock ? (
                "Indisponible"
              ) : (
                <>
                  <ShoppingBasket className="h-4 w-4" />
                  Ajouter au panier
                </>
              )}
            </span>
          </button>
        </div>
      </div>
    </div>
  )
}

"use client"

import { useEffect, useState, type ReactNode } from "react"
import { isPwaStandalone } from "@/lib/pwa"
import { cn } from "@/lib/utils"

/**
 * Barre d'action fixee en bas d'ecran (CTA principal du parcours : "Commander",
 * "Payer", "Ajouter au panier"…). Place les actions primaires dans la zone la
 * plus accessible au pouce (heatmap basse).
 *
 * Gere la safe-area basse et, quand `aboveNav` est vrai, se positionne au-dessus
 * de `MobileBottomNav` (~5rem) — uniquement en PWA installee : sur le web la
 * navigation est desormais en haut de page, la barre se colle donc en bas.
 * Visible en mobile uniquement (`md:hidden`) pour ne pas alterer la mise en
 * page web desktop.
 */
export function StickyBottomBar({
  children,
  className,
  aboveNav = false,
}: {
  children: ReactNode
  className?: string
  /** Remonte la barre au-dessus de la barre de navigation mobile (PWA). */
  aboveNav?: boolean
}) {
  const [isStandalone, setIsStandalone] = useState(false)

  useEffect(() => {
    setIsStandalone(isPwaStandalone())
  }, [])

  return (
    <div
      className={cn(
        "fixed inset-x-0 z-40 border-t border-[#E7F0E8] bg-white/95 px-4 pt-3 backdrop-blur-md md:hidden",
        "shadow-[0_-8px_28px_-16px_rgba(17,59,30,0.35)]",
        aboveNav && isStandalone
          ? "bottom-[calc(env(safe-area-inset-bottom)+4.75rem)] pb-3"
          : "bottom-0 pb-[max(env(safe-area-inset-bottom),0.75rem)]",
        className,
      )}
    >
      <div className="mx-auto max-w-md">{children}</div>
    </div>
  )
}

"use client"

import { useEffect, useRef } from "react"

export type VoiceOrbPhase = "idle" | "listening" | "processing"

interface VoiceOrbProps {
  phase: VoiceOrbPhase
  /** Live microphone stream — tapped for real-time amplitude while listening. */
  stream?: MediaStream | null
  /** Rendered size in CSS pixels (square). */
  size?: number
  className?: string
}

/* SOUKI palette — natural green + glassy cyan/turquoise core */
const PALETTE = {
  cyan: [80, 220, 230] as const,
  turquoise: [40, 190, 170] as const,
  green: [76, 184, 74] as const,
  deepGreen: [30, 138, 60] as const,
}

const rgba = (c: readonly [number, number, number], a: number) =>
  `rgba(${c[0]}, ${c[1]}, ${c[2]}, ${a})`

/**
 * VoiceOrb — a living, glass-liquid orb that reacts to the user's voice.
 *
 * - `listening`: the orb breathes with the real microphone amplitude
 *   (Web Audio AnalyserNode → RMS), emits concentric voice rings and
 *   floating particles, and morphs organically.
 * - `processing`: the voice rings dissolve and fresh produce is drawn in,
 *   orbiting and being absorbed toward the luminous sprout core — the
 *   "AI is building your basket" moment.
 * - `idle`: a calm, slow breathing glow.
 *
 * Everything is rendered on a single canvas for 60fps on mobile/PWA with
 * zero animation dependencies.
 */
export function VoiceOrb({ phase, stream, size = 220, className }: VoiceOrbProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const phaseRef = useRef<VoiceOrbPhase>(phase)
  phaseRef.current = phase

  // Web Audio analyser state
  const audioCtxRef = useRef<AudioContext | null>(null)
  const analyserRef = useRef<AnalyserNode | null>(null)
  const dataRef = useRef<Uint8Array | null>(null)
  const sourceRef = useRef<MediaStreamAudioSourceNode | null>(null)

  // Smoothed amplitude (0..1) shared across frames
  const ampRef = useRef(0)

  /* ── Attach / detach the analyser to the live stream ── */
  useEffect(() => {
    if (!stream || phase !== "listening") return

    let cancelled = false
    try {
      const Ctx =
        window.AudioContext ||
        (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext
      const audioCtx = new Ctx()
      const analyser = audioCtx.createAnalyser()
      analyser.fftSize = 512
      analyser.smoothingTimeConstant = 0.75
      const source = audioCtx.createMediaStreamSource(stream)
      source.connect(analyser)

      if (cancelled) {
        audioCtx.close()
        return
      }
      audioCtxRef.current = audioCtx
      analyserRef.current = analyser
      sourceRef.current = source
      dataRef.current = new Uint8Array(analyser.frequencyBinCount)
    } catch {
      // Audio analysis is a progressive enhancement; the orb still breathes on its own.
    }

    return () => {
      cancelled = true
      try {
        sourceRef.current?.disconnect()
        analyserRef.current?.disconnect()
        audioCtxRef.current?.close()
      } catch {
        /* noop */
      }
      sourceRef.current = null
      analyserRef.current = null
      audioCtxRef.current = null
      dataRef.current = null
    }
  }, [stream, phase])

  /* ── Render loop ── */
  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const ctx = canvas.getContext("2d")
    if (!ctx) return

    const dpr = Math.min(window.devicePixelRatio || 1, 2)
    canvas.width = size * dpr
    canvas.height = size * dpr
    ctx.scale(dpr, dpr)

    const cx = size / 2
    const cy = size / 2
    const baseR = size * 0.3

    // Particles orbiting inside the orb
    const particles = Array.from({ length: 22 }, () => ({
      angle: Math.random() * Math.PI * 2,
      radius: baseR * (0.35 + Math.random() * 0.6),
      speed: (0.002 + Math.random() * 0.006) * (Math.random() > 0.5 ? 1 : -1),
      r: 0.6 + Math.random() * 1.8,
      drift: Math.random() * Math.PI * 2,
    }))

    // Produce that gets "assembled" during the processing phase
    const VEG = ["🍅", "🥕", "🥬", "🥒", "🍓"]
    const produce = VEG.map((emoji, i) => ({
      emoji,
      angle: (i / VEG.length) * Math.PI * 2,
      speed: 0.012 + i * 0.0015,
      orbit: baseR * 1.15,
    }))

    let raf = 0
    let t = 0
    const rings: Array<{ r: number; alpha: number }> = []
    let ringTimer = 0

    const draw = () => {
      t += 1
      const ph = phaseRef.current
      ctx.clearRect(0, 0, size, size)

      /* 1. Read amplitude (smoothed) */
      let target = 0
      const analyser = analyserRef.current
      const data = dataRef.current
      if (ph === "listening" && analyser && data) {
        analyser.getByteTimeDomainData(data)
        let sum = 0
        for (let i = 0; i < data.length; i++) {
          const v = (data[i] - 128) / 128
          sum += v * v
        }
        target = Math.min(1, Math.sqrt(sum / data.length) * 3.2)
      } else if (ph === "processing") {
        target = 0.4 + Math.sin(t * 0.05) * 0.18 // autonomous pulse
      } else {
        target = 0.12 + Math.sin(t * 0.03) * 0.06 // idle breathing
      }
      ampRef.current += (target - ampRef.current) * 0.18
      const amp = ampRef.current

      // Organic radius: base + voice swell + subtle wobble
      const radius = baseR * (1 + amp * 0.32) + Math.sin(t * 0.08) * 2

      /* 2. Outer halo */
      const halo = ctx.createRadialGradient(cx, cy, radius * 0.6, cx, cy, radius * 2)
      halo.addColorStop(0, rgba(PALETTE.cyan, 0.28 + amp * 0.25))
      halo.addColorStop(0.5, rgba(PALETTE.turquoise, 0.1))
      halo.addColorStop(1, rgba(PALETTE.turquoise, 0))
      ctx.fillStyle = halo
      ctx.fillRect(0, 0, size, size)

      /* 3. Glass sphere body — organic morphing blob */
      ctx.beginPath()
      const lobes = 6
      for (let a = 0; a <= Math.PI * 2 + 0.01; a += 0.08) {
        const wobble =
          Math.sin(a * lobes + t * 0.06) * (2 + amp * 7) +
          Math.cos(a * (lobes - 2) - t * 0.04) * (1.5 + amp * 4)
        const rr = radius + wobble
        const x = cx + Math.cos(a) * rr
        const y = cy + Math.sin(a) * rr
        a === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y)
      }
      ctx.closePath()
      const body = ctx.createRadialGradient(
        cx - radius * 0.3,
        cy - radius * 0.35,
        radius * 0.1,
        cx,
        cy,
        radius * 1.1
      )
      body.addColorStop(0, rgba(PALETTE.cyan, 0.55))
      body.addColorStop(0.45, rgba(PALETTE.turquoise, 0.4))
      body.addColorStop(0.8, rgba(PALETTE.deepGreen, 0.32))
      body.addColorStop(1, rgba(PALETTE.deepGreen, 0.12))
      ctx.fillStyle = body
      ctx.shadowColor = rgba(PALETTE.cyan, 0.6)
      ctx.shadowBlur = 30 + amp * 40
      ctx.fill()
      ctx.shadowBlur = 0

      /* 4. Glass rim highlight */
      ctx.strokeStyle = rgba(PALETTE.cyan, 0.35 + amp * 0.3)
      ctx.lineWidth = 1.5
      ctx.stroke()

      // Top-left specular reflection
      ctx.beginPath()
      ctx.ellipse(
        cx - radius * 0.32,
        cy - radius * 0.4,
        radius * 0.28,
        radius * 0.16,
        -0.6,
        0,
        Math.PI * 2
      )
      ctx.fillStyle = "rgba(255,255,255,0.35)"
      ctx.fill()

      /* 5. Concentric voice rings (listening only) */
      if (ph === "listening") {
        ringTimer += 1
        if (ringTimer % 14 === 0 && amp > 0.08) {
          rings.push({ r: radius, alpha: 0.5 })
        }
      }
      for (let i = rings.length - 1; i >= 0; i--) {
        const ring = rings[i]
        ring.r += 1.4
        ring.alpha -= 0.012
        if (ring.alpha <= 0) {
          rings.splice(i, 1)
          continue
        }
        ctx.beginPath()
        ctx.arc(cx, cy, ring.r, 0, Math.PI * 2)
        ctx.strokeStyle = rgba(PALETTE.cyan, ring.alpha)
        ctx.lineWidth = 1.2
        ctx.stroke()
      }

      /* 6. Inner particles */
      ctx.save()
      for (const p of particles) {
        p.angle += p.speed * (1 + amp * 2)
        p.drift += 0.02
        const wob = Math.sin(p.drift) * 4
        const x = cx + Math.cos(p.angle) * (p.radius + wob)
        const y = cy + Math.sin(p.angle) * (p.radius + wob)
        ctx.beginPath()
        ctx.arc(x, y, p.r, 0, Math.PI * 2)
        ctx.fillStyle = rgba(PALETTE.cyan, 0.5 + amp * 0.4)
        ctx.fill()
      }
      ctx.restore()

      /* 7. Luminous sprout core */
      const coreR = radius * (0.16 + amp * 0.05)
      const core = ctx.createRadialGradient(cx, cy, 0, cx, cy, coreR * 3)
      core.addColorStop(0, rgba(PALETTE.cyan, 0.95))
      core.addColorStop(0.4, rgba(PALETTE.green, 0.6))
      core.addColorStop(1, rgba(PALETTE.green, 0))
      ctx.fillStyle = core
      ctx.beginPath()
      ctx.arc(cx, cy, coreR * 3, 0, Math.PI * 2)
      ctx.fill()

      // Sprout glyph (two leaves + stem)
      ctx.save()
      ctx.translate(cx, cy)
      ctx.strokeStyle = "rgba(255,255,255,0.95)"
      ctx.lineWidth = 2
      ctx.lineCap = "round"
      const s = coreR * 0.9
      ctx.beginPath()
      ctx.moveTo(0, s)
      ctx.lineTo(0, -s * 0.2)
      ctx.stroke()
      ctx.beginPath()
      ctx.ellipse(-s * 0.45, -s * 0.35, s * 0.5, s * 0.28, 0.7, 0, Math.PI * 2)
      ctx.ellipse(s * 0.45, -s * 0.35, s * 0.5, s * 0.28, -0.7, 0, Math.PI * 2)
      ctx.fillStyle = "rgba(255,255,255,0.9)"
      ctx.fill()
      ctx.restore()

      /* 8. Processing — produce orbits and is absorbed into the core */
      if (ph === "processing") {
        const cycle = (t % 220) / 220 // 0..1 absorption progress
        ctx.font = `${size * 0.11}px serif`
        ctx.textAlign = "center"
        ctx.textBaseline = "middle"
        produce.forEach((veg, i) => {
          veg.angle += veg.speed
          const localCycle = (cycle + i / produce.length) % 1
          const orbit = veg.orbit * (1 - localCycle) // spiral inward
          const x = cx + Math.cos(veg.angle) * orbit
          const y = cy + Math.sin(veg.angle) * orbit
          const scale = 0.6 + (1 - localCycle) * 0.6
          const alpha = Math.min(1, localCycle * 4) * (1 - Math.max(0, localCycle - 0.85) * 6)
          ctx.save()
          ctx.globalAlpha = Math.max(0, alpha)
          ctx.translate(x, y)
          ctx.scale(scale, scale)
          ctx.fillText(veg.emoji, 0, 0)
          ctx.restore()
        })
      }

      raf = requestAnimationFrame(draw)
    }

    raf = requestAnimationFrame(draw)
    return () => cancelAnimationFrame(raf)
  }, [size])

  return (
    <canvas
      ref={canvasRef}
      width={size}
      height={size}
      className={className}
      style={{ width: size, height: size }}
      aria-hidden="true"
    />
  )
}

export default VoiceOrb

"use client"

import React, { createContext, useContext, useEffect, useState, ReactNode } from "react"
import { toast } from "sonner"
import { API_BASE_URL } from "@/lib/api"

export interface User {
  id: number
  email?: string
  phone?: string
  role: string
  legacy_role?: string | null
  roles: string[]
  permissions: string[]
  is_verified: boolean
  is_active: boolean
  default_dashboard: string
  /** false = compte jamais onboarde. Porte par le serveur, pas par l'appareil. */
  onboarding_completed: boolean
  profiles?: {
    client?: { code_parrainage?: string | null; is_blacklisted?: boolean }
    [key: string]: any
  }
}

interface AuthContextType {
  user: User | null
  token: string | null
  isLoading: boolean
  isAuthenticated: boolean
  login: (loginId: string, password: string, role?: string) => Promise<User>
  googleLogin: (googleToken: string, role?: string) => Promise<User>
  logout: () => Promise<void>
  validateToken: () => Promise<boolean>
  hasRole: (role: string) => boolean
  can: (permission: string) => boolean
}

const AuthContext = createContext<AuthContextType | undefined>(undefined)
const AUTH_REQUEST_TIMEOUT_MS = 10000
// Cle de synchronisation inter-onglets (valeur = horodatage, jamais le token).
const AUTH_SYNC_STORAGE_KEY = "souki-auth-sync"
// Marqueur de session non secret expose via useAuth().token quand l'utilisateur est
// connecte. Le vrai JWT vit exclusivement dans le cookie httpOnly.
const COOKIE_SESSION_SENTINEL = "cookie-session"
const NETWORK_RETRY_ATTEMPTS = 3
const NETWORK_RETRY_DELAY_MS = 1200
const NETWORK_TIMEOUT_MS = 5000

const isNetworkFetchError = (error: unknown) =>
  error instanceof TypeError && error.message.toLowerCase().includes("fetch")

const wait = (ms: number) =>
  new Promise((resolve) => {
    window.setTimeout(resolve, ms)
  })

const isRequestTimeoutError = (error: unknown) =>
  error instanceof DOMException && error.name === "AbortError"

function buildApiUnavailableMessage() {
  return `Impossible de joindre l'API (${API_BASE_URL}). Verifiez que le back-end est demarre et accessible depuis le front.`
}

function buildRequestTimeoutMessage() {
  return `L'API met trop de temps a repondre (${API_BASE_URL}). Verifiez que le back-end et la base de donnees sont bien disponibles.`
}

async function readErrorDetail(response: Response) {
  const contentType = response.headers.get("content-type") || ""
  if (!contentType.includes("application/json")) {
    // Reponse non-JSON (page d'erreur HTML d'un proxy/CDN, 5xx, tunnel KO...) :
    // ne JAMAIS exposer ce contenu brut a l'utilisateur. On renvoie null pour que
    // l'appelant affiche un message generique propre.
    return null
  }

  try {
    const payload = await response.json()
    return payload?.detail ? String(payload.detail) : null
  } catch {
    return null
  }
}

async function fetchWithTimeout(
  input: RequestInfo | URL,
  init?: RequestInit,
  timeoutMs = AUTH_REQUEST_TIMEOUT_MS
) {
  const controller = new AbortController()
  const timeoutHandle = window.setTimeout(() => controller.abort(), timeoutMs)

  try {
    return await fetch(input, {
      ...init,
      signal: controller.signal,
    })
  } finally {
    window.clearTimeout(timeoutHandle)
  }
}

function normalizeUser(payload: any): User {
  const roles = Array.isArray(payload?.roles) ? payload.roles.map((value: string) => String(value).toUpperCase()) : []
  const permissions = Array.isArray(payload?.permissions)
    ? payload.permissions.map((value: string) => String(value))
    : []

  return {
    id: Number(payload?.id ?? 0),
    email: payload?.email ?? undefined,
    phone: payload?.phone ?? undefined,
    role: String(payload?.role || payload?.legacy_role || roles[0] || "CLIENT").toUpperCase(),
    legacy_role: payload?.legacy_role ? String(payload.legacy_role).toUpperCase() : null,
    roles,
    permissions,
    is_verified: Boolean(payload?.is_verified),
    is_active: payload?.is_active !== false,
    default_dashboard: String(payload?.default_dashboard || "/"),
    onboarding_completed: Boolean(payload?.onboarding_completed),
    profiles: payload?.profiles && typeof payload.profiles === "object" ? payload.profiles : undefined,
  }
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<User | null>(null)
  const [token, setToken] = useState<string | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [isAuthenticated, setIsAuthenticated] = useState(false)

  // Source de verite = cookie httpOnly. On interroge /auth/me avec credentials:"include"
  // (le navigateur joint le cookie automatiquement) ; aucun token n'est requis cote JS.
  const fetchCurrentUser = async (): Promise<{ user: User | null; networkError: boolean }> => {
    for (let attempt = 1; attempt <= NETWORK_RETRY_ATTEMPTS; attempt += 1) {
      try {
        const response = await fetchWithTimeout(`${API_BASE_URL}/auth/me`, {
          method: "GET",
          headers: { "Content-Type": "application/json" },
          credentials: "include",
        }, NETWORK_TIMEOUT_MS)

        // Un 401/403 signifie simplement que le visiteur n'a pas de session :
        // le rejouer ne peut pas le reconnecter et surcharge inutilement le backend.
        if (!response.ok) {
          return { user: null, networkError: false }
        }

        const userData = normalizeUser(await response.json())
        setUser(userData)
        return { user: userData, networkError: false }
      } catch (error) {
        const isNetworkError = isRequestTimeoutError(error) || isNetworkFetchError(error)
        if (isNetworkError && attempt < NETWORK_RETRY_ATTEMPTS) {
          await wait(NETWORK_RETRY_DELAY_MS)
          continue
        }

        if (isRequestTimeoutError(error)) {
          toast.error("Le serveur met trop de temps à répondre. Réessayez dans un instant.", {
            id: "auth-network",
          })
          return { user: null, networkError: true }
        }
        if (isNetworkFetchError(error)) {
          toast.error("Service momentanément indisponible. Vérifiez votre connexion.", {
            id: "auth-network",
          })
          return { user: null, networkError: true }
        }
        console.warn(
          "Session refresh error:",
          error instanceof Error ? error.message : String(error)
        )
        return { user: null, networkError: false }
      }
    }

    return { user: null, networkError: true }
  }

  const clearLocalSession = () => {
    setToken(null)
    setUser(null)
    setIsAuthenticated(false)
  }

  // Declenche un evenement "storage" dans les autres onglets pour resynchroniser la session.
  const notifyAuthSync = () => {
    try {
      localStorage.setItem(AUTH_SYNC_STORAGE_KEY, String(Date.now()))
    } catch {
      // localStorage indisponible (mode prive) : la synchro inter-onglets est juste ignoree.
    }
  }

  // Recharge l'utilisateur courant depuis le cookie httpOnly (seule source de verite).
  // nextToken sert uniquement de signal "connexion" (non-null) vs "deconnexion" (null) ;
  // sa valeur reelle est ignoree : le vrai JWT n'est JAMAIS conserve cote JS (anti-XSS).
  const syncAuthState = async (nextToken: string | null): Promise<User | null> => {
    if (nextToken === null) {
      clearLocalSession()
      return null
    }

    const { user: nextUser, networkError } = await fetchCurrentUser()
    if (nextUser) {
      // Marqueur de session NON secret. Les pages qui conditionnent leurs appels sur
      // `token` (ex: supplier, livreur) continuent de fonctionner, et l'en-tete
      // "Authorization: Bearer cookie-session" eventuellement envoye est ignore par le
      // backend (il privilegie le cookie). Le JWT reel reste dans le cookie httpOnly.
      setToken(COOKIE_SESSION_SENTINEL)
      setIsAuthenticated(true)
      return nextUser
    }

    // Ne pas effacer la session si le backend est simplement indisponible temporairement.
    if (networkError) {
      setIsAuthenticated(false)
      return null
    }

    clearLocalSession()
    return null
  }

  // Verifie la session via le cookie, sans token en memoire (init, autres onglets).
  const refreshSession = (): Promise<User | null> => syncAuthState("")

  useEffect(() => {
    const initializeAuth = async () => {
      setIsLoading(true)
      // On tente toujours une reprise de session via le cookie httpOnly.
      await refreshSession()
      setIsLoading(false)
    }

    // Synchronisation inter-onglets : on relaie un signal non sensible (jamais le token).
    const handleStorageChange = async (e: StorageEvent) => {
      if (e.key === AUTH_SYNC_STORAGE_KEY) {
        await refreshSession()
      }
    }

    const handleAuthTokenChanged = async (event: Event) => {
      const customEvent = event as CustomEvent<{ token: string | null }>
      await syncAuthState(customEvent.detail?.token ?? "")
    }

    void initializeAuth()
    window.addEventListener("storage", handleStorageChange)
    window.addEventListener("auth-token-changed", handleAuthTokenChanged as EventListener)

    return () => {
      window.removeEventListener("storage", handleStorageChange)
      window.removeEventListener("auth-token-changed", handleAuthTokenChanged as EventListener)
    }
  }, [])

  const validateToken = async (): Promise<boolean> => {
    return Boolean(await refreshSession())
  }

  const authenticate = async (endpoint: string, payload: Record<string, unknown>) => {
    try {
      let response: Response | null = null

      for (let attempt = 1; attempt <= NETWORK_RETRY_ATTEMPTS; attempt += 1) {
        try {
          response = await fetchWithTimeout(`${API_BASE_URL}${endpoint}`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(payload),
            // credentials:"include" pour que le navigateur stocke le cookie httpOnly renvoye.
            credentials: "include",
          }, NETWORK_TIMEOUT_MS)
          break
        } catch (error) {
          const isTimeout = isRequestTimeoutError(error)
          if ((isTimeout || isNetworkFetchError(error)) && attempt < NETWORK_RETRY_ATTEMPTS) {
            await wait(NETWORK_RETRY_DELAY_MS)
            continue
          }

          if (isTimeout || isNetworkFetchError(error)) {
            throw new Error("Le serveur backend ne répond pas encore. Attendez 2 à 3 secondes puis réessayez.")
          }

          throw error
        }
      }

      if (!response) {
        throw new Error("Le serveur backend est indisponible.")
      }

      if (!response.ok) {
        const errorDetail = await readErrorDetail(response)
        const fallback =
          response.status >= 500
            ? "Le service est momentanément indisponible. Réessayez dans quelques instants."
            : "Identifiants incorrects ou requête invalide. Vérifiez vos informations."
        throw new Error(errorDetail || fallback)
      }

      const data = await response.json()

      // Chemin rapide : le backend renvoie desormais l'utilisateur complet dans la
      // reponse de login. On evite ainsi un second aller-retour /auth/me (cause du
      // "gel" ressenti pendant plusieurs secondes a la connexion).
      if (data?.user) {
        const nextUser = normalizeUser(data.user)
        setUser(nextUser)
        setToken(COOKIE_SESSION_SENTINEL)
        setIsAuthenticated(true)
        notifyAuthSync()
        return nextUser
      }

      // Repli compatibilite (ancienne API sans champ "user") : on valide via /auth/me.
      const nextUser = await syncAuthState(data.access_token)
      if (!nextUser) {
        throw new Error("Validation du token echouee")
      }
      notifyAuthSync()
      return nextUser
    } catch (error) {
      console.warn(
        "Authentication error:",
        error instanceof Error ? error.message : String(error)
      )
      await syncAuthState(null)
      if (isRequestTimeoutError(error)) {
        throw new Error(buildRequestTimeoutMessage())
      }
      if (isNetworkFetchError(error) || error instanceof TypeError) {
        throw new Error(buildApiUnavailableMessage())
      }
      throw error
    }
  }

  const login = async (loginId: string, password: string, role = "CLIENT") => {
    return authenticate("/auth/login", {
      login_id: loginId,
      password,
      role,
    })
  }

  const googleLogin = async (googleToken: string, role = "CLIENT") => {
    return authenticate("/auth/google", {
      token: googleToken,
      role,
    })
  }

  const logout = async () => {
    // Invalide la session serveur et supprime le cookie httpOnly.
    try {
      await fetchWithTimeout(`${API_BASE_URL}/auth/logout`, {
        method: "POST",
        credentials: "include",
      }, NETWORK_TIMEOUT_MS)
    } catch {
      // On nettoie l'etat local meme si l'appel reseau echoue.
    }
    await syncAuthState(null)
    notifyAuthSync()
  }

  const hasRole = (role: string) => Boolean(user?.roles.includes(role.toUpperCase()))
  const can = (permission: string) => Boolean(user?.permissions.includes(permission))

  return (
    <AuthContext.Provider
      value={{
        user,
        token,
        isLoading,
        isAuthenticated,
        login,
        googleLogin,
        logout,
        validateToken,
        hasRole,
        can,
      }}
    >
      {children}
    </AuthContext.Provider>
  )
}

export function useAuthContext() {
  const context = useContext(AuthContext)
  if (context === undefined) {
    throw new Error("useAuthContext must be used within AuthProvider")
  }
  return context
}

"use client"

import { useCallback, useEffect, useState } from "react"

import { addFavorite, apiCall, removeFavorite } from "@/lib/api"
import type { CatalogueProductDTO } from "@/lib/api"
import { useAuth } from "@/hooks/useAuth"

/**
 * Favoris produits.
 *
 * - Utilisateur connecté : la **source de vérité est le serveur**
 *   (`/api/user/favorites`, cross-device). localStorage sert de cache optimiste
 *   / offline. Chaque toggle est optimiste et confirmé par un appel API ;
 *   en cas d'échec, on revient en arrière.
 * - Invité (sans token) : localStorage uniquement.
 *
 * Le contrat (`favorites`, `isFavorite`, `toggleFavorite`) est inchangé, donc
 * la fiche détail et le catalogue continuent de fonctionner sans modification.
 */
const STORAGE_KEY = "souki_favorites"
const EVENT_NAME = "souki:favorites-updated"

function readFavorites(): number[] {
  if (typeof window === "undefined") return []
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY)
    const parsed = raw ? JSON.parse(raw) : []
    return Array.isArray(parsed) ? parsed.filter((value) => typeof value === "number") : []
  } catch {
    return []
  }
}

function writeFavorites(ids: number[]) {
  window.localStorage.setItem(STORAGE_KEY, JSON.stringify(ids))
  window.dispatchEvent(new CustomEvent(EVENT_NAME))
}

export function useFavorites() {
  const { token } = useAuth()
  const [favorites, setFavorites] = useState<number[]>([])

  // Synchronisation entre instances du hook (même onglet + autres onglets).
  useEffect(() => {
    setFavorites(readFavorites())
    const sync = () => setFavorites(readFavorites())
    window.addEventListener(EVENT_NAME, sync)
    window.addEventListener("storage", sync)
    return () => {
      window.removeEventListener(EVENT_NAME, sync)
      window.removeEventListener("storage", sync)
    }
  }, [])

  // Chargement serveur quand connecté : le serveur fait foi. On n'écrase le cache
  // local QUE si l'appel réussit (un échec réseau ne doit pas vider les favoris).
  useEffect(() => {
    if (!token) return
    let isMounted = true
    void (async () => {
      try {
        const products = await apiCall<CatalogueProductDTO[]>("/api/user/favorites", { token })
        if (!isMounted) return
        const ids = products.map((product) => product.id)
        writeFavorites(ids)
        setFavorites(ids)
      } catch {
        // hors-ligne / session : on garde le cache local
      }
    })()
    return () => {
      isMounted = false
    }
  }, [token])

  const isFavorite = useCallback((id: number) => favorites.includes(id), [favorites])

  const toggleFavorite = useCallback(
    (id: number) => {
      const current = readFavorites()
      const willAdd = !current.includes(id)
      const next = willAdd ? [...current, id] : current.filter((value) => value !== id)

      // Optimiste : maj immédiate du cache + de l'état.
      writeFavorites(next)
      setFavorites(next)

      if (token) {
        const request = willAdd ? addFavorite(id, token) : removeFavorite(id, token)
        request.catch(() => {
          // Rollback en cas d'échec serveur.
          const rolledBack = willAdd
            ? readFavorites().filter((value) => value !== id)
            : [...readFavorites(), id]
          writeFavorites(rolledBack)
          setFavorites(rolledBack)
        })
      }

      return willAdd
    },
    [token],
  )

  return { favorites, isFavorite, toggleFavorite }
}
